-- GENERATED by `wfj generate` from data/quest/quest-0002.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [2038] = { "Gli attrezzi perduti di Bingles", "Trova e riporta gli attrezzi di Bingles:\n\nChiave Meccanica di Bingles, ⟦Bingles' Screwdriver=Cacciavite di Bingles⟧, ⟦Bingles' Hammer=Martello di Bingles⟧ e ⟦Bingles' Blastencapper=Scoppiabarile di Bingles⟧.", "Come se precipitare nel lago non fosse già abbastanza, i trogg dell'isola qui vicino mi hanno attaccato e rubato gli attrezzi e gli speciali esplosivi Scoppiabarile Blastenheimer. Senza girocottero e senza esplosivi, il movimento non ha speranze!\n\nRiprendi i miei attrezzi e trova i miei esplosivi Scoppiabarile, {name}. Per Gnomeregan!", "{name}! Dove sono le mie cose?!", "Hai reso un grande servizio al movimento, {name}. I trogg e gli gnomi lebbrosi che infestano Gnomeregan sentiranno presto tutto il peso di un assalto aereo gnomesco!", 0xf9774368, 0x792008cf, 0xd09399c8, 0x1dd7bb2d, 0x5ee96793, "....." },
  [2039] = { "Alla ricerca di Bingles", "Trova Bingles Blastenheimer a Loch Modan.", "Abbiamo perso i contatti con Bingles! Era stato mandato in missione di ricognizione sopra Gnomeregan e non fa rapporto da più di una settimana. Me lo sento, è andato a farsi saltare in aria.\n\nL'ultima volta è stato visto sorvolare il lago. Forse puoi indagare tu, {name}.", nil, "Quindi Gnoarn non si fida delle mie capacità di ricognizione? Chissà perché...\n\nLasciamo perdere, ho bisogno del tuo aiuto! No! Il movimento ha bisogno del tuo aiuto!", 0x615905ca, 0x3376ba72, 0x0eb9eb85, nil, 0xe10b4d25, "...m." },
  [2040] = { "Assalto sotterraneo", "Recupera il ⟦Gnoam Sprecklesprocket=Sarchiapone⟧ dalle ⟦Deadmines=Miniere della Morte⟧ e riportalo a Shoni the Shilent, a ⟦Stormwind=Roccavento⟧.", "Gnomeregan è caduta sotto il controllo di quei maledetti trogg! La situazione è grave, ma forse tu puoi aiutarci, {name}.\n\nNel profondo delle ⟦Deadmines=Miniere della Morte⟧ c'è un segatronchi goblin funzionante. Trova quel segatronchi e riporta indietro il suo generatore intatto. Con il generatore del segatronchi potremo dare ai nostri girotrivellatori escavatronici l'energia che serve a sfondare i confini rocciosi sotterranei di Gnomeregan, aprendo la strada a un assalto gnomesco!", "Hai trovato il ⟦Gnoam Sprecklesprocket=Sarchiapone⟧, {name}?", "Ben fatto, {name}. Grazie a te, Gnomeregan è un passo più vicina al giorno della sua liberazione!", 0x80a0cba5, 0xea953ef0, 0x63b95920, 0x9b272279, 0x733d0acf, "....." },
  [2041] = { "Un colloquio con Shoni", "Parla con Shoni the Shilent a ⟦Stormwind=Roccavento⟧.", "Forse... Forse puoi aiutarci nella battaglia per Gnomeregan.\n\nA ⟦Stormwind=Roccavento⟧ troverai il comandante della nostra squadra d'assalto sotterraneo, Shoni the Shilent. Shoni ha bisogno di aiuto con i suoi escavatorizzatori girotrapanomatici.\n\nProbabilmente la troverai in mezzo ai nani di ⟦Stormwind=Roccavento⟧.\n\nBuona fortuna, {name}.", nil, "Porti notizie dal comando centrale?", 0xf9384378, 0xe35660ac, 0xa17f2e67, nil, 0xc9cd2431, "...m." },
  [2078] = { "La vendetta di Gyromast", "Trova il primo ufficiale di Gelkak, il Threshwackonator 4100, e riaccompagnalo da Gelkak.", "Marinaio d'acqua dolce, devi trovare il mio primo ufficiale.\n\nPrendi 'sta chiave, ficcagliela in zucca e riportalo qui a servire il Capitano.\n\nQuei murloc e il loro capo non saranno tanto contenti quando il mio primo ufficiale li avrà tra le grinfie!", "Dov'è il mio primo ufficiale, {name}? Catene e squali per te se non ti sbrighi!", "Arrr... Stai dimostrando di essere più di un lupo di mare codardo, marinaio d'acqua dolce.\n\nIl Capitano potrebbe promuoverti a mozzo del cassero di poppa, se continui così...", 0xd9963931, 0xd2b23f5c, 0x7ec45f79, 0x4a2ccf6d, 0xa5444273, "....." },
  [2098] = { "Il recupero di Gyromast", "Trova i tre pezzi della Chiave di Gelkak e riportali a Gelkak Gyromast.", "La vita del pirata non è facile, marinaio d'acqua dolce. Non è solo saccheggi e grog! Ahimè, la mia nave è affondata proprio al largo per colpa di quei maledetti plesiosauri.\n\nQuel che mi serve è il mio primo ufficiale di nuovo funzionante!\n\nQuando sono finito a riva, la chiave del mio primo ufficiale si è rotta sugli scogli ed è stata arraffata dalle bestiacce di ⟦Darkshore=Rivafosca⟧. Con la coda dell'occhio ho visto alcuni di quei Ragin' Crawler, Ferocious Foreststrider e murloc frugare tra i rottami....", "L'hai trovata la mia chiave rotta, marinaio d'acqua dolce?", "Ohè, lurido lupo di mare! Ce l'hai fatta! Presto il mio primo ufficiale sarà di nuovo funzionante e quelle bestiacce non sapranno cosa le ha colpite!\n\nMmm, hai visto il mio primo ufficiale?", 0xfb8edee7, 0xb52c5a6e, 0x1f7e89e6, 0x5badcb40, 0x8453295d, "....." },
  [2118] = { "Terre appestate", "Cattura un Rabid Thistle Bear vivo e portalo da Tharnariun.\n\nSe non riesci a catturare un Rabid Thistle Bear e perdi la trappola, torna da Tharnariun Treetender e chiedine un'altra.", "Un morbo si diffonde per ⟦Darkshore=Rivafosca⟧ e si impadronisce della mente e del corpo di chiunque tocchi.\n\nI Thistle Bear sono stati colpiti più duramente di tutti da questa piaga. Un tempo bestie nobili, ora sono strumenti di distruzione, rabbiosi e frenetici. Forse ho una cura per questo male.\n\nPorta questa trappola nella foresta e posala a terra. Ogni Rabid Thistle Bear che attraverserà la luce diventerà docile per breve tempo. Una volta docile, l'orso ti seguirà. Riportalo qui, {name}.", "Mi hai portato l'animale malato, {name}?\n\nSe non riesci a far scattare la trappola, non preoccuparti: la ⟦Tharnariun's Hope=Speranza di Tharnariun⟧ è eterna. Se ti serve un'altra trappola, abbandona il compito e torna da me.", "Il nostro lavoro è appena cominciato, {name}. Sei pront<o/a> per il prossimo compito?", 0xfa0a3a70, 0x3807aa6c, 0xe76e9858, 0xcaf47f66, 0xb17abac8, "....." },
  [2138] = { "La purificazione degli infetti", "Ripulisci la foresta da 20 Rabid Thistle Bear e torna da Tharnariun Treetender a ⟦Darkshore=Rivafosca⟧.", "Come temevo, la cura non funziona.\n\nMi rattrista profondamente ordinare la morte di una qualunque creatura della natura, ma gli orsi dei cardi malati e contaminati devono essere abbattuti.\n\nTorna nella foresta e distruggi 20 orsi dei cardi rabbiosi, {name}. Di certo non fermerà la piaga, ma per un po' rallenterà i danni che questi animali stanno facendo alla nostra foresta e ai suoi abitanti.", "Hai portato a termine il tuo compito?", "Hai reso un grande servizio ad Auberdine, {name}, ma il tuo compito non è ancora finito.\n\nTorna da me quando ti sarai riposat<o/a>.\n\n...e {name}, prepara la mente e l'anima ad altro spargimento di sangue.", 0x6f6f3496, 0x02dfdd6a, 0x7195c76b, 0x79783cba, 0x6c182eed, "....." },
  [2139] = { "⟦Tharnariun's Hope=Speranza di Tharnariun⟧", "Trova e uccidi la Den Mother.", "La sopravvivenza del nostro popolo e delle nostre terre ha un prezzo doloroso, {name}.\n\nHai versato il sangue dei servitori della natura; hai abbattuto molti animali malati. La gente di Auberdine è in debito con te, perché il dolore della foresta si è attenuato, anche se solo per un momento.\n\nHo un ultimo compito per te, ma ti avverto: dovrai uccidere ancora. Spero che sia l'ultima volta che ti chiamo, {name}.\n\nIn una caverna a nord-est, vicino a ⟦Bashal'Aran=Bashal'aran⟧, vive la Den Mother. Uccidila.", "Con la Den Mother infetta uccisa, il numero di Rabid Thistle Bear che entrano nelle nostre terre diminuirà. Non perdere tempo, {name}.", "Hai combattuto per Auberdine con coraggio e onore, {name}. Nelle nostre terre dilaniate dalla guerra, morte e disperazione sono all'ordine del giorno. Molti non sapranno affrontare la sfida della vita nella nostra nuova patria e sceglieranno invece di nascondersi nelle loro case o di fuggire nelle terre più fortificate dell'⟦Alliance=Alleanza⟧.\n\nGrazie, {name}. Forse un giorno non lontano combatteremo fianco a fianco come compagni contro un altro nemico.", 0xf10fef91, 0x4766c644, 0xe4256bfb, 0x3c698219, 0x8e54a76e, "....." },
  [2158] = { "Riposo e relax", "Parla con il locandiere Farley alla Lion's Pride Inn.", "Ogni avventuriero dovrebbe riposare quando arriva la stanchezza, e non c'è posto migliore per riposo e relax della Lion's Pride Inn!\n\nIl mio migliore amico, il locandiere Farley, gestisce la Lion's Pride. Se gli dici che ti mando io, forse ti farà i prezzi speciali scontati su cibo e bevande.\n\nPer trovare la Lion's Pride Inn, segui la strada verso sud da qui: non puoi sbagliare!", nil, "Riposo e relax per gli stanchi e gli infreddoliti: è il nostro motto! Prego, siediti accanto al fuoco e riposa le tue stanche ossa.\n\nTi va di assaggiare un po' del nostro ottimo cibo e delle nostre bevande?", 0xf6b2744d, 0xf61951e2, 0xff0677e6, nil, 0x6e2b261e, "...m." },
  [2159] = { "⟦Dolanaar Delivery=Pacco per Dolanaar⟧", "Porta il ⟦Dolanaar Delivery=Pacco per Dolanaar⟧ alla locandiera Keldamyr.", "Salute, giovane {class}. Puoi darmi una mano? Ho un pacco di erbe da consegnare al villaggio di Dolanaar. Ma ho ancora degli affari con i druidi di ⟦Shadowglen=Vallombra⟧ e non posso ancora partire.\n\nPuoi consegnare questo pacco per me? Va portato alla locandiera Keldamyr, alla locanda di Dolanaar. Si trova lungo la strada, a sud.", "Come posso esserti utile, giovane? Sei qui per riposare alla locanda? Ti serve una Pietra del Ritorno?", "Ah sì, la consegna di erbe da ⟦Shadowglen=Vallombra⟧. Peccato che Porthannius non abbia potuto portarla di persona, perché abbiamo molto di cui parlare, io e lui. Ma sono comunque lieta di avere le erbe, e sono lieta che tu sia venut<o/a>.\n\nFinché sei qui, ti prego, riposati. Gli eroi devono mantenere alti la forza e lo spirito, e devono trovare riposo e conforto ogni volta che possono. Perché trascurare la pace del corpo e della mente è una via sicura verso il fallimento.\n\nQuindi... riposa.", 0x1821b05c, 0x63d50e5c, 0xc4d46c8a, 0x4944e9aa, 0x1a7ac861, "....." },
  [2160] = { "Scorte per Tannok", "Consegna la ⟦Crate of Inn Supplies=Cassa di Scorte della Locanda⟧ a Tannok Frosthammer, a Kharanos.", "Ehi! Hai l'aria di una persona avventurosa e in gamba. Se hai intenzione di sfidare il passo, potresti portare un pacco alla locanda di Kharanos?\n\nPensavi di fermarti alla locanda, no? Se riesci a superare il passo, di sicuro vorrai riprendere fiato lì.\n\nComunque, porta questo a Tannok Frosthammer, l'aiutante del locandiere. Io non riesco a passare, e ci vorranno giorni prima che arrivi una scorta di montanari!", "Ciao! Entra, siediti vicino al fuoco e scaldati con un boccale di birra.", "Ah, finalmente, le scorte da Hands! Cominciavo a preoccuparmi: abbiamo avuto ben poche notizie da ⟦Anvilmar=Forgiamara⟧ da quando i trogg hanno invaso il passo.\n\nGrazie per avermele portate, {name}. E ti prego, mettiti comod<o/a>. Devi essere stanc<o/a> dopo il viaggio.", 0x1a599de9, 0xec5c9fbf, 0x3e311c16, 0xd1d47487, 0xe882bc33, "....." },
  [2161] = { "Il fardello di un peone", "Porta il ⟦Ukor's Burden=Fardello di Ukor⟧ al locandiere Grosk, a ⟦Razor Hill=Tranciacolle⟧.", "Scusa? Puoi aiutarmi?\n\nHo qui un carico di cibo. Ho camminato lungo la strada e ho affrontato scorpidi, ragni e di peggio! Ho portato il cibo alla ⟦Valley of Trials=Valle delle Sfide⟧ perché pensavo che ne avessero bisogno e a me piace dare una mano. Ma il cibo non gli serve! Ora devo riportarlo a ⟦Razor Hill=Tranciacolle⟧ e ho paura di tutte le bestie lungo la strada...\n\nPuoi portarlo tu per me? Io sono solo un peone, ma tu sei della stoffa degli eroi. Non hai paura di niente!\n\nPortalo al locandiere Grosk, alla locanda di ⟦Razor Hill=Tranciacolle⟧. Grazie!", "Benvenut<o/a> a ⟦Razor Hill=Tranciacolle⟧!", "Ah, questo è il cibo che Ukor ha portato alla ⟦Valley of Trials=Valle delle Sfide⟧. Non ne avevano bisogno? Be', a quanto pare là gli piace far patire la fame a voi eroi in addestramento. Tempra lo spirito, dicono!\n\nGrazie per aver riportato il cibo. Lo rimetterò sugli scaffali... ma prima lascia che ti offra qualcosa per rifocillarti!\n\nE non dimenticare di riposare qui alla locanda. Sarai anche <un/una> {class} <coraggioso/coraggiosa> e <pronto/pronta> a conquistare il mondo, ma se sei senza energie non farai un granché di buono né a te stess<o/a> né all'⟦Horde=Orda⟧.", 0x7aa7b221, 0xde148f6a, 0xcd75d4e8, 0x4bc9da1c, 0xef14d510, "....." },
  [2178] = { "La dolce vita degli zampalunga", "Riporta 5 ⟦Strider Meat=Carne di Zampalunga⟧ ad Alanndarian Nightsong ad Auberdine.", "Senti che profumino delizioso? È la mia ricetta segreta, {name}: stufato di zampalunga fresco. Una delizia!\n\nTi interesserebbe forse imparare la ricetta?\n\nPrima che te la insegni, dovrai dimostrare di saper tenere testa a quelle bestie.\n\nOra, non pretendo che tu vada a domarne uno e me lo riporti in sella, ma se riesci a ucciderne qualcuno e a portarmi un po' della loro carne succulenta, potrei lasciarmi convincere a svelarti i segreti dello stufato di zampalunga.", "La pentola è vuota e io ho fame! Perché ci metti tanto?", "Fantastico! Assaggialo e dimmi cosa ne pensi, {name}!", 0xfb77df5a, 0xccc0962f, 0x0abb668a, 0xe34f9c3e, 0x42580f7f, "....." },
  [2198] = { "La ⟦Shattered Necklace=Collana Infranta⟧", "Cerca chi ha creato la Collana Infranta per scoprire quanto potrebbe valere.", "Hai trovato una collana annerita, anche se l'ossidazione nasconde una lavorazione intricata e magica. La collana è stata spezzata: dalla montatura sembrano mancare tre gemme. Sul retro della collana c'è l'impronta sbiadita del sigillo cittadino di ⟦Ironforge=Forgiardente⟧. Sotto il sigillo ci sono tre minuscole lettere incise: «TdK».\n\nSe c'è qualcosa da scoprire su questa collana, dovrai conoscerne le origini. Forse il sigillo e le iniziali sono un punto di partenza...", "Hai sbagliato gnomo, amico! Io lì non c'ero! Non puoi provare niente!\n\nAspetta un attimo... chi sei? Ma che... dove l'hai trovata questa collana?", "Sì... sono io il gioielliere che ha fatto questa collana. E non ho l'abitudine di regalare informazioni come se fossero gratis. Le informazioni non sono mai gratis, amico. Se devo aiutarti, prima devi aiutare ME.", 0xb1327827, 0xeeb9407b, 0xb9a1fb6d, 0x0b9a539d, 0x82358beb, "....." },
  [2199] = { "Sapere a pagamento", "Porta 5 Lingotto d'Argento a Talvash del Kissel a ⟦Ironforge=Forgiardente⟧.", "Sono un gioielliere di grande fama qui a ⟦Ironforge=Forgiardente⟧! Be', di fama passata, almeno... Sono caduto in disgrazia per colpa degli imbrogli di un concorrente! In questo mestiere una cattiva reputazione significa la rovina. Il risultato è che mi ritrovo senza un soldo di rame, con un buon nome che al momento è infangato.\n\nVoglio che tu mi porti cinque lingotti d'argento per completare un ordine che ho ricevuto, il primo dopo quella che sembra un'eternità.\n\nPortami quei cinque lingotti d'argento e risponderò alle tue domande sulla collana.", "Hai i cinque lingotti d'argento che ti ho chiesto? Ti racconterò la mia triste storia di sventure sulla collana che ora possiedi... ma solo dopo aver avuto quei lingotti! Dai, aiuta uno gnomo, no?", "Per me sei a posto; non m'importa cosa dicono tutti gli altri... Scherzo, scherzo! Davvero, grazie, amico mio.\n\nLa collana che hai è una delle mie creazioni migliori, ma le mancano tre gemme che aiutano a legarvi il potere magico. L'ho creata tempo fa per un paladino. Si era imposto la missione di ripulire dalla «corruzione malvagia» uno scavo nelle ⟦Badlands=Maleterre⟧ chiamato Uldaman.\n\nBe'... quel paladino è morto a Uldaman, e quello è stato solo l'inizio dei miei guai.", 0x99934f46, 0x01df1a41, 0xf6b25bc5, 0x5573d0cc, 0x592dece0, "....." },
  [2200] = { "Ritorno a Uldaman", "Cerca a Uldaman indizi su dove si trovi ora la collana di Talvash. Il paladino ucciso di cui ha parlato è stato l'ultimo ad averla.", "Un mio concorrente ha messo in giro la voce che la mia collana ha maledetto il paladino. Inutile dire che nessuno vuole comprare oggetti maledetti da un gioielliere.\n\n{name}, ti propongo un patto: trova le gemme e io rimetterò insieme la collana, a patto che tu vada in giro a dire che io NON faccio oggetti maledetti!\n\nProva a cercare indizi a Uldaman; magari guarda se il corpo del paladino è laggiù, visto che è lui l'ultimo che sappiamo averla avuta! Quando trovi le gemme dovresti usare questo: ti permetterà di contattarmi qui a ⟦Ironforge=Forgiardente⟧.", nil, "Resti di un paladino: leggendo il diario si scopre che, dopo molti sforzi, il paladino aveva individuato dove si trovavano tutte e tre le gemme mancanti:\n\nI nani Forgiascura hanno nascosto il rubino nella loro zona barricata, mentre combattevano contro i trogg per il controllo di Uldaman.\n\nI trogg hanno nascosto il topazio in un'urna vicino ad alcuni insoliti abitanti di Uldaman: nani dell'⟦Alliance=Alleanza⟧!\n\nInfine, l'anziano dei trogg in persona si è preso lo zaffiro.", 0x0a4fff55, 0x2968a0a2, 0x8111f254, nil, 0x4fa0e3d8, "...m." },
  [2201] = { "Trova le gemme", "Trova il rubino, lo zaffiro e il topazio sparsi per Uldaman. Quando li avrai, contatta Talvash del Kissel a distanza usando la ⟦Phial of Scrying=Fiala della Chiaroveggenza⟧ che ti ha dato.\n\nDal diario sai che...\n\n* Il rubino è stato nascosto in un'area barricata dei Forgiascura.\n\n* Il topazio è stato nascosto in un'urna in una delle aree dei trogg, vicino ad alcuni nani dell'⟦Alliance=Alleanza⟧.\n\n* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.", "Il diario del paladino ha fornito forse gli unici indizi che Uldaman concederà sul luogo in cui si trovano le gemme della collana. Se gli scritti del paladino sono ancora attendibili, bisognerà vedersela con i nani Forgiascura e con i trogg che si contendono il sito degli scavi.\n\nForte di queste conoscenze, la ricerca delle gemme comincia sul serio. Una volta trovate tutte le gemme, bisognerà avvisare Talvash a ⟦Ironforge=Forgiardente⟧ tramite la ⟦Phial of Scrying=Fiala della Chiaroveggenza⟧, come da sue istruzioni.", "L'immagine di Talvash si mette a fuoco nell'acqua della scodella della chiaroveggenza.\n\n«Accidenti, sei ancora viv<o/a>! Sei riuscit<o/a> a trovare le gemme? Sei davvero <il/la> <salvatore/salvatrice> della mia reputazione che speravo? Ti prego, dimmi che non hai sprecato una carica della fiala solo per fare due chiacchiere: quegli affari NON costano poco, e sono già in gravi ristrettezze economiche.", "Sì, sono proprio le tre gemme. Ottimo lavoro! Purtroppo il tuo compito non è ancora del tutto finito.\n\nNo, non sto cercando di fregarti, {class} sciocchin<o/a>. Qui si tratta di creare gioielli magici, gioielli della qualità di Talvash del Kissel! Ti serve una fonte di energia potente per dargli un po' di grinta. E quella collana non ha più grinta da dare.", 0xb51d5b0d, 0xf4b144bc, 0x4c6f3add, 0x60210ab2, 0x8762b2b9, "....." },
  [2202] = { "Reagenti da Uldaman", "Porta 12 Fungo Cappella Magenta a Jarkal Mossmeld a Kargath.", "Ho sentito parlare di una pianta scoperta da poco, i cosiddetti funghi cappella magenta. Crescono a grappoli, nel profondo del sito di scavo di Uldaman; forse si trovano anche altrove, ma per ora è l'unico posto che conosco. Voglio studiarne il possibile uso in alchimia, ed è qui che entri in gioco tu.\n\nTrova i grappoli di cappelle magenta e portami una dozzina di funghi. Ti avverto: se urtati, i grappoli possono sputare spore velenose.\n\nFallo per me, e ti preparerò una dose di uno dei miei famosi elisir ristoratori!", "Hai trovato i funghi cappella magenta che mi servono per il mio lavoro alchemico? Niente funghi, niente ricompensa!", "Ben fatto, {name}, hai dimostrato ancora una volta il tuo valore! Questi funghi saranno uno studio interessante, puoi scommetterci.\n\nE ora, come promesso, goditi un assaggio di uno dei miei intrugli ristoratori più potenti, dalla mia scorta personale...\n\nSe sei <un/una> alchimista espert<o/a>, forse potremmo concludere qualche altro affare. In ogni caso, ti ringrazio per il tuo aiuto!", 0xec9c87f2, 0xb16c00d4, 0xf40372d4, 0x3dc33ca7, 0x81d175bc, "....." },
  [2203] = { "Reagenti dalle ⟦Badlands=Maleterre⟧ II", "Usa le Ampolle Taumaturgiche Vuote sui draghi Scorched Guardian delle ⟦Badlands=Maleterre⟧. Quando saranno piene, portale a Jarkal Mossmeld, a Kargath.", "Mi sei stat<o/a> di grande aiuto, {class}. Vorrei ricompensarti con la ricetta stessa dell'infuso che ti ho dato prima... ma dovrei chiederti un compito piuttosto pericoloso. Ascolta la mia richiesta.\n\nQuesta cassetta contiene tre ampolle taumaturgiche vuote: sono intrise di un'aura di sintonia che prosciugherà il sangue di un drago guardiano riarso. Usarne una sulla bestia la farà infuriare parecchio, quindi sei avvisat<o/a>. Quando le avrai riempite tutte e tre, portamele.\n\nFallo, e la ricetta sarà tua.", "Hai usato le ampolle per procurarmi il sangue di drago guardiano riarso che mi serve? Sì, lo so, è un compito pericoloso... ma la ricetta del mio infuso ristoratore aspetta il tuo successo. Rischio e ricompensa, amico mio... rischio e ricompensa...", "Da alchimista ad alchimista, ti saluto. Ecco, prendi questa ricetta e imprimila nella memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni.", 0x883768bc, 0x12a43ea3, 0x37649b9e, 0x0cf00f74, 0xb7d7a9b7, "....." },
  [2204] = { "Restaurare la collana", "Ottieni una sorgente energetica dal costrutto più potente che riesci a trovare a Uldaman e consegnala a Talvash del Kissel, a ⟦Ironforge=Forgiardente⟧.", "Ti servirà un po' di \"sprint\" per la collana, e Uldaman è probabilmente il posto migliore dove trovarlo, a dire il vero. Mi sa che là dentro gironzolano parecchi costrutti, no? Be', fai fuori il costrutto più grosso e cattivo del posto e prendigli la sorgente energetica! Sono quasi sicuro di poterla fondere nella collana.\n\nSenza quella sorgente energetica, riparare la collana sarà impossibile. Torna da me qui a ⟦Ironforge=Forgiardente⟧ quando l'avrai, e ti sistemeremo tutto!", "Non ti sei nemmeno fermat<o/a> a darti una ripulita dopo aver lasciato Uldaman, vero? Sei venut<o/a> dritt<o/a> qui, al diavolo il tanfo di sotterraneo che ti porti dietro. Be', speriamo che questa visita sia solo maleodorante, e non pure inutile.\n\nHai la sorgente energetica per la collana?", "Ma guarda un po': sono proprio contento di vedere te e questa sorgente energetica sani e salvi. Mi ci vorrà un momento per fondere magicamente la sorgente energetica con la collana, ora che le gemme ci sono tornate dentro. Una volta finito, però, la collana sarà tua!\n\nSei emozionat<o/a>, vero? Tutt<o/a> fremente d'attesa? Ora, dove ho messo quel focus per incantesimi...", 0xd9740d79, 0xa02feecf, 0x905848a6, 0xc5dc9fc2, 0xf81ff10a, "....." },
  [2205] = { "In cerca del SI: 7", "Consegna il pacco di Keryn Sylvius a mastro Mathias Shaw, nella caserma di ⟦Stormwind=Roccavento⟧.", "Il distintivo? Oh, non è niente, pivell<o/a>: niente che tu possa gestire, comunque. A giudicarti dall'aspetto, direi che Mathias ti scambierà per <il/la> <ragazzo/ragazza> che consegna il formaggio, invece che per <un/una> ver<o/a> <ladro/ladra>. In ogni caso, mi è stato assegnato un incarico e ho promesso di portarlo a termine.\n\nA proposito, consegna questo pacco a Mathias e forse ti affiderà un compito o due.\n\nDatti una mossa.", "Posso aiutarti, {class}?", "Mi hai trovato... e a giudicare dal tuo aspetto, direi che la corsa e la ricerca che ne è seguita ti abbiano messo a dura prova, sia nella mente sia nel corpo.\n\nVuoi che Renzik ti mostri la strada per una locanda o sei pront<o/a> per un po' di lavoro?", 0xcaa7a9f9, 0x07f738a1, 0xfb528bff, 0x01686e7d, 0xde7424bd, ".....", nil, nil, 0x454725db, nil, nil },
  [2206] = { "Arraffa e scappa", "Trova il Defias Dockmaster e recupera lo Shipping Schedule per mastro Mathias Shaw.", "I nostri agenti sul campo riferiscono un'intensa attività dei Defias a sud di ⟦Goldshire=Borgodoro⟧. Secondo i rapporti, i Defias si sono impadroniti del ⟦Jerod's Landing=Molo di Jerod⟧ e ora lo usano per contrabbandare grandi quantità di merce da ⟦Redridge=Crestarossa⟧ alle ⟦Westfall=Marche Occidentali⟧.\n\nHo bisogno che ti infiltri nella casa del molo e mi porti quel registro delle spedizioni, {name}. Probabilmente lo troverai in fondo alle tasche del Dockmaster.\n\n...e {name}, se dovessi essere scopert<o/a>, l'⟦SI:7=IR:7⟧ negherà di sapere alcunché della tua esistenza.", "Il tuo tempo da mortale si consuma a ogni istante che sprechi a bighellonare in caserma, {class}.", "Sono sbalordito... Sbalordito che Keryn abbia finalmente trovato una recluta che potrebbe avere la stoffa di un vero ladro. Prendi questa lama, {name}. Verrà il giorno in cui sarai chiamat<o/a> di nuovo a servire l'⟦SI:7=IR:7⟧. Affina le tue abilità, tieni gli occhi aperti e quella lama affilata.\n\nNon ci vedrai arrivare, ma te ne accorgerai quando saremo lì...", 0x1787987c, 0x494cbf92, 0xb285531c, 0xcd220e78, 0x0bc8224c, "....." },
  [2218] = { "La via della salvezza", "Parla con Hulfdan Blackbeard a ⟦Ironforge=Forgiardente⟧.", "Un'altra anima persa in cerca di una guida, eh? Immagino tu voglia trovare uno scopo, il tuo scopo. L'ho visto mille volte: un altro eroe in cerca di lavoro.\n\nBe', oggi è il tuo giorno fortunato, amico. Hogral ha la cura per il tuo male.\n\nEcco cosa fai: prendi questa strada fino a ⟦Ironforge=Forgiardente⟧ e raggiungi la Forlorn Cavern. Lì, trova la gilda dei ladri e parla con Hulfdan Blackbeard. Ti metterà sulla via della salvezza.", nil, "Così ti credi una vera canaglia? Destinat<o/a> a essere <uno/una> dei pochi eletti di Blackbeard, un ufficiale dell'Hidden Circle?\n\nSolo un furfante buono a nulla penserebbe così bene di sé.\n\nÈ proprio quello che cerchiamo! Benvenut<o/a> a bordo, {name}!", 0x7deeb917, 0xc16240a1, 0x238604cf, nil, 0x3b3483ab, "...m." },
  [2238] = { "Un semplice sotterfugio", "Trova Onin MacHammar nei pressi di Gnomeregan.", "Vedi, il re sta sventrando la cava per estrarne minerali e gemme. Più ricchezze di quante un nano dovrebbe vederne in dieci vite.\n\nL'Hidden Circle ha dei valori, {name}. Noi diamo valore alle cose di valore. Capisci?\n\nOra, noi pensiamo che il re dovrebbe spartire un po' di quel bottino, ma non vogliamo che il vecchio «Stinkbeard» sappia che lo sta spartendo... se capisci cosa intendo.\n\nAbbiamo bisogno che tu parli con Onin MacHammar laggiù, vicino a Gnomeregan, e che riporti un rapporto. Quel nano furbo si è nascosto tra i lebbrosi. Fa' attenzione.", nil, "Ssst! Abbassa la voce, pezzo di idiota. Ci sentiranno.", 0xc34a099a, 0xba2a3a79, 0xad153087, nil, 0xab2bb692, "...m." },
  [2239] = { "⟦Onin's Report=Rapporto di Onin⟧", "Riporta il ⟦Onin's Report=Rapporto di Onin⟧ a Hulfdan, a ⟦Ironforge=Forgiardente⟧.", "La cava? Già, vedo quei mostruosi carri armati a vapore corazzati passare da questo posto quasi ogni giorno.\n\nI miei contatti a est mi dicono che il carro parte da ⟦Ironforge=Forgiardente⟧, fa un carico alla ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧, si ferma a Kharanos per fare rifornimento e poi, per qualche dannato motivo, fa il giro lungo passando da Gnomeregan, prima di arrivare a ⟦Ironforge=Forgiardente⟧ per scaricare la spedizione.\n\nÈ tutto nel rapporto, {race}. Portalo a Hulfdan, così potrà pianificare la prossima mossa.", "Ti è piaciuto il fetore degli gnomi lebbrosi? Lo chiedo solo perché hai un sorriso da matto stampato in faccia.\n\nChe notizie porti da Onin?", "Il giro lungo? Per la mia barba!\n\nHai fatto un buon lavoro, {name}. Prendi questo pugnale e vattene. Il Circolo ti chiamerà di nuovo quando il passo tre sarà pronto per essere messo in atto.\n\nQual è il passo tre? Viene subito dopo il passo due: io che ti pianto lo stivale nel didietro.\n\nInteressat<o/a>?", 0xfee6746a, 0xb2b73a1a, 0x6d453b17, 0x7416d656, 0x6c9c93b3, "....." },
  [2240] = { "La camera nascosta", "Leggi il diario di Baelog, esplora la camera nascosta, poi fai rapporto al prospettore Stormpike.", "E ora, il compito che ci attende.\n\nC'è una camera segreta, la Chamber of Khaz'mul, che va esplorata. Il problema è che la camera si trova dietro un'enorme porta sbarrata! Per fortuna io so come aprirla.\n\nHo descritto tutto nel mio diario, qui sul tavolo. Io e il mio gruppo siamo bloccati qui per ora... quindi tu, {name}, devi trovare la Chamber of Khaz'mul per noi!\n\nLeggi il mio diario, esplora la camera, poi fai rapporto al prospettore Stormpike alla ⟦Explorers' League=Lega degli Esploratori⟧ di ⟦Ironforge=Forgiardente⟧.", "Hai qualcosa da riferire?", "Hai visto la Chamber of Khaz'mul? Straordinario! Baelog era sicuro che esistesse, ma devo ammettere che avevo i miei dubbi.\n\nGrazie, {name}. Con un po' di fortuna la tua scoperta spingerà i nostri capi a rinnovare gli sforzi per riconquistare Uldaman. E se mai tornerà sotto il controllo di ⟦Ironforge=Forgiardente⟧, i segreti della Chamber of Khaz'mul saranno nostri!", 0x715ec1d2, 0x426bb2d5, 0xd19acc6b, 0x0c101615, 0x1bbdd389, "....." },
  [2241] = { "La mela cade", "Porta la ⟦Jannok's Rose=Rosa di Jannok⟧ a Syurna, a Darnassus.", "Dicono che sono «cotto», qualunque cosa significhi.\n\nCerto, passo ogni momento da sveglio a pensare a Syurna. Certo, casa mia è piena di quadri e disegni di Syurna. Certo, spesso passo giorni senza mangiare, dormire o bere, mentre mi struggo per l'amore che avremmo potuto avere. È così sbagliato?\n\nE ora non vuole vedermi! ME! Ho provato a mandarle dei messaggi, ma non parla nemmeno con nessuno che non sia un ladro.\n\nPotresti consegnarle questo fiore? Non dimenticare di dirle che è da parte di Jannok.", "Oh, ma che meraviglia. Hai portato i fiori per il tuo stesso funerale.", "Se avessi conservato ogni fiore che quell'idiota di Jannok mi ha mandato, avrei avuto abbastanza per aprire un negozio. Comunque, sembra che l'ultimo messaggero di Jannok possa rivelarsi utile.\n\nTi interessa un po' di lavoro, {class}?", 0x1e34b4e5, 0x539618ee, 0xb5594b87, 0x9279e6d4, 0x640f88b7, "....." },
  [2242] = { "Il destino chiama", "Trova Sethir l'Antico e riporta a Syurna tutti gli indizi che scopri.", "Crediamo che esista un essere in grado di aiutarci a capire cosa sta succedendo alle foreste di Teldrassil. Purtroppo, convincere quella creatura a collaborare si è rivelato disastroso.\n\nSi nasconde su un ramo ai margini dell'Oracle Glade. Tutti quelli che finora si sono avvicinati al satiro, con la forza o con la diplomazia, hanno trovato la rovina. Forse la furtività è la risposta, {name}.\n\nScopri cosa porta con sé Sethir l'Antico nelle sue sacche e torna a riferirmelo.", "Hai qualcosa da riferire su Sethir l'Antico, {name}?", "Sono brutte notizie, {name}. Sembra che il morbo che ha colpito le foreste e i fiumi di ⟦Darkshore=Rivafosca⟧ abbia cominciato a contaminare la nostra casa.\n\nCi hai servito bene, ma qui non c'è altro che tu possa fare. Prendi questa lama come ricompensa per il tuo servizio a Teldrassil.", 0x8c35f2ae, 0xe9faceef, 0xccf34b01, 0x274bca56, 0x1dda5b8b, "....." },
  [2258] = { "Reagenti delle ⟦Badlands=Maleterre⟧", "Porta 5 Stomaco di Condor, 10 Zanna di Coyote delle Rupi e 5 Scheggia Elementale di Roccia a Jarkal Mossmeld a Kargath, nelle ⟦Badlands=Maleterre⟧.", "{name}, mi farebbe comodo il tuo aiuto, se te la senti. Sono un alchimista di una certa fama, e cerco aiuto per procurarmi alcuni reagenti che si trovano nelle ⟦Badlands=Maleterre⟧.\n\nPer rifornire le mie scorte mi servono: cinque stomaci di condor, dieci zanne di coyote delle rupi e cinque schegge elementali di roccia. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei tipo da combattere, trova degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta. Che vuoi fare?", "Hai già preso le cose che mi servono? Non ti pagherò finché non mi porti quei reagenti.", "Ah, ben fatto! Queste dovrebbero bastarmi almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ci sono altri reagenti che mi servirebbero. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma ne varrà la pena, se vorrai aiutarmi di nuovo.\n\nMagari con qualcosa di più di qualche moneta luccicante, eh?", 0xaca0069d, 0xd99e4eb2, 0x58ee6bec, 0x5be9782d, 0xdcc1d162, "....." },
  [2259] = { nil, "Contatta Erion Shadewhisper a Darnassus.", "Non preoccuparti, {name}, non ti sto mandando da Syurna. Erion richiede la tua presenza all'⟦Cenarion Enclave=Enclave Cenariana⟧. Affrettati!", nil, "È tempo di allargare i tuoi orizzonti, {race}: il mondo ti aspetta.", 0x372c4f19, 0x1eb27f12, 0x7bffcd48, nil, 0x1d5a0e27, "e..m." },
  [2260] = { "La richiesta di Erion", "Raggiungi ⟦Stormwind City=Roccavento⟧ e chiedi consiglio a Renzik \"The Shiv\".", "La voce delle tue imprese si è diffusa ovunque, {name}. Tanto che i servizi segreti di ⟦Stormwind=Roccavento⟧ hanno chiesto di te per nome.\n\nIl viaggio è faticoso e non privo di pericoli, ma l'occasione di addestrarsi con l'⟦SI:7=IR:7⟧ non va presa alla leggera.\n\nTi aspetta un mondo nuovo, {name}. Raggiungi Old Town, a ⟦Stormwind=Roccavento⟧, e parla con Renzik \"The Shiv\" al quartier generale dell'⟦SI:7=IR:7⟧.", nil, "Hai risposto alla chiamata dell'IR:7, {name}, e hai viaggiato da terre lontane per unirti alle nostre file; tuttavia, hai ancora molto da imparare.", 0x01bdb2d2, 0x370fd4f0, 0x6d9f7c62, nil, 0xd5283d8b, "...m." },
  [2278] = { "I dischi di platino", "Parla con il guardiano di pietra e scopri quale antico sapere custodisce. Dopo aver appreso il sapere che ha da offrire, attiva i Discs of Norgannon.", "Al centro di questa camera del tesoro ci sono quattro enormi dischi di platino, ognuno adorno di numerosi sigilli di origine sconosciuta. Toccarli ti fa formicolare la mano. Subito dopo, si materializza l'immagine di un grande guardiano di pietra.\n\n\"Salute. Sono un custode del sapere. La sintesi dei Terrigeni compiuta dai Creatori è stata registrata e conservata qui, per questo mondo, nei Discs of Norgannon.\"\n\nHai scoperto una ricchezza di sapere su questo mondo mai rivelata prima!", "La voce del guardiano di pietra sembra risuonare nel profondo del tuo essere:\n\n\"Devi prima soddisfare il prerequisito di assimilazione dei dati dei Discs of Norgannon; una volta soddisfatto questo requisito, ti sarà permesso ottenere una versione portatile dei dati conservati. Assicurati di aver esplorato a fondo le informazioni di questo archivio.\"", "Seguendo le istruzioni del guardiano di pietra, accedi di nuovo ai Discs of Norgannon, ora che hai appreso la storia dei Terrigeni, dei trogg e dei nani. Dall'interno dei dischi si sente un ronzio debole e breve. Poi il guardiano di pietra parla:\n\n\"Ora i dischi sono stati sintetizzati. Accedi ancora una volta ai Discs of Norgannon per ricevere la tua copia personale.\"", 0xd5650943, 0x2e1dcb31, 0xfcf9c537, 0x065395e0, 0xadf3d52f, "....." },
  [2279] = { "I dischi di platino", "Porta la versione in miniatura dei Discs of Norgannon alla ⟦Explorers' League=Lega degli Esploratori⟧ a ⟦Ironforge=Forgiardente⟧.", "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano rumore stridente.\n\nIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!\n\nSenza dubbio un oggetto del genere sarebbe preziosissimo per chi si interessa della storia antica di Azeroth. La ⟦Explorers' League=Lega degli Esploratori⟧ di ⟦Ironforge=Forgiardente⟧ è un gruppo del genere, noto in tutta l'⟦Alliance=Alleanza⟧; forse potrebbero farne buon uso.", "Sì, posso aiutarti in qualcosa? Ti assicuro che in questo momento sono molto occupato. Se però si tratta di una questione di grande importanza per la ⟦Explorers' League=Lega degli Esploratori⟧, allora sono tutt'orecchi!", "Cos'hai lì... oh, cielo. Dove l'hai trovato?\n\nNo, davvero?\n\nHai parlato con chi, di cosa?\n\nNO, DAVVERO?!\n\n<Mio/Mia> car<o/a> {class}, potresti aver appena fatto la scoperta archeologica dell'anno! Per gli Dei, ma chi voglio prendere in giro, la scoperta del secolo! Se questi dischi sono ciò che penso, potrebbero essere proprio la chiave che cercavamo! Potrebbero dimostrare una volta per tutte la legittimità della creazione incantata dei nani!", 0xd5650943, 0x7540c2d4, 0x73154522, 0x7f85817c, 0xac58b5d8, "....." },
  [2280] = { "I dischi di platino", "Porta la versione in miniatura dei Discs of Norgannon a uno dei saggi di ⟦Thunder Bluff=Picco del Tuono⟧.", "Toccare di nuovo i Discs of Norgannon ti fa formicolare la mano. Questa volta, però, dall'interno dei dischi si sente uno strano rumore stridente.\n\nIl tuo zaino diventa all'improvviso più pesante di prima. Dentro scopri una versione in miniatura dei dischi!\n\nSenza dubbio un oggetto del genere sarebbe preziosissimo per chi si interessa della storia antica di Azeroth. I saggi di ⟦Thunder Bluff=Picco del Tuono⟧ sono storici di questo tipo, noti in tutta l'⟦Horde=Orda⟧; forse potrebbero farne buon uso.", "Sì, giovane, ti vedo entrare nella mia tenda con passo deciso... con determinazione nel tuo intento. Cerchi il mio consiglio su una questione di grande importanza per l'⟦Horde=Orda⟧? Forse desideri che ti venga svelato un mistero dell'universo?", "Allora, cosa sono questi?\n\nNotevole, giovane! In questi dischi percepisco segreti che la terra ha custodito gelosamente per molti anni. Sei stat<o/a> molto saggi<o/a> a portarli qui da me.", 0xd5650943, 0xc11f337c, 0x9fd11efc, 0x69e7ec1f, 0x54c80929, "....." },
  [2281] = { "Appuntamento a ⟦Redridge=Crestarossa⟧", "Avventurati fino a ⟦Lakeshire=Borgolago⟧, nelle ⟦Redridge Mountains=Montagne Crestarossa⟧, e parla con Lucius.", "Mandarti sul campo adesso sarebbe un suicidio. A Renzik non serve un altro ladro morto sulla coscienza. Ma non agitarti, {name}: Renzik ti metterà al passo.\n\nRaggiungi le ⟦Redridge Mountains=Montagne Crestarossa⟧ e parla con un collaboratore dell'⟦SI:7=IR:7⟧ di nome Lucius. Lo troverai a bighellonare sui moli di ⟦Lakeshire=Borgolago⟧ con gli altri fannulloni loschi.", nil, "Ah, hai le dita un po' grosse, eh? Non preoccuparti, {name}, ho trasformato ladruncoli più inutili di te in ladri esperti.", 0x1179ca1d, 0x8ce09cc7, 0xde207c62, nil, 0xf1b6dc03, "...m." },
  [2282] = { "⟦Alther's Mill=Segheria di Alther⟧", "Apri il Lucius's Lockbox, recupera l'⟦Token of Thievery=Emblema del Ladro⟧ e riportalo a Lucius, a ⟦Lakeshire=Borgolago⟧.", "Addestriamo ladri qui da anni! Del resto, non tutte le canaglie nascono con la grazia e la finezza del vecchio Lucius.\n\nPiù su, oltre la strada, troverai la ⟦Alther's Mill=Segheria di Alther⟧. Lassù ho un forziere con dentro una cosa importante. Va' a prendermela! Riporta quell'emblema e riceverai il tuo ⟦Certificate of Thievery=Attestato di Ladro⟧!", "Ho dimenticato di dirti degli orchi?\n\nHo sentito che ficcano il naso lassù, vicino alla segheria.", "L'hai aperto, eh? Bel lavoro, {name}.\n\nSe adesso muori, possiamo stare tranquilli sapendo che è stato per la tua stupidità e non per inesperienza.", 0xe7ba8f99, 0x26100448, 0xb5640ee8, 0xe82c551e, 0x0465ee25, "....." },
  [2283] = { "Recupero della collana", "Cerca una collana preziosa negli scavi di Uldaman e portala a Dran Droffers a Orgrimmar. La collana potrebbe essere danneggiata.", "Abbiamo un lavoro per te, sempre che tu abbia il fegato di farlo!\n\nNel cuore delle ⟦Badlands=Maleterre⟧ ci sono gli scavi di Uldaman. Abbiamo sentito la storia di un paladino idiota morto lì di recente. E ci interessa perché aveva addosso una collana preziosissima. Pare che abbia tre grosse gemme: un rubino, uno zaffiro e un topazio.\n\nIl punto è questo: la vogliamo, e la paghiamo A PESO D'ARGENTO. Potrebbe essere danneggiata, ma poco importa: sistemeremo noi qualunque graffio abbia.", "Allora, ce l'hai la collana? Non vedrai un soldo di rame da noi se non hai quella collana!", "Mmm, roba da recupero! Sento l'odore della collana da qui. Ora diamo un'occhiata a questa bellezza...\n\nEhi, cosa credi di fare? A questa collana mancano le gemme! Pensavi che non ce ne saremmo accorti? Persino Malton si accorgerebbe che le gemme non ci sono.\n\nBe', forse non le hai rubate tu... ma questa collana non vale niente senza quelle gemme! Il tuo lavoro qui non è finito, neanche lontanamente!", 0xd7ab4e5f, 0xfc569f24, 0x086a8e78, 0x1e95a75b, 0x9025e8b5, "....." },
  [2284] = { "Recupero della collana, tentativo 2", "Trova un indizio su dove si trovino le gemme nelle profondità di Uldaman.", "Com'è vero che Malton è uno scemo, quelle gemme sono ancora da qualche parte a Uldaman. Dovrai tornarci e cercarle.\n\nCome ho detto prima, se le nostre informazioni sono giuste, con la collana vanno un rubino, uno zaffiro e un topazio. Trovali e incastonali nella collana.\n\nQuanto a dove siano le gemme, chi lo sa? Magari avrai fortuna e troverai il cadavere del Paladino. Se non l'hanno già ripulito, forse le ha ancora addosso.", nil, "Sembra che tu abbia trovato i resti del paladino di cui parlava Dran. Frugando tra i resti scopri quello che sembra il suo diario. Il libro è in pessime condizioni: il sangue secco ha macchiato gran parte del testo. Quello che riesci a leggere, però, è incomprensibile; per quanto ne sai, è scritto nella lingua natia degli umani.\n\nDovrai far tradurre il libro se vuoi ricavarne qualche informazione.", 0x8c69a332, 0x9db927d1, 0xd72891ee, nil, 0xc5cbc3fd, "...m." },
  [2298] = { "Un'estorsione reale", "Raggiungi ⟦Stormwind=Roccavento⟧ e cerca Renzik \"The Shiv\".", "Allora, eravamo lì lì per cominciare a pianificare la fase III, quando un paio di zucconi di Magni piombano qua dentro a blaterare di un qualche colpo e ad arrestare alcuni dell'Hidden Circle.\n\nBeh, nessuno mette i ferri al vecchio Blackbeard! La discussione s'è fatta pesante e animata e, chissà come, è saltato fuori il tuo nome!\n\nIl mio consiglio? Prendi il primo grifone da ⟦Ironforge=Forgiardente⟧ e vai a ⟦Stormwind=Roccavento⟧. Raggiungi Old Town e lì parla con un mio vecchio amico, Renzik \"The Shiv\".", nil, "Fa sempre piacere avere uno dei ladri di Hulfdan tra le nostre file!", 0xd942bb73, 0xbbb8bc4a, 0x640cf402, nil, 0x4704075e, "...m." },
  [2299] = { "Da Hulfdan!", "Raggiungi ⟦Ironforge=Forgiardente⟧ e parla con Hulfdan Blackbeard.", "Dove sei finit<o/a>, {name}? Hulfdan ti sta cercando dappertutto. Pensavamo che il re ti avesse messo ai ferri.\n\nVai a ⟦Ironforge=Forgiardente⟧ il prima possibile e parla con Hulfdan!", nil, "Abbassa la voce, {name}, le guardie potrebbero sentirti.", 0x612d5545, 0x995810c1, 0x7e2c7b3a, nil, 0x03d4865c, "...m." },
  [2300] = { "⟦SI:7=IR:7⟧", "Raggiungi ⟦Stormwind=Roccavento⟧ e cerca Renzik \"The Shiv\".", "Renzik ti cercava, recluta.\n\nAl posto tuo non farei aspettare il vice di Mathias.", nil, "Sei pront<o/a> a metterti al lavoro o ti serve un pisolino prima di cominciare?", 0x0b3264b7, 0xbbb8bc4a, 0xf9063657, nil, 0x6f885d66, "...m." },
  [2318] = { "La traduzione del diario", "Trova qualcuno che possa tradurre il diario del paladino. Il luogo più vicino dove potrebbe esserci qualcuno è Kargath, nelle ⟦Badlands=Maleterre⟧.", "Sei a un punto morto, in un certo senso: sai che dovrai far tradurre il libro in una lingua che tu possa capire. Di certo al mondo ci sono parecchie persone in grado di farlo; il luogo più vicino dove potrebbe esserci qualcuno capace, però, è l'avamposto di Kargath, nelle ⟦Badlands=Maleterre⟧. Forse è un buon punto da cui cominciare.", nil, "Potente {class}, so cosa fai qui nelle ⟦Badlands=Maleterre⟧. So che cerchi il mio dono delle lingue. Vuoi i pezzi di quella collana che hai trovato a Uldaman.\n\nSorpres<o/a>? Non esserlo: è il mio lavoro sapere queste cose. Piuttosto, parliamo di cosa farai in cambio di un diario tradotto. Fidati: sono l'unico che troverai in grado di tradurlo.\n\nMeglio ancora, lascia che ti faccia un'offerta migliore di quella di Dran Droffers, che ti permetterà comunque di portare a termine il tuo accordo con loro. Ora ti interessa, sì?", 0x0fba366a, 0x3f90420d, 0x7bf166bf, nil, 0xd391c145, "...m." },
  [2338] = { "La traduzione del diario", "Presta la collana a Jarkal. In cambio, ti tradurrà il diario.", "Droffers and Son Salvage non sono abbastanza svegli da ridare la magia alla collana, ma io sì. Voglio solo studiare la collana per imparare a farne di simili. Per farlo, mi serve la tua collana. Prestamela, e in cambio del tempo che avrò per studiarla ti tradurrò il diario. Mentre tu cerchi le gemme, dovrei avere abbastanza tempo per imparare ciò che mi serve.\n\nÈ un patto semplice, e nessun altro ne saprà niente. Che vuoi fare?", "Ci hai pensato, vero? Sei <un/una> {class} in gamba se accetti questo patto: tu e io avremo ciò che vogliamo entrambi, e Droffers and Son Salvage crederanno di avere ciò che vogliono loro.", "Riconosci un buon affare quando lo vedi: sapevo di poter contare su di te.\n\nCi vorrà solo un momento, il tempo di lanciare un incantesimo per tradurre in fretta la lingua degli umani in una forma che tu possa capire. Sono un troll di parola; chiedi a chiunque nell'⟦Horde=Orda⟧ di Jarkal Mossmeld. Ora, cominciamo...", 0x0fba366a, 0x71c6ceb6, 0x1de510c3, 0x7b4404a4, 0x721e2a04, "....." },
  [2339] = { "Trova le gemme e la sorgente energetica", "Recupera tutte e tre le gemme e una sorgente energetica per la collana a Uldaman, poi portale a Jarkal Mossmeld, a Kargath. Jarkal crede che una sorgente energetica si possa trovare sul costrutto più forte di Uldaman.\n\nDal diario sai che...\n\n* Il rubino è stato nascosto in un'area barricata dei Forgiascura.\n\n* Il topazio è stato nascosto in un'urna in una delle aree dei trogg, vicino ad alcuni nani dell'⟦Alliance=Alleanza⟧.\n\n* Lo zaffiro se l'è preso Grimlok, il capo dei trogg.", "Ecco il diario, tradotto perché tu possa leggerlo per conto tuo. In sostanza dice che i nani hanno nascosto il rubino, i trogg hanno nascosto il topazio e un trogg di nome Tetrok ha lo zaffiro.\n\nSenti: ti servirà una sorgente energetica per far funzionare di nuovo la collana. Dran Droffers non lo sa. Per trovarne una, ecco cosa farei io: scendi più in profondità che puoi a Uldaman e uccidi il costrutto più forte che c'è. Senza dubbio, qualunque cosa sia, ce l'avrà.\n\nQuando avrai raccolto tutto, torna qui!", "Ti aspetta un altro viaggio nelle profondità di Uldaman, se non hai le gemme e una sorgente energetica capace di riportare il potere magico nella collana.\n\nLe gemme le riavrai per consegnarle a quegli scagnozzi di Orgrimmar; la sorgente energetica invece la terrò io, visto che sarà proprio lei a far funzionare la collana...", "Ottimo lavoro, {class}. Ora i frutti della nostra deviazione ci ripagheranno profumatamente. Ho finito con la collana vera e propria, e sono sicuro di poter ripetere il procedimento di costruzione con costanza.\n\nMa prima userò un incantesimo preparato apposta per analizzare in fretta quelle gemme, prima che tu le riporti a Orgrimmar insieme alla collana. Ci vorrà solo un attimo.", 0x30e6ddb1, 0x28647b79, 0x50d630eb, 0x253eacd6, 0x834beb73, "....." },
  [2340] = { "Consegna le gemme", "Consegna la ⟦Necklace and Gem Salvage=Collana e Gemma Recuperate⟧ a Dran Droffers, a Orgrimmar.", "Qualsiasi montatura e gemma andranno bene, purché siano dello stesso materiale. Questa sorgente energetica, però, è ciò che riporterà la magia nella collana... spero.\n\nTi fornirò volentieri le gemme che servono per la tua versione della collana, purché la sorgente energetica funzioni davvero.\n\nVa' a Orgrimmar e rispetta la tua parte dell'accordo con Droffers and Son Salvage. Tieni solo la bocca chiusa sul nostro patto, e quando tornerai potrei avere una splendida sorpresa per te.", "Ma guarda chi si vede! Te la sei presa comoda, vedo. Speriamo che non sia una perdita di tempo! Non ti pagheremo se non hai tutto quello che ti ho chiesto. E credimi: controlleremo tutto due e tre volte!", "Sì, c'è tutto. Senti, ti dispiace se ci teniamo anche la borsa? No? Grazie, molto gentile! Ah!\n\nQuesta collana sarà il nostro bottino più grosso! Non prendertela troppo, però: sono sicuro che la collana non ti starebbe comunque. Ah, di nuovo!\n\nUn patto è un patto, quindi ecco il tuo compenso per il recupero. Per ora i nostri affari sono conclusi; ripassa più tardi per vedere se abbiamo altro lavoro. Fino ad allora, sparisci!", 0xa6e01d8e, 0x45a474af, 0x9eac5fd0, 0x8e68c5fa, 0xbfd9badc, "....." },
  [2341] = { "Recupero della collana, tentativo 3", "Fai visita a Jarkal Mossmeld, a Kargath, per scoprire se ci è riuscito.", "Mentre Dran e Malton Droffers cominciano a bisticciare sul loro nuovo bottino, metà dell'accordo è conclusa. Ora serve un viaggio nelle ⟦Badlands=Maleterre⟧ per chiudere la faccenda, perché Jarkal Mossmeld, a Kargath, potrebbe avere lì una ricompensa speciale per te.", nil, "La sorgente energetica che mi hai dato ha superato ogni mia aspettativa. Sono riuscito a fare una collana sia per te sia per me, e me n'è avanzata abbastanza per farne almeno altre tre. Frutteranno un bel guadagno, e quelli di Droffers and Son Salvage non ne sapranno niente.\n\nEcco a te, amico mio. Ti ringrazio per lo splendido lavoro... ed ecco qualcosa di davvero speciale per il disturbo.", 0x8c69a333, 0x18d75125, 0x335e1a01, nil, 0xe95ab0ac, "...m." },
  [2342] = { "Tesori recuperati", "Recupera il Tesoro della Famiglia Garrett dal forziere di famiglia nella South Common Hall di Uldaman e portalo a Patrick Garrett, a ⟦Undercity=Sepulcra⟧.", "Spazzare i recinti dei pipistrelli con questa scopa non si addice a un Garrett! Ho guadagnato qualche moneta con questo lavoro maledetto, e sono disposto a spenderla per te pur di migliorare la mia condizione.\n\nL'arma prediletta della famiglia Garrett è chiusa nel nostro forziere nella South Common Hall di Uldaman, da quando noi Garrett lavoravamo laggiù come scavatori. Senza di essa resterò bloccato qui per sempre, letteralmente, a spazzare dietro a questi pipistrelli infernali.\n\nRecupera il tesoro della mia famiglia e portamelo! Aiutami a riprendermi ciò che mi spetta per nascita!", "Non si finisce mai di spazzare... questi pipistrelli non si stancano mai di prendersi gioco di me e della mia scopa. Ti prego, dimmi che hai recuperato il tesoro della mia famiglia! Ti ho offerto il mio argento: non ti basta?!", "Finalmente: una scopa degna di un Garrett! Vali fino all'ultima moneta d'argento che ho speso per te, eccome!\n\nMi sentite, pipistrelli schifosi? Ora impugno l'arma prediletta della famiglia Garrett! Tremate, pipistrelli, tremate!!", 0x029286ee, 0xda30ae15, 0x53650d5c, 0x18629af4, 0x43d5b24d, "....." },
  [2358] = { "⟦Horns of Nez'ra=Corna di Nez'ra⟧", "Riporta le ⟦Horns of Nez'ra=Corna di Nez'ra⟧ ad Arantir's Shadow a ⟦Lakeshire=Borgolago⟧.", "Molti anni fa, le ⟦Horns of Nez'ra=Corna di Nez'ra⟧ furono rubate dal Maniero dei ⟦Ravenholdt=Corvolesto⟧. Le ho cercate attraverso continenti e oceani, solo per scoprire che queste bestie insignificanti le avevano sempre avute in loro possesso.\n\nUccidi ogni orco ⟦Blackrock=Roccianera⟧ che incontri finché non avrai recuperato le ⟦Horns of Nez'ra=Corna di Nez'ra⟧. Se le recuperi, trovami a ⟦Lakeshire=Borgolago⟧.\n\nFallo per me e il tuo nome sarà noto ai ⟦Ravenholdt=Corvolesto⟧, {name}.", "Hai le corna del principe demoniaco?", "Negare il manufatto a ⟦Ravenholdt=Corvolesto⟧ sarebbe come negare la propria stessa esistenza. Ben fatto, <ladro/ladra>. Un giorno potresti camminare tra gli assassini di ⟦Ravenholdt=Corvolesto⟧.\n\nDa giovane, quando andavo all'avventura a ⟦Darkshore=Rivafosca⟧, scoprii un tè che ripristina l'energia in combattimento. Mi è stato utile per tutti questi anni e ora ti passo un assaggio di Tè di Sboccialesto. Bevine quando ti senti senza forze, {name}, e combatti di nuovo con vigore!", 0xd52ec603, 0x3b5ab7d3, 0x4584825e, 0xe35c152d, 0x1f0b2efd, "....." },
  [2359] = { "La torre di Klaven", "Ruba la Defias Tower Key, irrompi nella torre dei Defias e scopri il contenuto del forziere di ⟦Duskwood=Boscovespro⟧. Porta le informazioni che trovi a Mathias Shaw, a ⟦Stormwind=Roccavento⟧. Leggi il ⟦Kearnen's Journal=Diario di Kearnen⟧ per saperne di più sulla torre.", "Sono settimane che sorveglio questa torre, {name}. Di recente è arrivato un grosso carico da ⟦Duskwood=Boscovespro⟧, e con esso quelle guardie.\n\nCosa sono? Ne so quanto te. Una cosa però te la posso dire: non sono umani.\n\nComunque, nel carico c'era un forziere, ed è quello che immagino stiano sorvegliando quegli abomini. Lo zombi con gli spuntoni ha una chiave che ci serve.\n\nPrendi quella chiave, entra nella torre e scopri cosa c'è in quel forziere. Porta ciò che trovi a Mathias.", "Notizie dall'agente Kearnen?", "Questo spiegherebbe i droni dei Defias che tu e Kearnen avete visto fuori dalla torre, {name}. Spiegherebbe anche il coinvolgimento della S.P.R. & Co. con i Defias e gli strani carichi in partenza da ⟦Duskwood=Boscovespro⟧.\n\nSecondo questo libro, i troll Zanzil di Rovotorto hanno scoperto un modo per risvegliare i morti con le pozioni... o, per essere precisi, con il veleno.\n\nNon sarai di nessuna utilità all'⟦SI:7=IR:7⟧ senza una solida conoscenza dei veleni, {name}, soprattutto ora che abbiamo a portata di mano la ricetta per creare la non morte.", 0x7a0fe55b, 0x84c572ed, 0xffbbc189, 0x6bdfdca0, 0xea54e6be, "....." },
  [2360] = { "Mathias e i Defias", "Raggiungi le ⟦Westfall=Marche Occidentali⟧ e trova l'agente Kearnen per ricevere il rapporto.", "Appena in tempo, {name}. Le ricognizioni dell'⟦SI:7=IR:7⟧ segnalano un'attività insolitamente intensa dei Defias nelle ⟦Westfall=Marche Occidentali⟧.\n\nPare che i Defias si siano impadroniti di una torre di guardia abbandonata dell'⟦Alliance=Alleanza⟧ a sud-est di ⟦Sentinel Hill=Guardiacolle⟧ e la stiano usando come base operativa per contrabbandare merci dalla via di rifornimento di ⟦Redridge=Crestarossa⟧.\n\nVa' nelle ⟦Westfall=Marche Occidentali⟧ e contatta l'agente Kearnen per il rapporto. La troverai nascosta vicino alla torre.\n\n...e, {name}, se dovessi essere scopert<o/a>, l'⟦SI:7=IR:7⟧ negherà di sapere alcunché della tua esistenza.", nil, "Mathias ha finalmente mandato un altro agente a darmi man forte, eh? Be', spero che sia pronto a sentire brutte notizie.", 0x105ec7f9, 0x8fda0905, 0x763fbd75, nil, 0x167ae4df, "...m." },
  [2361] = { "Restaurare la collana", nil, nil, nil, "Ti do con piacere questa collana, possente {class}. Mi hai reso un servizio inestimabile, e per questo ti ringrazio. Indossala con orgoglio, e assicurati di dire ad alta voce, e spesso, chi l'ha fatta per te!\n\nE se potessi aggiungere che non è affatto maledetta, sarebbe fantastico.", 0xd9740d79, nil, nil, nil, 0x00ee2344, ".mmm." },
  [2378] = { "Alla ricerca della Shattered Hand", "Raggiungi Orgrimmar e parla con Shenthul al Cleft of Shadow.", "Hai servito bene gli ⟦Deathstalkers=Inseguitori della Morte⟧, {name}, ma forse è tempo che tu ti spinga oltre. Hai mostrato attitudine per la furtività e l'inganno, ma hai ancora bisogno di molto addestramento.\n\nGli ⟦Deathstalkers=Inseguitori della Morte⟧ hanno alleati nella Shattered Hand. Cerca coloro che ci aiuterebbero: trova Shenthul a Orgrimmar.", nil, "Quindi sei tu ciò che i nostri potenti alleati hanno mandato a Shenthul? Che delusione...", 0x4edc9e9f, 0xb842824b, 0x66a5c788, nil, 0x38cd9abf, "...m." },
  [2379] = { nil, "Parla con Zando'zan al Cleft of Shadow.", "La tua sola determinazione non basta a superare gli ostacoli che ci attendono.\n\nParla con Zando'zan per iniziare il tuo addestramento come agente della Shattered Hand.\n\nSolo quando avrai padroneggiato le arti della furtività e del furto potrai compiere il passo successivo verso il tuo destino.", nil, "Forse Zando'zan si sbagliava. Zando'zan chiede scusa.", 0xb5f8d527, 0x72e5b430, 0x5267d5d0, nil, 0x1bd8647f, "e..m." },
  [2380] = { "A Orgrimmar!", "Parla con Shenthul al Cleft of Shadow, a Orgrimmar.", "Non sei <un/una> <maestro/maestra> di furtività e inganno, ma tutto questo può cambiare e cambierà. Evidentemente hai impressionato i capi con le tue misere abilità, visto che il grande Shenthul ha chiesto di te per nome.\n\nPrendi la strada a nord di qui fino a Orgrimmar e parla con Shenthul nel Cleft of Shadow.", nil, "È importante che la Shattered Hand resti vigile di fronte ai cambiamenti che Thrall vuole portare nell'⟦Horde=Orda⟧. Il nostro numero da solo non basterà a rovesciare il suo dominio: bisogna padroneggiare la furtività e l'inganno.", 0x2374baca, 0x53b81ad0, 0x7f04c7de, nil, 0x065d936e, "...m." },
  [2381] = { "Derubare i predoni", "Riporta il ⟦Southsea Treasure=Tesoro dei Mari del Sud⟧ a Wrenix il Miserabile, a ⟦Ratchet=Porto Paranco⟧. Non dimenticare di prendere un E.C.A.C. e gli ⟦Thieves' Tools=Strumenti dei Ladri⟧ dal Gizmotronic Apparatus di Wrenix. Ti serviranno entrambi per portare a termine la missione.\n\nSe vieni <attaccato/attaccata> da pappagalli insolitamente ostili, usa l'E.C.A.C.!", "Non voglio spaventarti, {name}, ma gli ultimi cinque ladri che ho mandato a rubare il tesoro dei Mari del Sud mi sono tornati a pezzi.\n\nA sud, lungo la costa, troverai la Tide Razor, la nave dei filibustieri dei Mari del Sud. Nascosto nella stiva c'è il bottino: il tesoro dei Mari del Sud. Sul secondo ponte della nave c'è il covo dei pirati, il posto dove addestrano tutti i loro ladri.\n\nSali a bordo, ruba il tesoro e riportamelo. Usa il covo dei pirati se hai bisogno di fare pratica come ladro, ma sta' attent<o/a>!", "Be', almeno hai ancora tutte le parti del corpo. Hai trovato il tesoro?", "Incredibile! Inverosimile! Semplicemente fantastico! Hai talento, {name}. O questo, o sei la persona più fortunata del mondo!\n\nEcco la tua parte del bottino. Sono sicuro che sapresti usare questa roba meglio di me.", 0xee0557f2, 0x3ff88d8f, 0xbebe5cc4, 0x738c0a5e, 0x11243ac4, ".....", nil, nil, nil, nil, 0xe028f305 },
  [2382] = { "Wrenix di ⟦Ratchet=Porto Paranco⟧", "Raggiungi ⟦Ratchet=Porto Paranco⟧ e parla con Wrenix il Miserabile.", "Zando'zan l'ha visto! Sì, il giorno arriva! La morte di Thrall... il pugnale nella schiena, il veleno che gli scorre in ogni vena... Zando'zan ha detto troppo.\n\n{name}! Zando'zan ha un compito per {name}! {name} deve andare a ⟦Ratchet=Porto Paranco⟧, a est di ⟦Crossroads=Crocevia⟧, e parlare con Wrenix il Miserabile. Va'!", nil, "Un altro? Gli ultimi cinque che quel troll pazzo mi ha mandato sono finiti in pasto agli squali. Speriamo che a te vada un po' meglio, eh?", 0x05456afd, 0x578f4c54, 0xc9799e26, nil, 0xa433399d, "...m." },
  [2383] = { "⟦Simple Parchment=Cartapecora Semplice⟧", "Leggi la ⟦Simple Parchment=Cartapecora Semplice⟧ e parla con Frang nella ⟦Valley of Trials=Valle delle Sfide⟧.", "Ah, mentre eri via è arrivata una cartapecora per te, {name}.\n\nLeggila quando hai tempo. Se non sbaglio, viene dall'istruttore dei guerrieri Frang. Vuole parlarti quando sarai pront<o/a>. Lo troverai fuori dall'Antro del Tirocinio, al riparo all'ombra.", "Cos'hai lì? Una cartapecora? Spero che tu non sia <uno/una> studios<o/a>...", "Ah, questa è la mia cartapecora. Avevo sentito che saresti venut<o/a> nella Valle, {name}. Mi fa piacere vedere che ce l'hai fatta: speriamo che tu sopravviva alle prove che ti aspettano. Come ho detto, man mano che diventi più potente, vieni da me: farò il possibile per addestrarti nelle vie del {class}.\n\nBuona fortuna, {name}, e torna da me quando ti senti pront<o/a>.", 0x1d01cad6, 0x159b5995, 0xb9d4e50a, 0xbf9315ae, 0x818eae1e, "....." },
  [2398] = { "I nani perduti", "Trova Baelog a Uldaman.", "Gli scavi di Uldaman non sono sempre stati invasi. Noi nani di ⟦Ironforge=Forgiardente⟧ controllavamo la zona, ma... era prima che arrivassero i trogg. Arrivarono così in fretta e in tal numero che nemmeno la forza dei nani riuscì a fermarli!\n\nAnzi, il loro attacco fu così improvviso che temo che alcuni dei nostri siano rimasti intrappolati dietro le linee nemiche.\n\nIl mio amico Baelog ha guidato un piccolo gruppo di nani nel profondo degli scavi poco prima che arrivassero i trogg. Se lui e i suoi compagni sono vivi, voglio che tu li trovi.", nil, "Era ora che arrivassi! Stavo per perdere una scommessa con Olaf!\n\nHa scommesso che la barba gli sarebbe arrivata alle ginocchia prima di vedere di nuovo <un/una> {race} in carne e ossa. Be', eccoti qui, e come vedi alla barba di Olaf mancano ancora parecchi centimetri.\n\nGrazie, {name}. Dividerò la vincita con te.", 0x826b7a46, 0x194d79a7, 0x1cc327cb, nil, 0xc693cc2f, "...m." },
  [2399] = { "Le fronde germogliate", nil, nil, nil, "Le fronde che Denalan ha piantato nel suo giardino sono germogliate e cresciute. Fremono, impazienti di essere raccolte...", 0xd9520005, nil, nil, nil, 0x87fc0eaa, ".mmm." },
  [2418] = { "Pietre del potere", "Porta 8 Pietra del Potere di Dentrium e 8 Pietra del Potere di An'Alleum a Rigglefuzz nelle ⟦Badlands=Maleterre⟧.", "Tempo fa ho avuto un incidente con i nani Forgiascura. Mi hanno portato alla ⟦Angor Fortress=Fortezza di Angor⟧ per studiare due tipi di strane pietre provenienti da Uldaman. Ho scoperto che, se trattate nel modo giusto, le pietre erano fonti di energia stabili e durature. È incredibile cosa si trova in quel vecchio sito di scavo!\n\nComunque, dopo che ho rivelato loro il segreto delle pietre, mi hanno cacciato dalla ⟦Angor Fortress=Fortezza di Angor⟧ e si sono messi a scavare a Uldaman per trovarne altre.\n\nVoglio quelle pietre per me! Portami tutti e due i tipi e ti pagherò profumatamente!", "Hai le pietre del potere, {name}? Ho un roditore robotico che ha bisogno di una fonte di energia...", "Fantastico, ne hai trovate! Grazie mille, {name}. Sei <il/la> {race} più affidabile che abbia mai conosciuto!\n\nNon vedo l'ora di provarle su alcuni congegni che sto mettendo a punto. Scommetto che, nelle giuste condizioni, i congegni alimentati con queste pietre continueranno ad andare, e andare, e andare...", 0x2a8fd07d, 0xf6808489, 0x69dbb206, 0x8950568a, 0xa4af47c3, "....." },
  [2438] = { "L'⟦Emerald Dreamcatcher=Acchiappasogni di Smeraldo⟧", "Porta l'⟦Emerald Dreamcatcher=Acchiappasogni di Smeraldo⟧ a Tallonkai Swiftroot a Dolanaar.", "Tempo fa Gaerolas Talvethen, il custode dei druidi nell'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧, mi donò un Acchiappasogni di Smeraldo. Questo potente amuleto è in grado di attingere energia dal ⟦Emerald Dream=Sogno di Smeraldo⟧, e porta fortuna a chi lo possiede.\n\nPurtroppo non sono riuscito a recuperarlo dal mio cassettone a ⟦Starbreeze Village=Brezzastella⟧... Un tempo ⟦Starbreeze Village=Brezzastella⟧ era un luogo tranquillo, ma ora è caduta preda della corruzione dei mezzorsi che vi abitano.\n\nForse saresti <disposto/disposta> a recuperare il mio acchiappasogni, {class}?", "Ti prego, fa' presto. Posso solo sperare che i mezzorsi non abbiano danneggiato il mio Acchiappasogni di Smeraldo.\n\nL'hai già recuperato, {name}?", "Il mio Acchiappasogni di Smeraldo è molto importante per me. È un dono concesso a pochi. Grazie per avermelo riportato, {name}.", 0x15f1c399, 0x52a2d29e, 0xfe33a929, 0x164e94f7, 0x1efbac0d, "....." },
  [2439] = { "I dischi di platino", "Porta il tuo buono premio a Dinita Stonemantle, nel caveau di ⟦Ironforge=Forgiardente⟧.", "Questo oggetto è una scoperta incredibile. Gli antichi Titani, o i Creatori, come li chiamano questi dischi, sono il legame con la nostra creazione incantata, se il sapere qui custodito è corretto! Dovremo dedicare a questo studio quanto più tempo possibile.\n\nQuanto a te, {class} valoros<o/a>, porta questo buono a Dinita Stonemantle, al caveau. Ti darà quella che ritengo una ricompensa adeguata per una scoperta così straordinaria!\n\nTorna direttamente da me quando sarai pront<o/a>: c'è ancora molto da fare per la ⟦Explorers' League=Lega degli Esploratori⟧!", "Benvenut<o/a> al caveau di ⟦Ironforge=Forgiardente⟧, {name}. Cosa posso fare per te oggi?", "Ah sì, un buono della ⟦Explorers' League=Lega degli Esploratori⟧... e di gran valore, aggiungerei.\n\nLa ⟦Explorers' League=Lega degli Esploratori⟧ mi concede l'autorità di offrirti una ricompensa a scelta direttamente dal suo caveau. Riceverai questo oggetto e potrai scegliere tra cinque Pozioni Pregevoli di Cura o cinque Pozioni Superiori di Mana come ricompensa.", 0xd5650943, 0x5d43047f, 0x819d9adb, 0xa99640aa, 0x38a04709, "....." },
  [2440] = { "I dischi di platino", "Porta il buono premio a Bena Winterhoof a ⟦Thunder Bluff=Picco del Tuono⟧.", "Concentrerò le mie energie su questi dischi; a tempo debito mi riveleranno il loro vero funzionamento.\n\nQuanto a te, {name}, ora ti ricompenserò per la diligenza con cui me li hai portati. Porta questo buono a Bena Winterhoof, l'istruttrice di alchimia di ⟦Thunder Bluff=Picco del Tuono⟧. Ti darà un oggetto speciale che credo troverai interessante, e ti lascerà scegliere fra le pozioni della mia scorta personale.\n\nTorna presto da me: sento che c'è ancora molto da fare riguardo a questa scoperta.", "Salute, {class}! Sei qui per addestrarti nell'alchimia, o forse per qualcos'altro?", "Be', {name}, devi aver fatto molto piacere al saggio Truthseeker, se ti ha dato questo oggetto. Ti spetta anche un dono dalla sua scorta di pozioni: puoi scegliere tra 5 Pozioni Pregevoli di Cura o 5 Pozioni Superiori di Mana come ricompensa.", 0xd5650943, 0x5bcf3865, 0x279b2c71, 0xd39babcd, 0x44a13553, "....." },
  [2458] = { "Sotto copertura", "Raggiungi la torre della S.P.R. & Co., a nord della ⟦Sludge Fen=Palude Fangosa⟧, e contatta l'agente infiltrato della Shattered Hand, il ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧.\n\nQuando la torre è in vista, usa lo ⟦Flare Gun=Spararazzi⟧ per segnalare il tuo arrivo al ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧. Spara DUE razzi, poi avvicinati al ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧ ed esegui lo Shattered /Salute.\n\nQueste azioni vanno eseguite nell'ordine corretto, perché Fizzule attacca ed elimina chiunque non riconosca.", "La ⟦Venture Company=S.P.R. & Co.⟧... Forse ne hai sentito parlare?\n\nPer un anno abbiamo lavorato per infiltrare un agente nel profondo dei loro ranghi. Con molto impegno e un'attenta pianificazione, ci siamo riusciti.\n\nDi recente ci è giunta voce che la ⟦Venture Company=S.P.R. & Co.⟧ sta preparando qualcosa in grande stile. Va' a nord della ⟦Sludge Fen=Palude Fangosa⟧, alla torre della ⟦Venture Company=S.P.R. & Co.⟧, e contatta il nostro agente infiltrato, il ⟦Taskmaster Fizzule=Coordinatore Fizzule⟧.\n\nQuando trovi la torre, usa questo spararazzi, poi avvicinati a Fizzule e mostragli il saluto della Shattered Hand.", nil, "Fa piacere vedere un altro agente della Shattered Hand da queste parti, però il razzo forse era un po' esagerato!\n\nLa prossima volta che devi parlarmi, soffia due volte in questo fischietto e saprò che sei dei nostri.", 0x379ff3f0, 0x8c974479, 0x9977ca74, nil, 0xc03a9821, "...m." },
  [2459] = { nil, "Tallonkai Swiftroot di Dolanaar vuole che tu uccida 7 Gnarlpine Mystic e trovi il gioiello scomparso.", "Lo smeraldo... È scomparso! Il mio acchiappasogni è stato danneggiato!\n\nC'è una banda di mistici ⟦Gnarlpine=Mordipigna⟧ a nord di Starbreeze. Ho sentito dire che il loro capo, Ferocitas the Dream Eater, porta una collana che di notte risplende di verde. Ora che vedo il mio acchiappasogni, sono sicuro che sia stato lui a rubare il mio smeraldo... Non capirebbe mai che il suo potere per lui è inutile.\n\nTrova il gioiello scomparso, {name}. E, già che ci sei, elimina anche un po' di quei mistici corrotti.", "Ferocitas e i mistici ⟦Gnarlpine=Mordipigna⟧ devono restituire ciò che è mio. Ti prego, recupera lo smeraldo così che io possa riparare il mio acchiappasogni di smeraldo.", "Ora posso riparare il mio acchiappasogni. Grazie, {name}.", 0x236ef724, 0x4c50de14, 0x837c9efe, 0x9c2bf253, 0x00d792cf, "e...." },
  [2460] = { "Lo Shattered Salute", "Esegui lo Shattered Salute davanti a Shenthul.", "Come <ladro/ladra> della Shattered Hand, è indispensabile che tu impari lo Shattered Salute. È l'unico modo per riconoscere davvero un altro membro della Hand.\n\nGuarda, impara, ripeti.", "Esercitati!", "Ben fatto, {name}. Ora sei pront<o/a> a proseguire.", 0xe29bc468, 0xbc1b393c, 0x21bdbb05, 0xa5a697be, 0xc8d80fd4, "....." },
  [2478] = { "Missione: possibile ma non probabile", "Ruba la Silixiz's Tower Key al caposquadra Silixiz, poi uccidi due Mutated Venture Co. Drone, due Venture Co. Patroller e due Venture Co. Lookout.\n\nAssassina il gran caposquadra Gallywix e prendi la sua testa, poi scassina il forziere di Gallywix e ruba la ⟦Cache of Zanzil's Altered Mixture=Cassa di Mistura di Zanzil Alterata⟧. Porta la Cassa e la ⟦Gallywix's Head=Testa di Gallywix⟧ a Shenthul, a Orgrimmar, per ulteriori istruzioni.", "Dovrai rubare la chiave della torre al caposquadra Silixiz, {name}. Una volta che l'avrai, tienila: potrebbe servirmi più avanti.\n\nRicorda, il veleno ha indebolito tutti in questa torre. Usa le tue abilità per seminare caos e distruzione tra chi ci vive. Uccidili tutti, senza pietà!\n\nQuando tutto là dentro sarà un mucchio insanguinato, scassina il forziere di Gallywix e ruba la cassa di mistura di Zanzil che contiene. Porta sia la testa di Gallywix sia la mistura a Shenthul, a Orgrimmar.", "Cos'hai da riferire, {name}?", "Povero Fizzule, era un buon agente, uno dei migliori. Ahimè, è il prezzo da pagare, {name}. Essere un agente sul campo della Shattered Hand è un lavoro pericoloso.\n\nHai fatto bene il tuo dovere, {class}. Sarebbe un peccato se non sopravvivessi per servirci ancora.", 0x889d9a10, 0x323252b6, 0xc695e02b, 0xd8f33c29, 0x2c36763c, "....." },
  [2479] = { "L'aiuto di Hinott", "Raggiungi il ⟦Tarren Mill=Mulino di Tarren⟧, nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, e consegna il campione di ⟦Zanzil's Mixture=Fiala della Mistura di Zanzil⟧ a Serge Hinott.\n\nPer arrivare al ⟦Tarren Mill=Mulino di Tarren⟧, prendi lo zeppelin per ⟦Undercity=Sepulcra⟧ e segui la strada verso sud attraverso ⟦Silverpine=Pinargento⟧, in direzione di ⟦Hillsbrad=Colletorto⟧. Segui i cartelli!", "Porta un campione della mistura a Serge Hinott, al ⟦Tarren Mill=Mulino di Tarren⟧.\n\nSe qualcuno può curarti, quello è Serge. Sopravvivi abbastanza a lungo e Serge ti insegnerà a creare e usare i veleni.", "Che cos'è questo???", "Hai un pallore delizioso, {class}. E cos'è quell'odore nauseabondo che emani? Devo saperlo!", 0x59895e49, 0xe1eb607d, 0x1bcf7a9f, 0x1de2dddb, 0x558ebfce, "....." },
  [2480] = { "L'aiuto di Hinott", "Aspetta che Serge Hinott completi la cura.", "Non ho mai visto risultati tanto prodigiosi da un veleno! Zanzil, dici? Mai sentito nominare, però devo complimentarmi con lui per aver creato questo intruglio.\n\nDunque, dovrei curarti da questo e poi insegnarti a usare il veleno?\n\nDammi qualche momento per esaminare la tossina, {name}.", nil, "La cura è pronta! Bevi questo antitossico e la follia strisciante si fermerà, però non potrò fare niente per l'odore.", 0x59895e49, 0xd6da9379, 0x9ead8b00, nil, 0x37216e45, "...m." },
  [2498] = { "Ritorno da Denalan", "Rellian Greenspyre vuole che tu parli con Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧.", "Mi è appena giunta notizia che Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧, ha scoperto quella che potrebbe essere la causa dei tumori che affliggono i timberling. Ti prego, va' a parlargli e digli che ti mando io.\n\nAffrettati, {name}: ha bisogno del nostro aiuto.", nil, "Ah, quindi Rellian ti ha mandato ad aiutarmi. Sono lieto che tu sia arrivat<o/a> così presto.\n\nHo scoperto qualcosa di davvero inquietante!", 0x86434b8b, 0x01cfe979, 0x16e96e4d, nil, 0xbdb97620, "...m." },
  [2499] = { nil, "Denalan, al ⟦Lake Al'Ameth=Lago Al'ameth⟧, vuole che tu prenda il ⟦Gargantuan Tumor=Tumore Gigantesco⟧ di Oakenscowl.", "In una grotta lungo la sponda meridionale del lago, un timberling di nome Oakenscowl sta diffondendo la corruzione a tutte le creature che vivono al ⟦Lake Al'Ameth=Lago Al'ameth⟧.\n\nNon ho osato avvicinarmi troppo, ma anche da lontano è evidente: Oakenscowl è avvelenato dal tumore più grande che abbia mai visto... lo definirei persino gigantesco.\n\n{name}, hai già fatto molto per aiutarmi, ma ti chiedo un ultimo compito. Dai la caccia a Oakenscowl e prendi il tumore: elimina questa fonte di corruzione dalla mia casa.", "Hai già trovato Oakenscowl, {race}?", "Sapevo che eri più che in grado di liberare il lago da quella bestia orribile.\n\nÈ una situazione angosciante: un tempo Oakenscowl era un grande capo tra i suoi simili... ma la corruzione non fa distinzione tra umili e nobili.\n\nLe dimensioni di questo tumore sono davvero inquietanti, ma devo studiarlo per saperne di più sulla malattia che affligge i timberling.\n\nGrazie, {name}.", 0xa9dba359, 0x0d86e120, 0x1f483fdc, 0x5c25b955, 0x92662c82, "e...." },
  [2500] = { "Reagenti delle ⟦Badlands=Maleterre⟧", "Procurati nelle ⟦Badlands=Maleterre⟧ i reagenti che servono a Ghak Healtouch, poi torna da lui a Thelsamar.", "{class}, vorrei avvalermi dei tuoi servigi. Sono un alchimista di una certa fama, e cerco aiuto per procurarmi alcuni reagenti che si trovano nelle ⟦Badlands=Maleterre⟧.\n\nPer rifornire le mie scorte mi servono: cinque stomaci di condor, dieci zanne di coyote delle rupi e cinque schegge elementali di roccia. Ovviamente puoi prenderli dalle bestiacce stesse; se non sei tipo da combattere, trova degli amici che lo siano.\n\nProcurami queste cose e ci guadagnerai qualche moneta.\n\nAllora, che ne dici?", "Hai già preso le cose che mi servono? Non ti pagherò finché non mi porti quei reagenti.", "Ah, ben fatto, {name}. Queste dovrebbero bastarmi almeno per un po'. Ecco la tua paga, come promesso.\n\nSe ti interessa, ci sono altri reagenti che mi servirebbero. Questi però si trovano solo nelle profondità degli scavi di Uldaman. Non sarà facile procurarli, ma ne varrà la pena, se vorrai aiutarmi di nuovo.\n\nMagari con qualcosa di più di qualche moneta luccicante, eh?", 0xaca0069d, 0xf4c53465, 0xe9758759, 0x5be9782d, 0xf953efd3, "....." },
  [2501] = { "Reagenti dalle ⟦Badlands=Maleterre⟧ II", "Usa le Ampolle Taumaturgiche Vuote sui draghi Scorched Guardian delle ⟦Badlands=Maleterre⟧. Quando saranno piene, portale a Ghak Healtouch, a Thelsamar.", "Mi sei stat<o/a> di grande aiuto, {name}. Vorrei ricompensarti con la ricetta stessa dell'infuso che ti ho dato prima, ma devo chiederti un favore piuttosto pericoloso.\n\nQuesta cassetta contiene tre ampolle taumaturgiche vuote: sono intrise di un'aura di sintonia che prosciugherà il sangue di un drago guardiano riarso. Usarne una sulla bestia la farà infuriare parecchio, quindi fai attenzione. Quando le avrai riempite tutte e tre, portamele.\n\nFallo, e la ricetta sarà tua.", "Hai usato le ampolle per procurarmi il sangue di drago guardiano riarso che mi serve? Sì, lo so, è un compito pericoloso... ma la ricetta del mio infuso ristoratore aspetta il tuo successo. Rischio e ricompensa, amico mio... rischio e ricompensa...", "Da alchimista ad alchimista, ti saluto. Ecco, prendi questa ricetta e imprimila nella memoria. Che ti porti il successo e le ricompense che ha portato a me in tutti questi anni!", 0x883768bc, 0xb97f5a02, 0x928aded5, 0x0cf00f74, 0xb7d7a9aa, "....." },
  [2518] = { "Lacrime della luna", "La sacerdotessa A'moora, nel ⟦Temple of the Moon=Tempio della Luna⟧ a Darnassus, vuole che tu le porti la ⟦Silvery Spinnerets=Filatura Argentea⟧ di Lady Sathrah.", "Lady Sathrah un tempo era prediletta da Elune. Aggraziato e puro, il ragno tesseva i suoi fili d'argento al chiaro di luna, catturando la foschia della sera. La rugiada argentea aveva grandi poteri curativi ed era custodita qui nel tempio.\n\nMa di recente Sathrah è sprofondata nella follia. Ora sono minacciate anche le sue generazioni future.\n\nTrova Lady Sathrah, {name}, e poni fine alle sue sofferenze. Dimora lungo i confini settentrionali di Teldrassil, vicino al ⟦Wellspring Lake=Lago di Buonpozzo⟧. Raccogli la sua filatura argentea e riportala a me.", "Mi rammarico del compito che ti ho chiesto di svolgere, ma per Lady Sathrah non c'è più speranza.\n\nSperiamo di offrire a Elune il sacrificio della filatura. Con questo sacrificio Elune benedirà Sathrah, perché possa rinascere e trovare la pace.", "La foresta piange Lady Sathrah, ma era una cosa che andava fatta.\n\nGrazie, {name}.", 0x590caf7f, 0x6c622142, 0x20922da4, 0x35d5c5a2, 0x309445ea, "....." },
  [2519] = { "Il ⟦Temple of the Moon=Tempio della Luna⟧", "Sorella Aquinne vuole che tu parli con la sacerdotessa A'moora nel ⟦Temple of the Moon=Tempio della Luna⟧.", "Una creatura della foresta, un tempo grandiosa, ha bisogno di aiuto, {race}.\n\nC'è un compito difficile da portare a termine.\n\nTi prego, cerca la sacerdotessa A'moora: ti spiegherà tutto. La troverai a sud-est di qui, all'interno del ⟦Temple of the Moon=Tempio della Luna⟧.", nil, "Allora, ti ha mandato sorella Aquinne?", 0xbf995b33, 0xfccb6f52, 0xb532fd45, nil, 0x4f3a53a8, "...m." },
  [2520] = { "⟦Sathrah's Sacrifice=Sacrificio di Sathrah⟧", "La sacerdotessa A'moora vuole che tu deponga la filatura argentea di Lady Sathrah presso la fontana all'interno del tempio, e che poi torni da lei.", "Ora devi portare a termine il compito che ti è stato affidato. Prendi la filatura e offri a Elune il sacrificio di Lady Sathrah; concedi al grande ragno il riposo eterno.\n\nAll'interno di questo tempio, trova la fontana centrale. È lì che potrai lasciare il sacrificio. Le acque sacre purificheranno e laveranno via la corruzione che ha fatto impazzire Sathrah.\n\nQuando avrai finito, torna da me.", "Hai deposto il sacrificio presso la fontana, {name}?", "La perdita di Lady Sathrah è dolorosa, ma solo così potrà rinascere con uno spirito rinnovato.\n\nChe Elune accolga di buon grado il sacrificio che le hai offerto.", 0x5a3cb37c, 0x6736b09f, 0x7b40ee6c, 0xf5b1c4b7, 0xbd5ac00f, "....." },
  [2521] = { "Al servizio di Kum'isha", "Durante i tuoi viaggi nelle ⟦Blasted Lands=Terre Devastate⟧, se mai dovessi trovare una ⟦Flawless Draenethyst Sphere=Sfera di Draenetista Perfetta⟧, portala a Kum'isha il Collezionista.\n\nAttenzione: questa gemma è uno dei cristalli più rari di tutta Azeroth. Qualsiasi creatura di queste terre potrebbe avere con sé una ⟦Flawless Draenethyst Sphere=Sfera di Draenetista Perfetta⟧.\n\nRiceverai una ricompensa per ogni ⟦Flawless Draenethyst Sphere=Sfera di Draenetista Perfetta⟧ che avrai raccolto.", "{race}, il tuo minuscolo cervello riesce a comprendere la rarità di una sfera perfetta di draenetista? I draenei hanno passato intere vite a cercare anche uno solo di questi cristalli, solo per andare incontro a una fine orribile, senza aver raggiunto il loro scopo.\n\nE così ti presenti davanti a Kum'isha, sapendo ciò che Kum'isha ha chiesto, e vuoi ancora aiutare? Molto bene, {race}... In qualsiasi momento dei tuoi viaggi per queste terre, se troverai una sfera perfetta di draenetista, riportamela e ti ricompenserò con ricchezze che vanno oltre i tuoi sogni più sfrenati.", "Ho dedicato la mia vita alla ricerca delle sfere perfette di draenetista. Una vita intera, {race}!", "I miei occhi mi ingannano? Impossibile! Dove l'hai... Come...\n\nForse ora si potrà aprire un varco che ci riporti nella nostra terra natale.", 0x81cce1f7, 0x009332b5, 0xa4c5c9f1, 0x71ae7976, 0xf92902be, "....." },
  [2541] = { "Il Druido dormiente", "Porta un ⟦Shaman Voodoo Charm=Talismano Sciamanico Vudù⟧ a Oben Rageclaw all'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧.", "Gli sciamani ⟦Gnarlpine=Mordipigna⟧ che abitano questo luogo hanno scoperto un modo per separare lo spirito di un druido addormentato dal suo corpo fisico. I mezzorsi hanno animato il mio corpo e lo usano per attaccare chiunque cerchi di esplorare l'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧. Ora sono intrappolato nel ⟦Emerald Dream=Sogno di Smeraldo⟧, impotente a fermarli.\n\nDevi aiutarmi. Gli sciamani ⟦Gnarlpine=Mordipigna⟧ portano uno strano talismano che usano per compiere questo rituale, e vorrei esaminarlo. Ti prego, {name}, portamene uno.", "Se potessi esaminare il talismano, forse riuscirei a capire come spezzare l'incantesimo. Ne hai trovato uno?", "Grazie, {name}.\n\nChe strano ninnolo è questo... Sento l'aura malvagia che emana; è un incantesimo molto potente.", 0xf13c0bd8, 0xb6182866, 0xcd3565db, 0x8fcb5c05, 0x37128c11, "....." },
  [2561] = { nil, "Oben Rageclaw vuole che tu uccida il suo corpo senz'anima e poi usi il ⟦Voodoo Charm=Talismano Vudù⟧.", "Dopo aver esaminato questo talismano, {name}, ora capisco cosa bisogna fare. Ti prego, prendilo e fa' come ti chiedo.\n\nDevi esplorare le zone più profonde dell'⟦Ban'ethil Barrow Den=Eremo di Ban'ethil⟧. Lì troverai il mio corpo senz'anima... Anche se mi rammarico di ciò che sto per dirti, non vedo altro modo per liberarmi dal controllo dei ⟦Gnarlpine=Mordipigna⟧.\n\nPer sfuggire a loro, devi uccidere la mia forma fisica. Fatto questo, usa il talismano vudù sul mio corpo caduto. Dopo aver portato a termine questo compito, ti prego, torna da me.", "{name}, fai attenzione quando ti avvicini alla mia forma fisica: l'incantesimo che la vincola è molto potente.", "Finalmente sono libero dal controllo dei ⟦Gnarlpine=Mordipigna⟧. Grazie, {name}.\n\nOra il mio spirito potrà riposare in pace per sempre nel ⟦Emerald Dream=Sogno di Smeraldo⟧.\n\nForse un giorno ci incontreremo di nuovo, giovane {class}. Ma, per ora, accetta questa ricompensa come segno della mia gratitudine.", 0xdcee0406, 0x31a8c3fe, 0x9102b8db, 0x56e2ee75, 0x992edece, "e...." },
  [2581] = { "Guance di Iena Ridente", "Porta 3 Guancia di Iena Ridente, 2 Polmone di Cinghiale Devastato e 1 ⟦Scorpok Pincer=Chela di Scorpok⟧ al mago del sangue Drazial.", "È risaputo che le iene hanno una forza tremenda nelle mascelle, ma la forza di spezzare tre pollici di acciaio di torio? Impossibile, improbabile, eppure l'ho vista dimostrare con i miei occhi.\n\nAvventurati nelle ⟦Blasted Lands=Terre Devastate⟧ e portami tre guance di iena ridente. Mentre cerchi le iene ridenti, tieni d'occhio cinghiali e scorpok: per completare il primo saggio servono anche due polmoni di cinghiale devastato e una chela di scorpok.", "Puzzi da far schifo, {name}. Sei andat<o/a> a zonzo nei campi di zolfo? E dove sono i miei componenti?!", "Come ti senti, {name}? Irradi l'aura della iena ridente: la tua forza non ha eguali tra i mortali!\n\nPurtroppo, con i componenti che mi hai portato, sono riuscito a ricavare dal saggio solo una tavoletta. Mi serviranno altri componenti, se vorrai un'altra tavoletta.", 0xf7f16d26, 0xb51443a6, 0x3ee63bcd, 0xd475d33e, 0x0973a15f, "....." },
  [2583] = { "La vitalità del cinghiale", "Porta 3 Polmone di Cinghiale Devastato, 2 Chela di Scorpok e 1 ⟦Basilisk Brain=Cervello di Basilisco⟧ al mago del sangue Drazial.", "In queste terre devastate vivono due specie di cinghiale: l'Ash-Mane Boar e l'Helboar.\n\nPare che la resistenza di queste bestie le renda quasi immuni alle ferite, tanto che gli altri animali le trovano troppo difficili da uccidere e, di conseguenza, non degne della fatica.\n\nDobbiamo condurre altre analisi, {name}. Se mi porterai tre polmoni di cinghiale devastato, due chele di scorpok e un cervello di basilisco, creerò un elisir divino dal residuo del saggio. Sarai la mia prima cavia!", "Dove sono gli organi, {name}!?", "Lo spirito del cinghiale illumina il tuo essere, {name}! Mi chiedo: ti credi invulnerabile quanto queste bestie?", 0x9a4e1685, 0x97393e8f, 0x2a64bd84, 0x307f3aa2, 0x73abbfa6, "....." },
  [2585] = { "Il colpo decisivo", "Porta 3 Chela di Scorpok, 2 Stomaco d'Avvoltoio e 1 ⟦Blasted Boar Lung=Polmone di Cinghiale Devastato⟧ al mago del sangue Drazial.", "Li hai mai osservati in battaglia, {name}? Gli scorpok, intendo. Hai mai visto la grazia e l'agilità con cui si muovono? La risolutezza dei loro colpi?\n\nSe solo potessimo isolare in qualche modo quell'agilità e racchiuderla, saremmo ricchi oltre ogni nostra... cioè... sarebbe una benedizione per la comunità scientifica.\n\nAiutami, {name}, e ti concederò un assaggio del saggio.\n\nPer creare un campione stabile mi servono tre chele di scorpok, due stomaci d'avvoltoio e un polmone di cinghiale devastato.", "Dove sono gli organi, {name}!?", "Affascinante. Di tutti i saggi, questo è stato il più difficile da analizzare.\n\nPrendi un pizzico di questo sale residuo e mettilo sotto la lingua. Dovresti provare una leggera euforia, seguita da uno stato di agilità e rapidità senza precedenti.", 0x0a859cb2, 0xab76c31d, 0xc7ff6f5a, 0x307f3aa2, 0xf5293056, "....." },
  [2601] = { "Il morso del basilisco", "Porta 10 Cervello di Basilisco e 2 Stomaco d'Avvoltoio alla maga del sangue Lynnore.", "Queste lande desolate brulicano di Redstone Basilisk, {name}. Questi basilischi si sono adattati e hanno prosperato più di qualunque altra creatura selvatica della regione.\n\nLi ho osservati da lontano mentre cacciano e svolgono le loro attività quotidiane: queste bestie mostrano un pensiero più complesso perfino di certi umanoidi.\n\nDevo studiare i loro cervelli!\n\nRecuperamene dieci, {name}. Il composto, però, non può essere completato senza due stomaci d'avvoltoio, che formeranno la base della soluzione.", "Sei tornat<o/a> con gli organi che ti ho chiesto?", "È meraviglioso, {name}! Ti offro un assaggio dei meccanismi interni del Redstone Basilisk.\n\nSe il composto è di tuo gradimento, se ne può sempre preparare dell'altro... a un prezzo.", 0x20ee9432, 0xa6edac7a, 0xafb93fc0, 0x7cfd6e6c, 0x0b5fda6b, "....." },
  [2603] = { "Il vigore dell'avvoltoio", "Porta 10 Stomaco d'Avvoltoio e 2 Guancia di Iena Ridente alla maga del sangue Lynnore.", "In queste terre devastate la morte ha davvero le ali, {race}. Ho visto i Black Slayer e i Bonepicker banchettare sul cadavere di molti esploratori caduti, a volte nutrendosi delle carcasse più ripugnanti e infette. C'è da chiedersi, dunque, come i loro organi interni riescano a vincere la pestilenza che affligge queste terre.\n\nAiutami nei miei studi, {name}! Mi servono stomaci! Per la base dell'intruglio serviranno anche due guance di iena ridente.\n\nI tuoi sforzi saranno ricompensati due volte.", "Non farmi perdere tempo, {name}. Non abbiamo nulla di cui parlare, a meno che tu non abbia recuperato ciò che ti ho chiesto.", "Eccellente! Mi metterò subito al lavoro. Forse troveremo una cura per molti dei mali del mondo!\n\nAh sì, la tua ricompensa... naturalmente, se ti servirà altra gomma, torna da me e ti sarà affidato un altro compito.", 0xf578d486, 0x341217f6, 0x95cfa89c, 0xb053bb62, 0x33e80ed6, "....." },
  [2605] = { "Il goblin assetato", "Procurati una ⟦Laden Dew Gland=Ghiandola Carica di Rugiada⟧ e portala a Marin Noggenfogger, a ⟦Gadgetzan=Meccania⟧.", "Ho avuto un'idea, sai. Ho sentito parlare di certe strane creature chiamate collettori di rugiada che vivono a sud-ovest... e che riescono a immagazzinare l'acqua in ghiandole speciali.\n\nSe riuscissi a procurarmi una di queste ghiandole, potrei creare una bevanda capace di placare la mia sete tremenda! Pensi di potermi aiutare, {name}?\n\nCerca il giardino di cactus, {name}: è lì che troverai i collettori di rugiada.", "Ti prego, dimmi che hai trovato i collettori di rugiada!", "Oh, magnifico! Dammela qui, fammela bere!", 0x805d477a, 0xa5a9ca3d, 0xbd452d01, 0x899d1b38, 0x4e1b216e, "....." },
  [2606] = { "Questione di gusto", "Marin Noggenfogger vuole che tu parli con Sprinkle, a ⟦Gadgetzan=Meccania⟧.", "Bleah! Questa roba ha un sapore orribile! Addio, bella idea...\n\nAspetta, cosa? Oh, lo so, lo so, pensi che non dovrei arrendermi con questa roba. E va bene, allora.\n\nEhmmm, ho un'idea! Geniale! Porta questa rugiada alla mia amica Sprinkle: è una cuoca eccellente. Dille cosa stiamo combinando e che vogliamo renderla un po' più facile da mandar giù.\n\nVoglio dire, se deve avere un sapore così cattivo, almeno dovrebbe dare una bella botta... E io proprio non la sento...", "Così il vecchio Marin ci riprova, eh? Con cosa è fatto questo intruglio?", "Marin è un tipo a posto, non fraintendermi... solo un po'... eccentrico, direi.\n\nE ovviamente ha bisogno del mio aiuto, un'altra volta.", 0x82179d87, 0x0808dc2a, 0xd3943384, 0x956f77b1, 0x5fbd62fd, "....." },
  [2607] = { "Il ⟦Touch of Zanzil=Tocco di Zanzil⟧", "Parla con Doc Mixilpixil nella cantina della caserma.", "Sembra che tu abbia riportato più informazioni di quante ne aspettassi perfino io. Questa è davvero una strana piega degli eventi, {name}.\n\nUna cura? Mmm... Scendi in cantina e parla con Doc Mixilpixil: forse può aiutarti.", nil, "Era ora! Metti il formaggio sul tavolo e sparisci. Osborne ti pagherà all'uscita.", 0x11470d66, 0xad163fb8, 0x32b769f3, nil, 0x006a9227, "...m." },
  [2608] = { "Il ⟦Touch of Zanzil=Tocco di Zanzil⟧", "/lay: sdraiati per farti visitare dal dottor Mixilpixil. Come può trovare la cura, se non trova la causa?", "Santo cielo, sembri la morte. Correggo: ho visto la morte, e tu sei mess<o/a> peggio. Tu, <signore/signorina>, sei quello che la morte ha tossito fuori alla sua ultima visita medica.\n\nAh! Hai sentito, Noarm? Scrivitela!\n\n*Coff* Ehm, sì, per aiutarti dovrò prelevarti un po' di sangue. Non preoccuparti, fa male solo le prime... cinquanta volte o giù di lì... Usa /lay e sdraiati quando sei pront<o/a> per la cura, {name}.", "Quando sei pront<o/a> per la visita, usa /lay, sdraiati a terra e comincerò il salasso.", "Dammi un momento per consultarmi con i miei colleghi, {name}. Dottor Montgomery, signor Noarm, a consulto!", 0x11470d66, 0xc7da4c18, 0x83e14b94, 0x27c52fde, 0x5baee4be, ".....", nil, nil, 0x0305c147, nil, nil },
  [2609] = { "Il ⟦Touch of Zanzil=Tocco di Zanzil⟧", "Porta al dottor Mixilpixil un mazzo di ⟦Simple Wildflowers=Fiori Semplici⟧, una Leaded Vial, un ⟦Bronze Tube=Tubo di Bronzo⟧ e una ⟦Spool of Light Chartreuse Silk Thread=Rocchetta di Filo di Seta Verdastro⟧. L'\"ite\" non guarisce da sola, <giovanotto/signorina>.", "È unanime, {name}. Hai l'\"ite\".\n\nPer fortuna ho una cura per l'\"ite\".\n\nEcco cosa mi serve: un mazzo di fiori semplici, una fiala piombata, un tubo di bronzo e, ultima ma non meno importante, una rocchetta di filo di seta verdastro. La vecchia Emma me ne ha lasciata una rocchetta a \"The Finest Thread\". Trovi il negozio lungo i canali.\n\nForza, sbrigati, {name}, e cerca di non toccare nessuno finché non sei guarit<o/a>. Ah, e il dottor Montgomery dice che hai bisogno di una doccia: parole sue, non mie.", "Se vuoi guarire dall'\"ite\" dovrai impegnarti più di così, {name}. Dove sono i reagenti per la cura?", "Cosa sto facendo? Secondo te cosa sto facendo? Sto preparando una cura per la tua \"ite\"! Non fare l'offes<o/a> adesso, {name}!\n\nAncora qualche secondo. Ecco! Spruzzati addosso questa, ehm, medicina dal profumo fantastico e sarai come nuov<o/a>.", 0x11470d66, 0xd6faf98a, 0xdeee9d37, 0x82beeccc, 0xfb99b7cf, ".....", nil, 0x6c5f6143, nil, nil, nil },
  [2621] = { "Il disonorato", "Parla con il comandante dei dispacci Ruag a ⟦Stonard=Pietrachiusa⟧.", "Rimpianto. È tutto ciò che mi resta. Una sola decisione sbagliata, e tante conseguenze orribili. Se solo avessi aspettato quegli ordini. Forse avrebbero descritto gli orrori che ci attendevano in quelle terre maledette! Forse dovevano assegnarci a un altro incarico? Alla fine, la colpa è stata mia. Tutta colpa mia.\n\nE così eccomi qui, in attesa di ordini. Devo sapere. Devo avere quegli ordini.\n\nIl comandante dei dispacci Ruag risiede a ⟦Stonard=Pietrachiusa⟧. Trovalo e scopri che fine hanno fatto gli ordini.", nil, "Thrall's Grasp... La storia è ancora fresca nella mia mente.\n\n<Il comandante Ruag scuote la testa.>\n\nUna cosa terribile, quella successa a quel reggimento. L'Orda ha perso alcuni dei suoi soldati migliori quando quel battaglione è stato distrutto.", 0xbda27292, 0x0b66b2f4, 0xcd14fa37, nil, 0xcac5f462, "...m." },
  [2622] = { "Gli ordini scomparsi", "Parla con Bengor.", "Gli ordini? Che cosa vuoi tu dagli ordini?\n\nCosa stai insinuando, {name}? Certo che li ho inoltrati, quegli ordini! I soldati a cui li ho affidati sono caduti in un'imboscata e sono stati brutalmente pestati dai murloc. Ne è sopravvissuto solo uno, se si può chiamarla sopravvivenza. Riesce a malapena a parlare, non può camminare e dev'essere nutrito con un tubo. Se vuoi sapere che fine hanno fatto quegli ordini, parla con Bengor. Sono sicuro che è qui intorno da qualche parte... e, {name}, sta' attent<o/a> a dove ficchi il naso: potrebbero staccartelo a morsi.", nil, nil, 0x2d77d470, 0x9bcc00ad, 0x8684ebe3, nil, 0xb47cdba1, "...me" },
  [2623] = { "Swamp Talker", "Recupera gli ⟦Warchief's Orders=Ordini del Capoguerra⟧ e riportali all'Eroe Caduto dell'⟦Horde=Orda⟧.", "Ordini dati dal comandante dei corrieri. Noi... prendemmo gli ordini. In marcia verso le ⟦Blasted Lands=Terre Devastate⟧, imboscata.\n\nMurloc... Tanti murloc... Uno chiamato Swamp Talker. Mi prese gli ordini dalle mani mentre una lancia mi trafiggeva il cranio. Est... grotta...\n\n<Bengor perde i sensi.>", "In attesa di ordini.", "È peggio di quanto immaginassi. Diciannove dei miei uomini avrebbero potuto essere risparmiati dall'agonia che hanno subito. Se solo non avessi agito in modo così sconsiderato.\n\nDevi aiutarli, {name}! Io non posso fare nulla.", 0xe86f7781, 0xf431fca9, 0x309b0066, 0x45e39911, 0xf2effa95, "....." },
  [2641] = { "L'ingrediente segreto di Sprinkle", "Sprinkle, a ⟦Gadgetzan=Meccania⟧, vuole che tu raccolga un'⟦Violet Tragan=Amanita Viola⟧ e gliela riporti.", "Quando ero piccola, a cucinare era sempre mia sorella. Era orribile! Riuscivo a malapena a mandar giù certi suoi intrugli, finché non ho scoperto quello che mi piace chiamare il mio ingrediente \"segreto\"! Aggiungilo a qualsiasi cosa e... WOW! Diventa buonissima!\n\nChe cos'è, mi chiedi? È un fungo chiamato ⟦Violet Tragan=Amanita Viola⟧. Se vuoi che ti aiuti a trasformare questa bevanda dal sapore orrendo in qualcosa di commestibile, va' nelle Entroterre e cerca un laghetto.\n\nAh, e ricorda: l'⟦Violet Tragan=Amanita Viola⟧ si trova solo sott'acqua.", "Sotto le acque di quel lago: è l'unico posto dove si trova l'⟦Violet Tragan=Amanita Viola⟧. Spero che tu sappia trattenere bene il fiato!", "È proprio quella, {name}!\n\nHa un aspetto così buono che quasi quasi... Ahah, ci sei cascat<o/a>!", 0x48dcbf56, 0x725eaf56, 0x8fd96556, 0x624f9464, 0x7cf9518d, "....." },
  [2661] = { "Una consegna per Marin", "Sprinkle vuole che tu porti la ⟦Violet Powder=Polvere Viola⟧ a Marin Noggenfogger, a ⟦Gadgetzan=Meccania⟧.", "Ecco la ⟦Violet Powder=Polvere Viola⟧, {name}. Portala a Marin e digli che mi deve un favore!", "Oh, {name}, finalmente sei tornat<o/a>. Che cosa mi hai portato?", "⟦Violet Powder=Polvere Viola⟧, eh? Proviamola: peggio di così non può andare, poco ma sicuro!", 0x458593b0, 0xbf6e3776, 0x1e01e31c, 0x1caa7a18, 0xe0372ebf, "....." },
  [2662] = { "⟦Noggenfogger Elixir=Elisir di Granstrippo⟧", "Marin Noggenfogger vuole che tu gli parli di nuovo dopo che avrà creato il suo elisir.", "Ora, mescoliamo questa polvere con la rugiada.\n\nTorna a parlarmi tra un minuto... quando avrò perfezionato il favoloso ⟦Noggenfogger Elixir=Elisir di Granstrippo⟧!", nil, "Bevi questo! È assolutamente meraviglioso!!!\n\nLo sapevo di averne la stoffa... Oh, grazie ancora per l'aiuto, {name}, ma per favore, ti sposti un po' di lato? Mi blocchi gli affari! Farò milioni con il favoloso ⟦Noggenfogger Elixir=Elisir di Granstrippo⟧, milioni!\n\nCome? Sprinkle dice che le devo un favore? Oh, quella Sprinkle, che burlona!", 0x1f1d9022, 0x1eeb2789, 0x356c5cd7, nil, 0x1bf10544, "...m." },
  [2681] = { "Le pietre che ci legano", "Libera nove Servant of Razelikh, tre Servant of Sevine, tre Servant of Allistarj e tre Servant of Grol. Torna dall'Eroe Caduto quando avrai finito. Devi restare vicino alle pietre, o il procedimento fallirà.", "Da sol<o/a> non basterai a sopraffare le forze di Razelikh e dei suoi sottoposti.\n\nRaduna un gruppo di avventurieri all'altezza e libera i miei uomini dal loro tormento eterno! Diciotto pietre devi frantumare.\n\nCombatti con forza e muori con onore, {name}.", "Non è un compito facile, {name}. Non arrenderti!", "Ce l'hai fatta, {name}! Quelle povere anime tormentate possono finalmente riposare.\n\nIl nostro lavoro non è ancora finito, {name}. Abbiamo molto di cui parlare e molto altro da compiere.", 0xb9c0ca74, 0x954b0e18, 0xe5fcf65b, 0x2db7e4f8, 0xd8cd7b43, "....." },
  [2701] = { "Eroi di un tempo", "Apri il forziere e prendi la tua ricompensa.", "Ti prego, prendi da qui una reliquia antica. A noi quell'oggetto non serve più.\n\nChe ti sia utile nella lotta contro la Legione.", nil, "Per un attimo resti accecat<o/a> dallo scintillio.", 0x66b9e903, 0x9708f52e, 0x84e15692, nil, 0x4202d363, "...m." },
  [2702] = { "Eroi di un tempo", "Parla con il caporale Thund Splithoof.", "Mi hai reso onore con la tua nobiltà e il tuo eroismo, {name}.\n\nE hai reso onore anche a loro...", nil, "Davvero, hai reso onore a tutti noi. I nostri ringraziamenti da soli non bastano.", 0x66b9e903, 0x30807b26, 0xa2f524f9, nil, 0xe07e9f96, "...m." },
  [2721] = { nil, "Scopri che fine ha fatto il tenente Kirith.", "Mentre un capitolo della tua avventura si chiude, un altro se ne apre, {name}.\n\nUno dei miei uomini manca ancora all'appello, disperso da qualche parte nelle ⟦Blasted Lands=Terre Devastate⟧. Parlo del tenente Kirith, naturalmente.\n\nCome ti avevo detto, siamo stati entrambi imprigionati e torturati da Allistarj, ma il povero Kirith... la sua forza di volontà ha vacillato. Dalla mia gabbia sentivo gli esperimenti; le urla dei torturati risuonavano per le sale della grotta. Fu l'ultima volta che vidi o sentii Kirith.", nil, "Trebor? Ti ha mandato Trebor?", 0xf24438ad, 0xa3197881, 0x5ce3d883, nil, 0x38fc0acd, "e..m." },
  [2741] = { "Il Super Egg-O-Matic", nil, nil, "Il Super Egg-O-Matic è l'ultima delle invenzioni di Curgle Cranklehop. È un macchinario davvero notevole.\n\nIl Super Egg-O-Matic sbuffa all'impazzata mentre ti avvicini al pannello di controllo.", "Metti l'uovo di ippogrifo nella macchina. Segue una serie di bip, insieme a strani rumori meccanici.\n\nSembra che l'Eggometer abbia pesato, misurato e impacchettato il tuo uovo. Questo sì che è un servizio rapido!", 0x4734c8ad, nil, nil, 0x057367ef, 0x55a62f46, ".mm.." },
  [2742] = { "Rin'ji è in trappola!", "Scorta Rin'ji fuori dal ⟦Quel'Danil Lodge=Padiglione Quel'Danil⟧, poi trova il segreto che ha nascosto alla Scogliera Altosguardo, a est.", "Ehi, {race}!\n\nRin'ji perso ascia ed essere catturato! Per favore, aiuta Rin'ji a scappare. Me sapere che {race} come te non amare quelli come Rin'ji, ma Rin'ji supplica! Dovere uscire da qui!\n\nRin'ji avere qualcosa per {race} gentile che aiuta Rin'ji a uscire da qui...\n\nRin'ji nasconde qualcosa di segreto alla Scogliera Altosguardo.", "Rin'ji avere paura!", "Questa tavoletta troll dev'essere il \"segreto\" di cui parlava Rin'ji.\n\nÈ coperta di strani segni e non riesci a decifrare cosa dice.", 0xedcbafa0, 0x2e3685ec, 0x9115ee07, 0x84c2d66f, 0x60b31af3, ".....", nil, nil, 0x9beee76c, nil, nil },
  [2743] = { "Il manto dell'oscurità", "Torna dall'Eroe Caduto dell'⟦Horde=Orda⟧ con ciò che hai scoperto.", "Non giriamoci intorno, {race}; il mio tempo qui è limitato.\n\nDevi distruggere la triade del potere che protegge il signore dei demoni, Razelikh. Non sarà un compito semplice come liberare un'anima dannata.\n\n<Kirith sogghigna.>\n\nVedi, ciascuno dei sottoposti di Razelikh porta al collo un terzo di un amuleto creato da Razelikh. Proprio l'amuleto che ti servirà per evocare l'arcidemone.\n\nTorna da Trebor e digli cosa serve per evocare Razelikh. Saprà darti altre istruzioni.", nil, "Il signore dei demoni mostra un'astuzia calcolata quasi quanto la sua brutalità, {name}.", 0x6aba07e4, 0x3827a7a4, 0xf90b2858, nil, 0x5627f8b3, "...m." },
  [2744] = { "Il cacciatore di demoni", "Parla con Loramus Thalipedes ad Azshara.", "La triade è protetta da Razelikh.\n\nIn cambio della loro servitù, Razelikh ha concesso a ciascuno di loro un potere quasi illimitato entro le ⟦Blasted Lands=Terre Devastate⟧. I frammenti dell'amuleto sono ciascuno legati alla forza vitale del loro possessore e gli donano l'immortalità. Finché restano nelle ⟦Blasted Lands=Terre Devastate⟧, non possono essere uccisi, e la loro vita si prolunga fino alla fine dei giorni.\n\nC'è qualcuno che potrebbe aiutarti ancora, {name}. Va' ad Azshara e trova il cacciatore di demoni Loramus Thalipedes. Cerca sulle isole.", "Che ci fai qui?", "Ti aiuterò. Anche se non credo che tu abbia capito fino in fondo contro cosa ti stai mettendo.", 0x94f424b7, 0x52d8585c, 0xada03b34, 0xb27a2670, 0xb056674e, "....." },
  [2745] = { "Infiltrarsi nel castello", "Parla con Tyrion nel Castello di ⟦Stormwind=Roccavento⟧.", "Mmm, una storia interessante, e da non prendere alla leggera. Sì, posso aiutarti, ma se vuoi andare fino in fondo dovrai amministrare una forma di giustizia che non è... legale.\n\nLescovar e Marzon vanno sistemati, e in fretta. Credi di essere all'altezza?\n\nDecidi tu. Se sì, corri al castello e trova un mio vecchio amico, uno gnomo di nome Tyrion. Tiene d'occhio Lescovar da un paio di settimane. Dovrebbe poterti aiutare a chiudere la faccenda.", nil, "Ma che...?! Non arrivarmi alle spalle così! E abbassa la voce! In nome dell'Ombra, che ci fai qui ad arrivarmi di soppiatto? Non vedi che ho da fare, razza di <stupido/stupida>?\n\nCome sarebbe, cosa sto facendo? Aspetto che si apra il prossimo Portale Oscuro, cosa diavolo credi che stia facendo? Di' quello che hai da dire e vattene... prima che le guardie notino noi due nascosti insieme tra i cespugli. Ho una reputazione da difendere.", 0x8aa81dca, 0xffe1ba3d, 0x31a5101a, nil, 0xd55e7590, "...m." },
  [2746] = { "Oggetti di una certa importanza", "Porta 3 ⟦Silk Cloth=Tessuto di Seta⟧ e 2 Mela Fresca di Clara a Tyrion, a ⟦Stormwind=Roccavento⟧.", "Trias vuole anticipare un po' i tempi, eh? D'accordo, si può fare, ma non sono pronto. E sappi questo: la parte difficile la faccio io, ma sei tu <quello/quella> che si sporcherà le mani, capito? Bene.\n\nAllora, prima di mettere in atto il mio piano mi serve che tu mi procuri alcune cose. Ho il travestimento perfetto per far passare Spybot davanti a quelle guardie.\n\nPortami un po' di seta e un paio di mele. Per la seta fai tu, ma la fattoria di Clara, appena fuori città, ha mele della misura perfetta.", "Tengo d'occhio Lescovar da un paio di settimane. Trias non si è mai fidato di lui, ma non sospettavamo che avesse a che fare con la ⟦Defias Brotherhood=Fratellanza dei Defias⟧. Stavamo seguendo piste che lo legavano al ⟦Twilight's Hammer=Martello del Crepuscolo⟧. In ogni caso, è diventato più pericoloso di quanto questa città possa gestire, ed è qui che entriamo in gioco noi.\n\nProcurami quegli oggetti e potremo mettere in atto il mio piano.", "Andranno benissimo, {name}. Ottimo lavoro.\n\nIl resto dell'attrezzatura che mi serve ce l'ho nello zaino... grazie alla Luce, ho appena fatto fare una borsa di seta a un mio amico sarto. Stavo finendo lo spazio per portarmi dietro tutta la roba.\n\nPrima che Spybot entri, definiamo i dettagli, così sai cosa devi fare.", 0x1f4eb590, 0x1d0c75b3, 0x1b56c1ff, 0xb3384936, 0x8b76d0c1, ".....", nil, nil, 0xde7d35a2, nil, nil },
  [2751] = { "Armamenti barbarici", "Porta 2 ⟦Patterned Bronze Bracers=Bracciali di Bronzo Decorati⟧, 2 Granspada di Bronzo e 2 Artiglio Affilato a Orokk Omosh a Orgrimmar.", "Venti generazioni di Omosh hanno impugnato questo martello, {name}. Centomila tonnellate di metallo abbiamo forgiato. Tragicamente, tutto finisce con Orokk, il fallimento degli Omosh: senza parenti e incapace di avere discendenti.\n\nNon posso lasciare che le ricette segrete degli Omosh muoiano con me! Qualcuno deve portare avanti l'eredità, Omosh o no!\n\nDimostra a Orokk che sei capace, {name}. Porta a Orokk quanto segue: due Bracciali di Bronzo Decorati, due Granspade di Bronzo e due Artigli Affilati. Portali a Orokk e andremo avanti.", "Bronzo, {name}! Altro bronzo!!", "La stirpe svanirà, ma forse la leggenda degli Omosh continuerà!\n\nHai dimostrato di essere un fabbro, {name}. Per il fabbro, la ricompensa è la soddisfazione di vedere le proprie armi e armature ricoperte del sangue dei nemici!\n\nChe le corazze che creerai per le generazioni future siano intrise del sangue dei tuoi nemici!", 0x17a1e905, 0x5f866922, 0x7a95f0a5, 0x718616f8, 0x90223961, "....." },
  [2752] = { "Sui paraspalle di ferro", "Porta 4 Ascia da Battaglia di Bronzo e 4 Martello da Guerra di Bronzo a Orokk Omosh a Orgrimmar.", "Orokk vede l'entusiasmo nei tuoi occhi, {name}. Come una spugna assorbi la saggezza degli Omosh.\n\nTre lezioni io insegnerò!\n\nTorna all'incudine, impregnati del calore della forgia e crea per Orokk quattro Asce da Battaglia di Bronzo e quattro Martelli da Guerra di Bronzo. Solo allora conoscerai il segreto del paraspalle di ferro.", "Mostrami la tua dedizione, {race}.", "Rendi fiero Orokk, {name}. Leggi e scopri i segreti dei paraspalle di ferro!", 0xf7581b4d, 0x57479f8c, 0xb4647cff, 0x31673690, 0x16d86607, "....." },
  [2753] = { "Schiacciati sotto i piedi", "Porta 4 Elmo di Ferro Verde, 4 ⟦Green Iron Bracers=Bracciali di Ferro Verdi⟧ e 2 ⟦Green Iron Leggings=Gambiere di Ferro Verdi⟧ a Orokk Omosh a Orgrimmar.", "Solo altre due lezioni Orokk insegnerà, {name}. I tuoi muscoli fanno male, lo so, ma continua per gli Omosh!\n\nPorta a Orokk quattro elmi di ferro verde, quattro bracciali di ferro verdi e due gambiere di ferro verdi: così tu impari e i tuoi nemici soffrono!", "I loro crani si spaccheranno sotto il peso dei tuoi stivali!", "Tu ricordi a Orokk suo nonno, il capo Gorokk degli Omosh! Leggi, impara dello stivale di ferro.", 0x910ff756, 0xaf1751cb, 0x89658ce5, 0x8fb855cc, 0x65ef0b88, "....." },
  [2754] = { "Corni della frenesia", "Porta 2 Maglio di Ferro Solido, 2 ⟦Silvered Bronze Boots=Stivali di Bronzo Argentato⟧ e 2 ⟦Silvered Bronze Gauntlets=Guanti di Bronzo Argentato⟧ a Orokk Omosh a Orgrimmar.", "L'ultima lezione che Orokk ti insegna, {name}. All'incudine e alla forgia sacre tu ritorni! Porta per Orokk due magli di ferro solido, due stivali di bronzo argentato e due guanti di bronzo argentato.\n\nGuarda la paura nei loro occhi quando ti avvicini!", "Mostra al ferro chi comanda, {name}!", "Stupefacente! Hai imparato la via degli Omosh, {name}!", 0xda80e91d, 0xcba97f38, 0xe496585c, 0x255ff424, 0xf310ad15, "....." },
  [2755] = { "Le gioie degli Omosh", "Guarda e impara la danza della gioia degli Omosh.", "Orokk non piange, {name}. Fuliggine in occhio.\n\n<Orokk si asciuga una lacrima.>\n\nC'è un ultimo segreto della famiglia Omosh che Orokk ti insegnerà. Orokk morirà felice, grazie a {name}.\n\nImpara danza della gioia degli Omosh e poi impari pugno di ferro!", nil, "<Orokk ansima.>\n\nÈ passato molto tempo da quando Orokk ha fatto la danza della gioia degli Omosh. Impara ora, {name}!", 0x69671f62, 0x90c19859, 0x16aecffb, nil, 0xc6b8ccc7, "...m." },
  [2756] = { "Le antiche usanze", "Porta 4 Pettorale Corazzato d'Acciaio e 4 Elmo d'Acciaio Runico ad Aturk l'Incudine, a Orgrimmar.", "Ai tempi delle leggende, Aturk frantumava i crani dei suoi nemici e ne macinava le ossa in una polvere sottile da usare come filamento. Quei giorni sono finiti da un pezzo, {race}. Il Capoguerra chiede la pace tra i clan. I vecchi nemici ora vengono solo osservati con occhi stanchi!\n\nIncredibile, lo so, ma tale è la volontà di Thrall.\n\nBasta lamentarsi! Sei qui per imparare, e imparerai! Portami quattro pettorali d'acciaio e quattro elmi d'acciaio e avrai un assaggio di guerra!", "Aturk, come il tempo, non aspetta nessuno! Sbrigati, idiota!", "A quanto pare sei solo un altro docile pecorone del Capoguerra, {name}. Che delusione.\n\nQuanto desidero una morte gloriosa sul campo di battaglia. E invece sono bloccato qui, per ordine di Thrall, a insegnare il mestiere ai poppanti! Guarda e impara, <pivello/pivella>!", 0x4e5f99d2, 0x111e7523, 0xd7eb3c98, 0xfa65622b, 0xd7251ac5, "....." },
  [2757] = { "⟦Booty Bay=Baia del Bottino⟧ o niente!", "Parla con McGavan alla ⟦Booty Bay=Baia del Bottino⟧.", "Ascolta, <ragazzo/ragazza>, non imparerai niente restando qui a gironzolare.\n\nConosco un tizio che conosce un tizio. Bazzica la fucina della ⟦Booty Bay=Baia del Bottino⟧. Se gli mostri questa insegna, ti racconterà tutto sul mithril.\n\nAllora, che ne dici? Lascia queste cose da principianti ai poppanti in fasce, {name}: è ora di andare avanti.\n\nSe ti interessa, si chiama McGavan. Mostragli questo ninnolo e riconoscerà il tuo impegno.", "Quelli come te sono una razza rara, compare. Fammi vedere quell'insegna.", "Per i peli della schiena di Blackhoof... finalmente qualcuno degno del Mithril Order!", 0x201687f5, 0x76671185, 0x8d214fc9, 0xbd77d15c, 0x83bb6990, "....." },
  [2758] = { "Le origini della forgiatura", "Porta 6 ⟦Golden Scale Bracers=Bracciali di Scaglie d'Oro⟧ a Hank il Martello, a ⟦Stormwind=Roccavento⟧.", "Quando avevo più o meno la tua età, un nano di nome Galvan mi prese sotto la sua ala e mi insegnò l'arte del fabbro d'armature. Prima di partire per la ⟦Booty Bay=Baia del Bottino⟧, mi fece promettere di addestrare tutti coloro che avessero il desiderio e la determinazione di progredire nell'arte della forgiatura; ed eccomi qui, dopo tutti questi anni.\n\nE ora è il momento che tu impari qualcosa. Fabbricami sei bracciali di scaglie d'oro e scoprirai da dove nasce la forgiatura, {name}.", "Potresti essere tu <il/la> prossim<o/a> protett<o/a> di Galvan?", "Molto bene, {name}! Ascolta e impara.\n\nLa forgiatura non nasce mai da qui! <Hank indica il suo martello.>\n\nLa forgiatura non nasce mai da qui! <Hank indica l'incudine.>\n\nLa forgiatura nasce solo da qui! <Hank indica il suo cuore.>\n\nE ora conosci l'origine della forgiatura.", 0x5dd39489, 0x350387d3, 0x870eb53b, 0x1e10ca8a, 0xeb39dca0, "....." },
  [2759] = { "In cerca di Galvan", "Parla con McGavan alla ⟦Booty Bay=Baia del Bottino⟧.", "Anche se Galvan ha lasciato la ⟦Booty Bay=Baia del Bottino⟧ molti anni fa, alcuni membri dell'ordine sono ancora in città, nella speranza di trovare un giorno qualcun altro degno degli insegnamenti di Galvan.\n\nPrendi questa insegna e presentala a McGavan, alla ⟦Booty Bay=Baia del Bottino⟧.\n\nSe davvero arrivi fin lì, saprà che ne sei degn<o/a>. Ho fiducia in te, {name}!", "Quelli come te sono una razza rara, compare. Fammi vedere quell'insegna.", "Per i peli della schiena di Blackhoof... finalmente qualcuno degno del Mithril Order!", 0x4dfe8db2, 0x76671185, 0x9fa6b639, 0xbd77d15c, 0x83bb6990, "....." },
  [2760] = { nil, "Parla con Galvan l'Antico nella Valle di Rovotorto.", "La maggior parte delle nostre reclute non arriva mai a ⟦Booty Bay=Baia del Bottino⟧, {name}. Lo scintillio dell'insegna basta a scatenare la brama di bottino anche nel più saldo dei fabbri. Che sciocchi, perché l'insegna è una goccia nel mare in confronto alle ricchezze che vedrai!\n\nTrova Galvan l'Antico e mostragli questa spilla. La sua dimora è molto a nord, tra Zul'gurub e il Tumulo degli Ogre Mosh'ogg.", "Salute! Avvicinati; mostra a Galvan cosa hai.", "Ah, sono passati molti anni dall'ultima volta che qualcuno si è dimostrato degno dell'iniziazione del Mithril Order. Cominciamo subito!", 0x569a9c64, 0xa93e34db, 0x8f04f385, 0x5db33734, 0x2f763df1, "e...." },
  [2761] = { "Fondi e rifondi", "Porta 40 Lingotto di Mithril e 40 Lingotto di Ferro a Galvan l'Antico, a Rovotorto.", "Molti fabbri credono che estrazione e forgiatura siano mestieri separati e indipendenti; ma può esistere la forgiatura senza l'estrazione? Ah ah! È impossibile! Il fabbro provetto dev'essere anche un minatore provetto.\n\nDimostra a Galvan di essere all'altezza, {name}. Portami quaranta lingotti di ferro e quaranta lingotti di mithril. In cambio, Galvan ti insegnerà i segreti dei pantaloni di mithril decorati!", "Dopo tanto scavare, i muscoli si gonfiano e il corpo fa male!", "La tua etica del lavoro è impeccabile, {name}! Stai cominciando a capire le vie della mineralogia di Galvan! Prendi questo e impara tutto ciò che puoi.", 0x4717cd13, 0x15538102, 0x6f06ffe2, 0x5c6d8c09, 0x8470c433, "....." },
  [2762] = { "Il grande ingannatore d'argento", "Porta 40 Lingotto di Mithril e 5 Lingotto di Verargento a Galvan l'Antico, a Rovotorto.", "Si dice che il verargento sia più forte e più resistente del mithril. Galvan non contesta questa valutazione dei minerali, ma contrariamente al suo nome, il verargento non è affatto vero! Il mithril è un minerale ben più nobile! AH! Comunque sia, per questa lezione dovrai trovare il grande ingannatore d'argento, {name}.\n\nPortami quaranta lingotti di mithril e cinque lingotti di verargento. In cambio, ti verrà insegnato il segreto dei guanti di mithril decorati e, cosa ben più importante, imparerai che il verargento è un bugiardo!", "Dopo tanto scavare, i muscoli si gonfiano e il corpo fa male!", "È un'amante crudele, non è vero, {name}? Parlo del verargento, naturalmente. Già, Galvan ha passato più di dieci anni sulle Montagne d'Alterac per imparare questa lezione. Prendi questo e impara tutto ciò che puoi!", 0xc46fcd5c, 0xc623695f, 0xd9fa85a8, 0x5c6d8c09, 0xa96f4203, "....." },
  [2763] = { "L'arte dell'infusione", "Porta 40 Lingotto di Mithril e 4 Citrine a Galvan l'Antico, a Rovotorto.", "La raccolta delle gemme preziose è della massima importanza per il nostro mestiere, {name}. Poche gemme sono più preziose del citrino. Le proprietà magiche che infondiamo nei nostri manufatti vengono enormemente amplificate dalla presenza del citrino.\n\nPer questa lezione, rafforzeremo quaranta lingotti di mithril con quattro citrini. Il risultato sarà una migliore comprensione della gemmologia magica e la conoscenza per creare spallacci di mithril decorati.", "Dopo tanto scavare, i muscoli si gonfiano e il corpo fa male!", "È difficile staccare gli occhi dal suo splendore, {name}. Già, il citrino è una gemma gloriosa.\n\nPresta attenzione e impara ciò che una simile scoperta può insegnarci!", 0xf2f52fac, 0xdf13f115, 0xf5af3a64, 0x5c6d8c09, 0x7cc58672, "....." },
  [2764] = { "Il miglior allievo di Galvan", "Parla con Trenton Lighthammer a ⟦Gadgetzan=Meccania⟧.", "Se sei pront<o/a> a concludere il tuo addestramento con Galvan, dovresti recarti a ⟦Gadgetzan=Meccania⟧.\n\nLì troverai il mio miglior allievo: Trenton Lighthammer. Ha molto da insegnarti sulle vie del mithril decorato. Altrimenti, resta qui e impara!\n\nOh, ⟦Gadgetzan=Meccania⟧ è a Tanaris, naturalmente!", nil, "Ti manda Galvan l'Antico??\n\n<Trenton si inchina.>\n\nÈ un grande onore conoscere qualcun altro che ha studiato con il maestro!", 0xa8a42fec, 0xcd48da8f, 0x7bd100a2, nil, 0x4513ea46, "...m." },
  [2765] = { "⟦Expert Blacksmith=Fabbro Esperto⟧!", "Riscuoti la tua ricompensa da Galvan l'Antico!", "Quando sei venut<o/a> da me la prima volta, sapevo che saresti diventat<o/a> <uno/una> dei miei migliori allievi! Senza esitare hai ceduto a McGavan un monile di un certo potere. L'hai fatto solo per poter incontrare me. Una fede cieca e una devozione al mestiere come queste meritano una ricompensa.\n\nHai raggiunto la maestria nell'arte del fabbro, {name}. Raccogline i frutti!", nil, "È giusto che tu riceva un monile ben più potente di quello che hai sacrificato per arrivare fin qui. Usalo in buona salute, {name}.", 0x54c35794, 0x66460dd6, 0x62ca6d71, nil, 0xffcf7017, "...m." },
  [2766] = { "Trova OOX-22/FE!", "Porta il trasmettitore d'emergenza al robot autoguidato di Oglethorpe, in una grotta vicino a ⟦Feral Scar Vale=Valsfregiata⟧.", "Hai scoperto una sorta di strano congegno metallico a forma di uovo. Armeggiando con una delle sue manopole, l'uovo prende vita e si apre trasformandosi in una specie di marchingegno robotico gnomesco! Dall'interno dell'uovo robotico gracchia una voce.\n\n\"Mi chiamo Oglethorpe Obnoticus, e il mio robot autoguidato è precipitato! Ti ricompenserò se lo recuperi; ti prego, porta questo trasmettitore al robot!\"\n\n\"Ho calcolato per te le coordinate del robot: si trova in una grotta vicino a ⟦Feral Scar Vale=Valsfregiata⟧!\"", "A quanto pare hai trovato i rottami di... un pollo robotico? La voce dall'interno dell'uovo gracchia di nuovo:\n\n\"Sì, ottimo lavoro! Questo è proprio il mio robot autoguidato, anche se i miei sensori indicano che ha bisogno di una spintarella prima di poter volare di nuovo a ⟦Booty Bay=Baia del Bottino⟧ per le riparazioni. Su, metti il trasmettitore dentro il robot: al resto penserà il trasmettitore!\"", "Metti l'uovo... il trasmettitore d'emergenza... dentro il pollo... il robot autoguidato.\n\nDall'interno del robot si sentono ronzii e fruscii mentre cerca a fatica di rimettersi in piedi. Quando il robot prende vita, si sente di nuovo la voce di Oglethorpe, ma ora dall'interno del robot:\n\n\"Almeno OOX-22/FE funziona, ma ha bisogno di grosse riparazioni! È troppo pesante perché tu possa trasportarlo... ma credo di avere un'idea. Te la senti di vegliare ancora un po' su di lui?\"", 0x66c4048e, 0x7e3d9c73, 0xa871c89f, 0xae44575b, 0x5f146e7e, "....." },
  [2767] = { "Salva OOX-22/FE!", "Scorta OOX-22/FE fino al molo lungo la Costa dell'Oblio, poi fai rapporto a Oglethorpe Obnoticus a ⟦Booty Bay=Baia del Bottino⟧.", "La voce dello gnomo gracchia di nuovo dal robot:\n\n\"Devo spostare OOX-22/FE in un luogo aperto e sicuro, perché possa avviare una lunga procedura di decollo. Ha un occultamento integrato, ma mi serve tempo, da parte mia, per rimetterlo in funzione. Scorta il robot dalla sua posizione attuale fino, diciamo, al molo lungo la Costa dell'Oblio! Dovrebbe essere il posto perfetto, e il tempo sufficiente, per rimettere tutto in linea!\"\n\n\"Scortalo sano e salvo fino al molo, poi vieni a parlarmi a ⟦Booty Bay=Baia del Bottino⟧! Oglethorpe Obnoticus, passo e chiudo!\"", "Sì, sono Oglethorpe Obnoticus, mastro inventore al tuo servizio! Allora, c'è qualcosa in cui posso aiutarti?", "Oh, sei TU <il/la> grande salva<tore/trice> di OOX-22/FE! Non so nemmeno come cominciare a ringraziarti per il tuo aiuto! La mia serie di robot autoguidati ha bisogno di altro sviluppo, ma il tuo recupero mi ha risparmiato innumerevoli ore di ricostruzione e anche parecchi pezzi d'oro di costi di fabbricazione!\n\nTi prego, scegli quello che vuoi tra questi oggetti. Grazie ancora per il tuo generoso aiuto, {name}: io e i miei robot siamo in debito con te!", 0xa3042cf3, 0x89a547eb, 0x3e081a77, 0xa11d5fae, 0xd20da83c, "....." },
  [2768] = { "La Verga Divinomatica", "Porta la Divino-matic Rod all'ingegnere capo Bilgewhizzle a ⟦Gadgetzan=Meccania⟧.", "Il sergente Bly mi ha derubato! Ha detto che l'avrebbe solo preso in prestito, ma mi ha rubato la mia preziosa verga divinomatica!! Senza quella verga come faccio a sapere dove scavare nuovi pozzi??\n\nTrova Bly e riportami la mia verga! Ho sentito che ha guidato la sua banda di avventurieri di dubbia fama a caccia di tesori a ⟦Zul'Farrak=Zul'farrak⟧, a ovest. Scommetto che lo troverai lì.\n\nSperiamo che ci abbiano già pensato i troll, perché se dovrai combattere con lui per la verga, ti aspetta uno scontro serio.", "Hai trovato il sergente Bly? Hai recuperato la mia verga divinomatica?", "L'hai trovata! Ben fatto, {name}! Hai dovuto combattere con Bly per averla? Spero che tu abbia steso per bene lui e la sua banda!", 0x5062dadf, 0x5ecdd6a7, 0xa6f3d8cc, 0x7535d73e, 0x9ab2a77b, "....." },
  [2769] = { "I fratelli Brassbolts", "Parla con Wizzle Brassbolts nelle Distese Salate.", "Hai conosciuto i fratelli Brassbolts? Sono nelle Distese Salate, a Kalimdor, e sfidano i goblin con la loro auto a razzo. Di solito vincono, e non c'è da stupirsi: l'auto dei goblin salta in aria così spesso che non taglia quasi mai il traguardo!\n\nMa anche così, i fratelli Brassbolts cercano sempre nuovi modi per rendere la loro auto più veloce, e Wizzle mi ha detto che gli serve un componente molto raro per il suo prossimo esperimento.\n\nProbabilmente gli serve aiuto per procurarselo. Parla con lui e scoprilo.", nil, "Ah, vuoi aiutarmi? Fantastico!\n\nC'è un pezzo che mi serve per un esperimento a cui sto lavorando, e ho bisogno di <un/una> {class} coraggios<o/a> come te per procurarmelo!", 0x089469a7, 0xb1fcc703, 0x1fabb59b, nil, 0x80c2ec73, "...m." },
  [2770] = { nil, "Porta la ⟦Gahz'rilla's Electrified Scale=Scaglia Elettrificata di Gahz'rilla⟧ a Wizzle Brassbolts nelle Distese Salate.", "Nel cuore di ⟦Zul'Farrak=Zul'farrak⟧, la città dei troll delle sabbie a Tanaris, c'è una pozza sacra. Da quella pozza i troll evocano una bestia enorme! Gahz'rilla! È così feroce che persino le sue scaglie crepitano di energia. Ed è proprio quell'energia che voglio sfruttare per la mia auto!\n\nPortami la scaglia elettrificata di Gahz'rilla!\n\nMa l'evocazione di Gahz'rilla è un segreto ben custodito dei troll. Per affrontarlo, devi prima strappare loro il segreto.", "Hai la scaglia? Non vedo l'ora di provare modi diversi per sfruttarne l'energia!", "Wow, hai preso la scaglia! Grazie, {name}. Non vedo l'ora di mettermi al lavoro su questa cosa!\n\nQuindi hai visto Gahz'rilla? Era grosso come dicono??", 0x020c88eb, 0x1d10cf57, 0xd30442ce, 0xcc8dce4a, 0x7f35b7a9, "e...." },
  [2771] = { "Una buona testa sulle spalle", "Porta 2 Camaglio di Mithril e 1 Ornate Mithril Shoulder a Trenton Lighthammer.", "Sembra che il maestro avesse pianificato tutto fin dall'inizio. A me non è stato insegnato a creare gli oggetti che hai imparato a creare tu, e a te non sono stati insegnati quelli che ho imparato io.\n\nIl maestro è saggio, {name}. Ci insegneremo a vicenda!\n\nMostrami come si fanno un camaglio di mithril e degli spallacci di mithril decorati, e io ti mostrerò come creare un elmo di mithril decorato.", "Hai finito di forgiare gli oggetti, {name}?", "Eccellente! Uno scambio equo, se lo dico io. Guarda e impara, {name}!", 0xd4e4683b, 0x7a9ee4a2, 0x1014689c, 0x71e37944, 0xf6fdfe75, "....." },
  [2772] = { "Il mondo ai tuoi piedi", "Porta 2 ⟦Heavy Mithril Boots=Stivali Pesanti di Mithril⟧ e 1 ⟦Ornate Mithril Pants=Pantaloni di Mithril Decorati⟧ a Trenton Lighthammer.", "Al Campionato dei Fabbri di Tutta la Valle dell'anno scorso, tutti i presenti mi hanno visto finire a terra per uno sgambetto di un vile cane della fonderia della S.P.R. & Co. Quello che non sapevano, però, era il motivo per cui sono riuscito a continuare e alla fine a vincere il torneo: proprio così, gli stivali di mithril decorati!\n\nPer il torneo di quest'anno, però, dovrò imparare a forgiare i pantaloni di mithril decorati, perché tra i partecipanti c'è un segatronchi della S.P.R. & Co.! Insegnami la via dei pantaloni e imparerai la via degli stivali!", "Hai finito di forgiare gli oggetti, {name}?", "Avrai il mondo ai tuoi piedi, {name}! Che vengano pure a farti lo sgambetto: ormai nessuno può più buttarti a terra!", 0x090933fe, 0x4f45deb8, 0xb61b748b, 0x71e37944, 0x04ba94a1, "....." },
  [2773] = { "Il Ragazzo del Mithril", "Porta 2 Pettorale Corazzato Pesante di Mithril e 1 ⟦Ornate Mithril Gloves=Guanti di Mithril Decorati⟧ a Trenton Lighthammer.", "Da queste parti mi conoscono come il Ragazzo del Mithril. Fornisco mithril decorato ad avventurieri di tutto il mondo.\n\n<Trenton sussurra.>\n\nQuello che non sanno è che non conosco la tecnica per forgiare i guanti di mithril decorati. Sssh! Sarà il nostro piccolo segreto.\n\nInsegnami la tecnica per creare i guanti di mithril decorati, {name}, e in cambio ti mostrerò il frutto del culmine del mio addestramento con Galvan: il pettorale corazzato di mithril decorato.", "Hai finito di forgiare gli oggetti, {name}?", "Grazie per tutto ciò che mi hai insegnato, {name}. Il signore e padrone del completo di mithril decorato sarà presto tuo.\n\nEcco!", 0xc82def0d, 0xcf23ef19, 0x8eabfebf, 0x71e37944, 0xa14908be, "....." },
  [2781] = { "RICERCATO: Caliph Scorpidsting", "Porta la testa di Caliph Scorpidsting all'ingegnere capo Bilgewhizzle a ⟦Gadgetzan=Meccania⟧.", "RICERCATO: Caliph Scorpidsting!\n\nLa Compagnia Idrica di ⟦Gadgetzan=Meccania⟧, di ⟦Gadgetzan=Meccania⟧, Tanaris, pagherà una ricca taglia per la testa di Caliph Scorpidsting, capo dei fuorilegge Wastewander. I suoi crimini comprendono:\n\n1. L'omicidio di dipendenti della Compagnia Idrica di ⟦Gadgetzan=Meccania⟧!\n\n2. Il furto di risorse della Compagnia Idrica di ⟦Gadgetzan=Meccania⟧!\n\n3. L'occupazione di proprietà della Compagnia Idrica di ⟦Gadgetzan=Meccania⟧!\n\nPorta la prova della morte di Caliph Scorpidsting all'ingegnere capo Bilgewhizzle per una ricompensa immediata!", "Sì, {class}, sono un funzionario della Compagnia Idrica di ⟦Gadgetzan=Meccania⟧. In cosa posso esserti utile?", "Finalmente giustizia è fatta! Hai inferto un duro colpo a quegli spregevoli nomadi! Con la morte di Scorpidsting, potrebbe essere proprio la volta buona per cacciare quegli abusivi dai pozzi di ⟦Gadgetzan=Meccania⟧!\n\nPer l'autorità della Compagnia Idrica di ⟦Gadgetzan=Meccania⟧, ti consegno con piacere questa taglia. Hai reso un grande servizio a tutti noi.", 0xb61cb520, 0xf8907cbb, 0xf0bbc190, 0xbf6f0318, 0x71967060, "....." },
  [2782] = { "Il ⟦Rin'ji's Secret=Segreto di Rin'ji⟧", "Oran Snakewrithe, studiosa ben nota per le sue conoscenze sui troll Scorzasecca, potrebbe riuscire a decifrare la tavoletta. Si sa che risiede nel ⟦Magic Quarter=Quartiere della Magia⟧ di ⟦Undercity=Sepulcra⟧.", "La tavoletta è coperta di segni dei troll Scorzasecca. Il segreto di Rin'ji è davvero un mistero...\n\nÈ possibile che tu abbia tra le mani qualcosa di molto prezioso. D'altra parte, è possibile anche l'esatto contrario. Un troll Scorzasecca in difficoltà farebbe probabilmente di tutto pur di tirarsi fuori dai guai...", "Bene, bene, e questo cos'è?", "Questa tavoletta... Davvero insolita... Dove l'hai trovata, {name}?", 0x9db2ed6a, 0xacdc06a9, 0xc21069d7, 0xd520768c, 0x51b1062d, "....." },
  [2783] = { "Liti meschine", "Parla con l'Eroe Caduto dell'⟦Horde=Orda⟧, al confine tra le ⟦Blasted Lands=Terre Devastate⟧ e la palude.", "Combattiamo il nemico sbagliato, {name}.\n\nIl vero potere di queste terre continua a crescere in forza e numero mentre noi ci contendiamo terra bruciata con gli orchi.\n\nDobbiamo continuare a combattere in queste terre una guerra contro l'⟦Horde=Orda⟧, solo per essere travolti un giorno dagli eserciti della Legione Infuocata? È inutile.\n\nMetti da parte le divergenze, {name}, e parla con l'eroe caduto dell'⟦Horde=Orda⟧. Conosce la verità sulle ⟦Blasted Lands=Terre Devastate⟧.", nil, "L'⟦Alliance=Alleanza⟧ vuole aiutarci?\n\nPensavo che non avrei mai più visto questo giorno. Un giorno in cui l'⟦Alliance=Alleanza⟧ combatte fianco a fianco con l'⟦Horde=Orda⟧ contro un nemico comune.\n\nCosì sia... ci uniremo.", 0xfd0feee3, 0xdc8a1010, 0xa7547fc4, nil, 0x1a69cea0, "...m." },
  [2784] = { "La caduta in disgrazia", "Ascolta la storia dell'eroe caduto dell'⟦Horde=Orda⟧.", "Ascolta la mia storia, {race}.", "Ascolta ciò che ho da dire.", "Come spirito sono impotente, {name}. Aiutami. Permettimi di riconquistare il mio onore.", 0x8531d6e8, 0xcc5274d5, 0x896212bd, 0x35dae5cd, 0x9269440e, "....." },
  [2801] = { "Una storia di dolore", "Ascolta la storia dell'eroe caduto dell'⟦Horde=Orda⟧.", "Prima di andare avanti, devi ascoltare la mia storia.", "Ascolta ciò che ho da dire, {name}.", "È il momento di agire, {name}.", 0x76eea50b, 0xcc5274d5, 0x7cce8f86, 0x8967c526, 0x75013208, "....." },
  [2821] = { "Il marchio di qualità", "Porta 10 Pelle di Yeti Spessa a Pratt McGrubben a Feathermoon Stronghold.", "La mia filosofia sulla lavorazione del cuoio è che il lavoro deve essere della migliore qualità possibile, senza compromessi. Chiunque ti dica che la qualità non conta sta cercando di venderti una villa sul mare a Dun Morogh!\n\nNella mia ultima ricerca di materiali di alta qualità, mi sono imbattuto nelle pelli di yeti spesse. Gli yeti vivono a Feralas e se ne trovano molti a ⟦Feral Scar Vale=Valsfregiata⟧. Ne voglio un po', e per una pila di dieci ti lascerò scegliere uno dei miei articoli di cuoio. Se ti sembra giusto, siamo d'accordo.", "Una pila di dieci pelli di yeti spesse ti farà guadagnare uno dei miei articoli a scelta. Siccome tengo alla qualità, posso garantirti che avrai un buon oggetto!\n\nSe non riesci a trovare gli yeti, so dove potrebbero essercene alcuni. Prova a cercare appena nell'entroterra della Costa dell'Oblio, attorno a ⟦Feral Scar Vale=Valsfregiata⟧.", "Ti sei fermat<o/a> a esaminare la grana di queste pelli? Trattate a dovere, potrebbero essere persino più resistenti del ferro. Non molti conoscono queste pelli e questo, insieme alle tante soluzioni conciarie che conosco, mi permetterà forse di creare oggetti con un vero marchio di qualità... grazie a te, naturalmente!\n\nE ora, scegli pure tra ciò che posso offrirti per il tuo servizio!", 0x2849b87a, 0x3fd60048, 0x1df20f34, 0x3b3e3760, 0x7bf8bd37, "....." },
  [2822] = { "Il marchio di qualità", "Porta 10 Pelle di Yeti Spessa a Jangdor Swiftstrider all'⟦Camp Mojache=Accampamento Mojache⟧.", "Vado fiero del mio lavoro con il cuoio, e credo che si veda: la qualità non va mai compromessa. Chiunque dica che la qualità non conta ti farebbe credere anche che la terra non custodisce segreti!\n\nNella mia ultima ricerca di materiali di alta qualità, ho scoperto le pelli di yeti spesse. Gli yeti vivono a Feralas, spesso a ovest di qui, a ⟦Feral Scar Vale=Valsfregiata⟧. Per una pila di dieci ti lascerò scegliere uno dei miei articoli di cuoio. Se ti va bene, siamo d'accordo!", "Sei riuscit<o/a> a procurarti una pila di dieci pelli di yeti spesse? I miei articoli di cuoio non sono secondi a nessuno, e te ne farò scegliere uno se hai le pelli.\n\nSe non riesci a trovare gli yeti, so dove potrebbero essercene alcuni. Prova a cercare a ovest di qui, appena nell'entroterra della Costa dell'Oblio, attorno a ⟦Feral Scar Vale=Valsfregiata⟧.", "Ah, eccellente! Queste pelli, con un trattamento speciale, sono resistenti come il ferro, te lo dico io! Ci vorranno molti tentativi per trovare la miscela giusta per la concia, ma sono sicuro che porteranno il mio marchio di qualità a un livello superiore.\n\nQuanto a te, {name}... il tuo aiuto si è rivelato prezioso. Scegli pure tra questi oggetti che ho creato.", 0x2849b87a, 0xc0f5fd2f, 0xf3e7743d, 0xa1aa3678, 0x64f1fdb0, "....." },
  [2841] = { "Guerra di macchine", "Recupera i ⟦Rig Blueprints=Progetti Modificati⟧ e Thermaplugg's Safe Combination a Gnomeregan e portali a Nogg a Orgrimmar.", "La tecnologia degli gnomi: due anni fa la si usava soprattutto per farci battute. I tempi sono proprio cambiati. Ora hanno costruito una nuova macchina che è meglio di tutti i nostri modelli di segatronchi messi insieme. Mi servono i progetti, {name}!\n\nPurtroppo i progetti sono chiusi in una cassaforte vicino a Mekgineer Thermaplugg. E come se non bastasse, la combinazione della cassaforte la conosce solo Mekgineer Thermaplugg.\n\nFa' tutto quello che serve per avere quella combinazione, {name}. Poi apri quella cassaforte e riportami quei progetti!", "Non vedo nessun progetto. Li hai nascosti da qualche parte addosso o te ne stai qui solo per irritarmi?", "Sapevo che ce l'avresti fatta, {name}! Sovik invece aveva i suoi dubbi.\n\n<Nogg si schiarisce la gola.>\n\nOra che abbiamo i progetti, è solo questione di tempo prima di capire tutte le innovazioni degli gnomi che sono servite a costruire la macchina e trasformarle in innovazioni goblin per i nostri nuovi modelli di segatronchi.", 0xcf5a7376, 0x0da92dea, 0xe80d6917, 0xc41d80f1, 0xbb1889bb, "....." },
  [2842] = { "L'ingegnere capo Scooty", "Parla con Scooty alla ⟦Booty Bay=Baia del Bottino⟧.", "Appena Kernobee ci ha dato notizia della nuova macchina degli gnomi, io e Scooty ci siamo messi al lavoro sul Transpolyporter 6000: il modo più veloce e affidabile per arrivare a Gnomeregan.\n\nFinalmente è pronto a imbarcare passeggeri, {name}. Se vuoi provarlo, va' alla ⟦Booty Bay=Baia del Bottino⟧ e parla con Scooty al posatoio delle viverne. Per arrivare alla ⟦Booty Bay=Baia del Bottino⟧, prendi la nave da ⟦Ratchet=Porto Paranco⟧.\n\nCerto, potresti sempre tentare di raggiungere Gnomeregan attraverso le montagne di Dun Morogh infestate dai nani!", nil, "È una bellezza, vero? Il massimo della tecnologia goblin dei trasporti: è esplosa solo una dozzina di volte, più o meno.\n\nNon preoccuparti, {name}, l'ho sistemata per bene. Non ti esploderà sotto i piedi, e se succede, sarà rapido e indolore.", 0x8bca8052, 0xfcd92c6b, 0x7f138176, nil, 0xc0853908, "...m." },
  [2843] = { "Gnomeregan, arrivoooo!", "Aspetta che Scooty calibri il ⟦Goblin Transponder=Segnalatore dei Goblin⟧.", "Finché hai con te il segnalatore, devi solo salire sulla piattaforma e verrai teletrasportat<o/a> a Gnomeregan.\n\nPotresti avere qualche effetto collaterale insolito, ma nessuno dovrebbe essere permanente... non più.\n\nStavo quasi dimenticando la parte più importante: il ritorno. Quando vorrai tornare, sali sulla piattaforma del transpolyporter a Gnomeregan!\n\nOra calibro il segnalatore sulla tua taglia e sul tuo peso.", "È pronto!", "Fatto! Quando sei pront<o/a>, sali sulla piattaforma.", 0xbb614da5, 0xec9deafb, 0xed51c3c5, 0x8ea737cf, 0x32ca58dc, "....." },
  [2844] = { "Il guardiano gigante", "Trova la bambina elfa della notte che si è persa.", "Sono un buono a nulla, {name}. Dovevo badare alla mia piccola amica, Shay, e in qualche modo mi è scappata. Non so bene cos'è successo, a dire il vero, ma l'ultima volta che l'ho vista stavamo camminando tra le rovine appena a nord di qui.\n\nAndava tutto bene, ma poi mi sono girato e... era sparita.\n\nOra proprio non riesco a capire cosa dovrei fare. Hai qualche idea, {name}? Sono tanto preoccupato.\n\nEhi, che ne dici di andare tu a cercare Shay? Le tue gambe vanno molto più svelte delle mie.", nil, "Oh, sono così felice che tu mi abbia trovata! Devo ammettere che mi sono un po' persa... Ma non è un posto bellissimo?", 0x4901404e, 0x55e72e8a, 0x7c246465, nil, 0x8e2ac637, "...m." },
  [2845] = { "Shay la girovaga", "Prendi la ⟦Shay's Bell=Campana di Shay⟧ dal forziere.\n\nScorta Shay Leafrunner all'accampamento di Rockbiter.", "Pensi di potermi aiutare a ritrovare la strada per tornare dal mio amico Rockbiter? Doveva badare a me... ma ogni tanto ho la tendenza ad allontanarmi. Ci sono così tante cose da vedere, e mi distraggo così facilmente.\n\nC'è però una cosa che riesce sempre ad attirare la mia attenzione.\n\nIn questo forziere troverai una campana a cui tengo moltissimo. Adoro il suo suono. Ti do la mia parola: se mi allontano, non devi far altro che suonarla e io tornerò di corsa.", "Cominciavo a preoccuparmi per te! Grazie mille per aver riportato Shay a casa, {name}.", "Cosa? Dici che 'sta campana funziona quando Shay scappa? Ma guarda un po'!\n\nVisto che hai fatto tanto per me, ecco qua, {name}.", 0x7a831151, 0x0dfd54bb, 0x78a146db, 0x787391f0, 0x7d16be98, "....." },
  [2846] = { "La ⟦Tiara of the Deep=Tiara del Profondo⟧", "Porta la ⟦Tiara of the Deep=Tiara del Profondo⟧ a Tabetha, ad ⟦Dustwallow Marsh=Acquemorte⟧.", "Tempo fa possedevo un gioiello stupendo, la ⟦Tiara of the Deep=Tiara del Profondo⟧. E non era solo bella: racchiudeva un grande potere per chi sapeva usarla.\n\nCosì, quando la notizia della tiara giunse all'idromante Velratha, lei volle averla a ogni costo. Mandò i suoi agenti a casa mia e la rubarono mentre ero via. Ladri!\n\nRivoglio la mia tiara! Va' a ⟦Zul'Farrak=Zul'farrak⟧, la città dei troll a Tanaris, trova Velratha e strappale la tiara. Riportamela e ti guadagnerai il mio favore.", "Hai la tiara, {name}? Velratha ha imparato quanto costa mettersi contro di me?", "Magnifico! L'hai trovata! E, cosa altrettanto importante, Velratha non ce l'ha più! Grazie, {name}. Ti sarò debitrice per sempre!\n\nE se prima ti sono sembrata un po'... cattiva, non farci caso. Con chi non mi ha derubata sono una persona molto più gentile.", 0x9db75a34, 0x182805f8, 0xea00f20d, 0xe3059e4c, 0x116c565f, "....." },
  [2847] = { "Armatura di Cuoio Selvatico", "Porta 10 ⟦Thick Leather=Cuoio Spesso⟧ a Pratt McGrubben, a Feathermoon Stronghold.", "{name}, stai diventando davvero brav<o/a> come conciat<ore/rice>! Conosco alcuni schemi che potrebbero interessarti... l'armatura di Cuoio Selvatico! Il Cuoio Selvatico attinge alle proprietà potenti e caotiche della vite selvaggia, che si trova nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che le abitano. Per qualcuno con la tua abilità, l'armatura che se ne ricava non ha rivali, garantito.\n\nTe lo insegnerò, ma per un po' lavorerai per me. Il primo prezzo è semplicemente di dieci pezzi di cuoio spesso. Dopo, parleremo dei dettagli.", "Come ti ho detto, lavorerai per me mentre impari a conoscere l'armatura di Cuoio Selvatico. Poiché la vite selvaggia è potente e caotica, conferisce un beneficio casuale ma forte all'armatura, già robusta, che realizzerai. Questa conoscenza, però, non è stata facile da ottenere per me.\n\nIl prezzo iniziale per cominciare è di dieci pezzi di cuoio spesso.\n\nFatto questo, passeremo al lavoro che dovrai svolgere per ottenere gli schemi.", "Be', {name}, sono contento di averti nella squadra. Hai fatto una scelta furba come conciat<ore/rice>; chi indossa armature di cuoio farà a gara per averti, una volta che avrai imparato a fare uno qualsiasi dei pezzi dell'armatura di Cuoio Selvatico.\n\nMettiamoci al lavoro: da dove vuoi cominciare?", 0x053a8360, 0xf6a18def, 0x5c5bf7ef, 0x62f7bc20, 0xfcbb1f9d, "....." },
  [2848] = { "⟦Wild Leather Shoulders=Spallacci di Cuoio Selvatico⟧", "Porta 6 Potenziamento d'Armatura Spesso e un Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", "Gli spallacci di Cuoio Selvatico sostengono benissimo la corporatura di chi li indossa, offrendo una protezione di prim'ordine alla parte alta delle braccia e alle spalle stesse. Come per tutta l'armatura di Cuoio Selvatico, quando la vite selvaggia viene cucita nel pezzo, gli conferisce un beneficio potente ma casuale.\n\nPer questo schema mi serviranno sei potenziamenti d'armatura spessi e una vite selvaggia. Non dovrebbe essere una richiesta troppo difficile da soddisfare per te.", "Hai i sei potenziamenti d'armatura spessi e la vite selvaggia che ti ho chiesto?\n\nNon pensare che fabbricare potenziamenti d'armatura sia un lavoro monotono: il metodo costante che sviluppi esercitando il mestiere su questi potenziamenti affina l'abilità necessaria per il lavoro minuzioso che richiede l'armatura di Cuoio Selvatico.\n\nVisto? C'è un vero motivo dietro quello che stai facendo per me...", "Questi potenziamenti d'armatura sono di qualità solida, {name}. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi lavora per me, è la qualità.\n\nTi sei guadagnat<o/a> questo schema; spero che ti porti le ricompense che ha portato a me.", 0x765de05b, 0x5fd85b49, 0xebba0586, 0xc673456c, 0xddffc6c0, "....." },
  [2849] = { "⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧", "Porta 2 Pettorale Corazzato di ⟦Turtle Scale=Scaglie di Tartaruga⟧, 2 ⟦Turtle Scale Gloves=Guanti di Scaglie di Tartaruga⟧ e un Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", "La veste di Cuoio Selvatico è il pezzo fondamentale di ogni completo di Cuoio Selvatico. La struttura della veste si fonde con la vite selvaggia, dando un capo che offre la massima protezione al torso e lascia che la potente magia scorra attraverso l'indumento.\n\nPer questo schema mi serviranno due pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧, due paia di guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧ e una vite selvaggia. È una richiesta impegnativa, ma per te non dovrebbe essere difficile soddisfarla.", "Hai i due pettorali corazzati e i guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧ che ti ho ordinato? E non dimenticare la vite selvaggia!\n\nGià con i primi schemi impariamo che i fondamenti della forma si trasferiscono bene a indumenti più difficili. Anche se sono oggetti diversi, la forma dei pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧ ti prepara ai dettagli necessari per fare una veste di Cuoio Selvatico.\n\nE i guanti... be', quelli sono solo per me. Ricorda, lavori per me!", "Sono pezzi davvero belli, {name}. Per la maestria e la cura messe nel farli, si venderebbero a parecchio argento in più di un pezzo qualunque.\n\nHai completato il mio ordine, e con esso arriva la tua ricompensa. La conoscenza per fare le vesti di Cuoio Selvatico ora è tua!", 0x762367c6, 0xe2688b0f, 0xcfbb37a9, 0x84b4761f, 0x4389a2a4, "....." },
  [2850] = { "⟦Wild Leather Helmet=Elmetto di Cuoio Selvatico⟧", "Porta 2 Giubba della Fuga Notturna, 2 Banda della Fuga Notturna e un Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", "Un elmetto di Cuoio Selvatico offre a chi lo indossa una protezione superiore delle parti vitali della testa, senza sacrificare la comodità. Come per tutta l'armatura di Cuoio Selvatico, la vite selvaggia integrata conferisce alla struttura dell'elmo un potenziamento potente ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!\n\nPer questo schema mi serviranno due giubbe della Fuga Notturna, due bande della Fuga Notturna e una vite selvaggia. Completa questo ordine e lo schema sarà tuo!", "Mi servono quelle giubbe e quelle bande, e mi serve anche quella vite selvaggia, prima di condividere con te la conoscenza degli elmetti di Cuoio Selvatico.\n\nI copricapi sono molto ambiti tra gli avventurieri, che si tratti di una banda di una semplicità disarmante o di un elmetto che copre tutta la testa. I fondamenti per creare un copricapo di valore restano gli stessi, qualunque sia il suo aspetto.", "Questo equipaggiamento della Fuga Notturna che mi hai fornito soddisfa l'ordine alla perfezione, {name}. Non mi aspetto niente di meno da <un/una> conciat<ore/rice> del tuo calibro.\n\nTi sei decisamente guadagnat<o/a> questo schema. Te lo do volentieri, e spero che saprai trarne profitto.", 0xa93a2f88, 0xb3a4a52f, 0x276d4784, 0xe1bd53bd, 0x944bc44f, "....." },
  [2851] = { "⟦Wild Leather Boots=Stivali di Cuoio Selvatico⟧", "Porta 2 ⟦Nightscape Pants=Pantaloni della Fuga Notturna⟧, 2 ⟦Nightscape Boots=Stivali della Fuga Notturna⟧ e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", "Ormai hai imparato parecchio, {name}; eppure c'è ancora molto da imparare. Ora tocca agli stivali di Cuoio Selvatico, la pietra angolare di ogni completo.\n\nQuesti stivali sono fatti per avvolgere il piede nella comodità, proteggendolo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca di muoversi senza far rumore.\n\nPer questo schema, mi serve un ordine di due pantaloni della Fuga Notturna e due stivali della Fuga Notturna. Mi serviranno anche due viti selvagge... non una sola. Quando hai tutto, fammelo sapere.", "L'ordine dei pantaloni, degli stivali e delle viti selvagge va completato prima che tu riceva lo schema, {name}. Hai finito?\n\nDal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in equilibrio sul filo del rasoio tra comodità e funzionalità. Con entrambe, possiamo creare oggetti che permettono a chi li indossa di ignorare la fatica che stroncherebbe chi porta merce di qualità inferiore.", "Ancora una volta hai completato un ordine complesso con l'abilità di un professionista espert<o/a>. Ti sei guadagnat<o/a> questo schema, e anche la mia gratitudine.", 0x1661d982, 0x0127e602, 0xbe8c2905, 0xa24c5cd2, 0x9e668019, "....." },
  [2852] = { "⟦Wild Leather Leggings=Gambiere di Cuoio Selvatico⟧", "Porta 2 Elmo di ⟦Turtle Scale=Scaglie di Tartaruga⟧, 2 ⟦Turtle Scale Bracers=Bracciali di Scaglie di Tartaruga⟧ e 2 Wildvine a Pratt McGrubben, a Feathermoon Stronghold.", "Ora che conosci le basi, sei pront<o/a> a padroneggiare lavori più complessi, {name}. Le gambiere di Cuoio Selvatico sono tra le protezioni di cuoio più robuste e potenti che esistano. Vita, cosce, polpacci e parti vitali: tutto riceve una protezione formidabile. Insieme al potenziamento della vite selvaggia, gli avventurieri che le possiedono ti ringrazieranno ogni volta che ti vedranno.\n\nPer questo schema, mi serve un ordine di due elmi di ⟦Turtle Scale=Scaglie di Tartaruga⟧, due bracciali di ⟦Turtle Scale=Scaglie di Tartaruga⟧ e due viti selvagge.", "Hai pronti i bracciali e gli elmi di ⟦Turtle Scale=Scaglie di Tartaruga⟧? Non dimenticare le due viti selvagge che mi servono!\n\nOrmai stai cominciando a capire la potenza che si cela nell'armatura di Cuoio Selvatico. Un'armatura che non ha limiti di impiego è quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di risorse per fare gli oggetti, non nella qualità dei prodotti finiti!", "Di nuovo, hai completato un ordine senza un difetto. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, {name}?\n\nEcco lo schema per le gambiere, insieme ai miei ringraziamenti. Fai tua questa conoscenza, e lascia che i tuoi prodotti finiti mettano a frutto la tua notevole abilità!", 0xb8e345b1, 0xd7de4f84, 0xe55cc30f, 0xb19aa2de, 0x098b510c, "....." },
  [2853] = { "Maestro del Cuoio Selvatico", "Consegna la ⟦Pratt's Letter=Lettera di Pratt⟧ a Telonis, il maestro conciatore di Darnassus.", "Be', {name}, sei la definizione stessa della diligenza. Resta un solo schema per l'armatura di Cuoio Selvatico; gli altri li padroneggi. Non ti farò faticare inutilmente per averlo. Te lo sei guadagnato pienamente, e anche di più... ma non posso dartelo io. Il mio maestro, colui che mi ha introdotto al mestiere, è quello che deve ricompensarti.\n\nPorta questa lettera a Telonis; insegna la conciatura a Darnassus. Mostragli la lettera e lascia che ti riconosca come suo pari, come faccio io.", "Salute, {race}... dal tuo aspetto capisco che sei <un/una> conciat<ore/rice> come me. Sei venut<o/a> ad attingere alle mie abilità, o forse hai altre faccende da sbrigare con me?", "Ah sì, ti manda Pratt. Anche se è un umano, a volte mi ricorda noi elfi della notte. La sua dedizione e il suo talento con il cuoio sono notevoli. Che ti lodi così in questa lettera è un segno di rispetto che riconosco.\n\nSo che ti ha insegnato l'arte del Cuoio Selvatico. Permettimi di concludere il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei mantelli di Cuoio Selvatico.", 0x0b03020c, 0xc396a4c4, 0xf694056c, 0xb2e5d777, 0x1241932d, "....." },
  [2854] = { "Armatura di Cuoio Selvatico", "Porta 10 ⟦Thick Leather=Cuoio Spesso⟧ a Jangdor Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "{name}, la tua abilità di conciat<ore/rice> ti precede. Possiedo conoscenze di conciatura che faresti bene ad acquisire... l'armatura di Cuoio Selvatico! Il Cuoio Selvatico attinge alle proprietà potenti e caotiche della vite selvaggia, che si trova nelle zone di vegetazione rigogliosa e addosso ad alcune delle creature che le abitano. Per un artigiano della tua abilità, l'armatura che se ne ricava non ha rivali, garantito.\n\nTe lo insegnerò, ma per un po' lavorerai per me. Il primo prezzo è semplicemente di dieci pezzi di cuoio spesso. Dopo, parleremo dei dettagli.", "Dobbiamo essere chiari: sarai mi<o/a> apprendista mentre impari l'arte dell'armatura di Cuoio Selvatico. Poiché la vite selvaggia è potente e caotica, conferisce un beneficio casuale ma forte all'armatura, già robusta, che realizzerai. Questa conoscenza, però, non è stata facile da acquisire per me.\n\nIl prezzo iniziale per cominciare è di dieci pezzi di cuoio spesso.\n\nFatto questo, passeremo al lavoro che dovrai svolgere per ottenere gli schemi.", "Be', {name}, sono lieto di averti come mi<o/a> apprendista. Hai fatto una scelta saggia come conciat<ore/rice>; chi fa uso di armature di cuoio farà a gara per averti, una volta che avrai imparato a padroneggiare l'arte del Cuoio Selvatico.\n\nMettiamoci al lavoro: da dove vuoi cominciare?", 0x053a8360, 0x4b71ee49, 0xea03e2b5, 0x692a5bf2, 0x7033c860, "....." },
  [2855] = { "⟦Wild Leather Shoulders=Spallacci di Cuoio Selvatico⟧", "Porta 6 Potenziamento d'Armatura Spesso e un Wildvine a Jangdor Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "Gli spallacci di Cuoio Selvatico sostengono benissimo la corporatura di chi li indossa, offrendo una protezione superiore alla parte alta delle braccia oltre che alle spalle. Come per tutta l'armatura di Cuoio Selvatico, quando la vite selvaggia viene cucita nel pezzo, vi infonde un potenziamento casuale ma molto potente.\n\nPer questo schema mi serviranno sei potenziamenti d'armatura spessi e una vite selvaggia. Non dovrebbe essere una richiesta troppo difficile da soddisfare per te.", "Hai i sei potenziamenti d'armatura spessi e la vite selvaggia che ti ho chiesto?\n\nConsidera la fabbricazione dei potenziamenti d'armatura una lezione di lavoro costante e affidabile: il metodo regolare che sviluppi esercitando il mestiere su questi potenziamenti affina l'abilità necessaria per il lavoro minuzioso che richiedono le armature di Cuoio Selvatico.\n\nOgni lezione ha uno scopo, {name}. È importante accoglierle tutte come si deve.", "Questi potenziamenti d'armatura sono di qualità solida, {name}. Se c'è una cosa che pretendo, non solo dal mio lavoro ma anche da quello di chi istruisco, è la qualità.\n\nTi sei guadagnat<o/a> questo schema; spero che ti porti le ricompense che ha portato a me.", 0x765de05b, 0x56e3ec88, 0x26cd7091, 0x81b4f39f, 0xf1b34312, "....." },
  [2856] = { "⟦Wild Leather Vest=Veste di Cuoio Selvatico⟧", "Porta 2 Pettorale Corazzato di ⟦Turtle Scale=Scaglie di Tartaruga⟧, 2 ⟦Turtle Scale Gloves=Guanti di Scaglie di Tartaruga⟧ e un Wildvine a Jangdor Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "La veste di Cuoio Selvatico è il pezzo fondamentale di ogni completo di Cuoio Selvatico. La struttura della veste e la vite selvaggia intrecciata in essa danno un capo che offre la massima protezione al torso e lascia che la potente magia scorra attraverso l'indumento.\n\nPer questo schema mi serviranno due pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧, due paia di guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧ e una vite selvaggia. Non è una lezione facile, ma hai di certo l'abilità per completarla.", "Hai i due pettorali corazzati e i guanti di ⟦Turtle Scale=Scaglie di Tartaruga⟧? E non dimenticare la vite selvaggia!\n\nGià con i primi schemi impariamo che i fondamenti della forma si trasferiscono bene a indumenti più difficili. Anche se sono oggetti diversi, la forma dei pettorali corazzati di ⟦Turtle Scale=Scaglie di Tartaruga⟧ ti prepara ai dettagli necessari per fare una veste di Cuoio Selvatico.\n\nMan mano che procedi con le lezioni, le abilità che ti insegno diventeranno arte.", "Sono pezzi davvero belli, {name}. La maestria e la cura messe nel farli mostrano che hai scelto di dedicarti completamente a questi compiti.\n\nHai soddisfatto le mie richieste, e con esse arriva la tua ricompensa. La conoscenza per fare le vesti di Cuoio Selvatico ora è tua!", 0x762367c6, 0x8af7a605, 0x0f2311f8, 0x068164b1, 0x32236632, "....." },
  [2857] = { "⟦Wild Leather Helmet=Elmetto di Cuoio Selvatico⟧", "Porta 2 Giubba della Fuga Notturna, 2 Banda della Fuga Notturna e un Wildvine a Jangdor Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "Un elmetto di Cuoio Selvatico offre a chi lo indossa una protezione superiore delle parti vitali della testa, senza sacrificare la comodità. Come per tutta l'armatura di Cuoio Selvatico, la vite selvaggia integrata infonde nella struttura dell'elmo una magia potente ma casuale. Chi indossa il cuoio vorrà di sicuro questo pezzo!\n\nPer questo schema mi serviranno due giubbe della Fuga Notturna, 2 bande della Fuga Notturna e una vite selvaggia. Completa questa lezione e lo schema sarà tuo!", "Mi servono quelle giubbe e quelle bande, e mi serve anche quella vite selvaggia, prima di condividere con te la conoscenza degli elmetti di Cuoio Selvatico.\n\nI copricapi sono molto ambiti tra gli avventurieri, che si tratti di una banda di una semplicità disarmante o di un elmetto che copre tutta la testa. I fondamenti per creare un copricapo di valore restano gli stessi, qualunque sia il suo aspetto.", "Questo equipaggiamento della Fuga Notturna che mi hai fornito soddisfa alla perfezione i requisiti che ti ho dato, {name}. Non mi aspetto niente di meno da <un/una> conciat<ore/rice> del tuo calibro.\n\nTi sei guadagnat<o/a> l'onore di creare gli elmetti di Cuoio Selvatico. Ti do questo schema volentieri, e spero che saprai trarne profitto.", 0xa93a2f88, 0xecd7e157, 0x125cca60, 0xe1bd53bd, 0xf8efbed3, "....." },
  [2858] = { "⟦Wild Leather Boots=Stivali di Cuoio Selvatico⟧", "Porta 2 ⟦Nightscape Pants=Pantaloni della Fuga Notturna⟧, 2 ⟦Nightscape Boots=Stivali della Fuga Notturna⟧ e 2 Wildvine a Jangdor Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "La tua conoscenza dell'armatura di Cuoio Selvatico cresce, {name}; eppure c'è ancora molto da imparare.\n\nGli stivali di Cuoio Selvatico sono la pietra angolare di ogni completo. Sono fatti per avvolgere il piede nella comodità, proteggendolo dai pericoli dell'avventura. Le suole morbide sono una benedizione per chi cerca di muoversi senza far rumore.\n\nPer questo schema, devi forgiare due pantaloni della Fuga Notturna e due stivali della Fuga Notturna. Mi serviranno anche due viti selvagge... non una sola. Quando avrai questi oggetti, procederemo.", "I pantaloni, gli stivali e le viti selvagge devono essermi consegnati prima che tu impari lo schema, {name}. Hai fatto quanto ti ho chiesto?\n\nDal primo paio di stivali che impariamo a fare, cominciamo a capire che uno stivale di qualità deve stare in equilibrio sul filo del rasoio tra comodità e funzionalità. Con entrambe, possiamo creare oggetti che permettono a chi li indossa di ignorare la fatica che stroncherebbe chi porta merce di qualità inferiore.", "Ancora una volta hai creato oggetti con l'abilità di un professionista espert<o/a>. Ti sei guadagnat<o/a> questo schema, e anche le mie congratulazioni.", 0x1661d982, 0xb3b1079c, 0xa6d99d3d, 0xd32a3cf5, 0x6f0c5592, "....." },
  [2859] = { "⟦Wild Leather Leggings=Gambiere di Cuoio Selvatico⟧", "Porta 2 Elmo di ⟦Turtle Scale=Scaglie di Tartaruga⟧, 2 ⟦Turtle Scale Bracers=Bracciali di Scaglie di Tartaruga⟧ e 2 Wildvine a Jangdor Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "Sei pront<o/a> a padroneggiare lezioni più complesse, {name}. Le gambiere di Cuoio Selvatico sono tra le protezioni di cuoio più robuste e potenti che esistano. Vita, cosce, polpacci e parti vitali: tutto riceve una protezione formidabile. Insieme al potenziamento della vite selvaggia, gli avventurieri che le possiedono ti ringrazieranno ogni volta che ti vedranno.\n\nPer ottenere questo schema, mi servono due elmi di ⟦Turtle Scale=Scaglie di Tartaruga⟧, due bracciali di ⟦Turtle Scale=Scaglie di Tartaruga⟧ e due viti selvagge.", "Hai pronti i bracciali e gli elmi di ⟦Turtle Scale=Scaglie di Tartaruga⟧? Non dimenticare le due viti selvagge che mi servono.\n\nOrmai stai cominciando a capire la potenza che si cela nell'armatura di Cuoio Selvatico. Un'armatura che non ha limiti di impiego è quasi inestimabile per un conciatore. Gli unici limiti stanno nella quantità di risorse per fare gli oggetti, non nella qualità dei prodotti finiti!", "Di nuovo, hai completato il mio compito senza un difetto. Forse un giorno sarò io a venire da TE in cerca di conoscenza, eh, {name}?\n\nEcco lo schema per le gambiere, insieme ai miei ringraziamenti. Fai tua questa conoscenza, e lascia che i tuoi prodotti finiti mettano a frutto la tua notevole abilità!", 0xb8e345b1, 0x612c1276, 0x3a102e0d, 0x792dd5a5, 0xf055bcf5, "....." },
  [2860] = { "Maestro del Cuoio Selvatico", "Consegna la ⟦Jangdor's Letter=Lettera di Jangdor⟧ a Una, la maestra conciatrice di ⟦Thunder Bluff=Picco del Tuono⟧.", "{name}, hai imparato tutto ciò che posso insegnarti. Resta però un ultimo schema per l'armatura di Cuoio Selvatico. Non ti farò faticare inutilmente per averlo; te lo sei guadagnato pienamente, e anche di più. Questo schema, però, non posso condividerlo liberamente con te.\n\nLa mia maestra, colei che mi ha introdotto al mestiere, è quella che deve ricompensarti. Porta questo biglietto a Una; insegna la conciatura a ⟦Thunder Bluff=Picco del Tuono⟧. Mostrale la lettera e lascia che ti riconosca come sua pari, come faccio io.", "Salute, {race}... dal tuo aspetto capisco che sei <un/una> conciat<ore/rice> come me. Sei venut<o/a> ad attingere alle mie abilità, o forse hai altre faccende da sbrigare con me?", "Ah sì, ti manda Jangdor. Mi fa piacere vedere che uno dei miei migliori allievi ora ha un allievo tutto suo.\n\nLa sua dedizione e il suo talento con il cuoio sono notevoli. Che ti lodi così in questa lettera è un segno di rispetto che riconosco.\n\nSo che ti ha insegnato l'arte del Cuoio Selvatico. Permettimi di concludere il tuo addestramento con questo schema. Usalo bene; pochi al mondo conoscono i segreti dei mantelli di Cuoio Selvatico.", 0x0b03020c, 0x72f983eb, 0x9cfc7e82, 0xb2e5d777, 0x761c97b8, "....." },
  [2861] = { "Il compito di Tabetha", "Parla con Tabetha, ad ⟦Dustwallow Marsh=Acquemorte⟧.", "Si dice che Tabetha, una collega maga che vive nel cuore di ⟦Dustwallow Marsh=Acquemorte⟧, abbia un conto in sospeso con un certo troll delle sabbie di ⟦Zul'Farrak=Zul'farrak⟧. Se parli con Tabetha, potrà dirti di più.\n\nE porta con te qualche amico, {name}. Se Tabetha ti manda a ⟦Zul'Farrak=Zul'farrak⟧, non vorrai andarci da sol<o/a>.\n\nTroverai la casetta di Tabetha a ovest di Theramore, appena a nord delle Rovine dei Mazzapietra.", nil, "Esatto. Ho proprio un conto in sospeso con una troll. Anzi, più di uno. Le spezzerei tutte le ossa!\n\nVuoi aiutarmi?", 0x96c81b26, 0x67e27f0b, 0xaa525e99, nil, 0x80cd032f, "...m." },
  [2862] = { "Guerra ai Raspalegno", "Porta 10 Pelliccia di Gnoll Raspalegno a Hadoken Swiftstrider all'⟦Camp Mojache=Accampamento Mojache⟧.", "Gli gnoll... sono più di una seccatura. Sono una minaccia costante all'esistenza stessa di questo accampamento! Non importa se siano originari di Feralas o no: se non rafforziamo la nostra determinazione contro di loro, ci ritroveremo cacciati dall'intera regione.\n\nUltimamente gli attacchi degli gnoll contro l'accampamento si sono fatti più accaniti. Ci serve il tuo aiuto per sfoltire le loro file: portami dieci delle loro pellicce, e ti ricompenserò generosamente per il tuo impegno.\n\nVa'!", "Li respingiamo, eppure continuano ad attaccare! Qualcuno o qualcosa deve farli impazzire... oh, sei tornat<o/a>, eh, {name}? Hai le pellicce che mi servono per riscuotere la taglia?", "Questa è la prova di un buon inizio, {name}. Le tue capacità di soldato meritano un encomio.\n\nNon sei l'unic<o/a> a cui ho affidato questo compito. Molti prima di te li hanno combattuti, e in passato i nostri sforzi li hanno tenuti a bada. Di recente, però, i loro tentativi di spingersi a nord nella nostra zona d'influenza sono aumentati in modo drastico. Anche i loro attacchi sono diventati più feroci... quasi come se fossero disperati.\n\nHo un piano, però, {name}, che potrebbe sistemarli una volta per tutte...", 0xc1b743b5, 0x1ddcdda5, 0x9d52d80c, 0x6b0c27cf, 0xf34890ac, "....." },
  [2863] = { "Attacco agli Alpha", "Uccidi 5 Woodpaw Alpha e torna da Hadoken Swiftstrider entro un'ora.", "Il piano è abbattere in rapida successione diversi capi degli gnoll, gli Alpha, come si fanno chiamare. Se riusciamo a infliggere loro una devastazione così rapida e precisa, scateneremo il caos nelle loro file. Forse riusciremo anche a far entrare nelle loro teste dure e pulciose che possiamo distruggerli, e che lo faremo!\n\nVoglio che sia tu il messaggero della mia volontà: elimina cinque dei loro Alpha entro un'ora perché funzioni, {name}, o resteremo in questo stallo!", "Il tempo stringe, {name}! Se non sei qui a riferirmi che hai fatto fuori gli Alpha, stai perdendo tempo!", "Hai fatto ciò che ti ho chiesto, e per questo ti rendo onore. Prendi questa piccola ricompensa per i tuoi sforzi, {name}.\n\nCon le loro file sfoltite e i loro capi uccisi, gli gnoll ci penseranno due volte prima di assaltare l'accampamento. Ma la questione non è ancora chiusa...\n\nDeve esserci un motivo se gli gnoll sono stati spinti in uno stato così frenetico. Prima che abbiano la possibilità di riorganizzarsi, voglio scoprire cosa lo provoca.", 0x8dbc86ab, 0x3dfff3ba, 0xb852b226, 0x1fcc4718, 0xefd117c5, "....." },
  [2864] = { nil, "Parla con Tran'rek a ⟦Gadgetzan=Meccania⟧.", "Mio cugino Tran'rek è nei guai. Settimane fa mi ha promesso un carico di gusci di scarabeo e non me l'ha ancora consegnato. È mio cugino, quindi mi seccherebbe dover mandare qualcuno a ⟦Gadgetzan=Meccania⟧ a rompergli qualcosa.\n\nPuoi parlare con Tran'rek per me? Fagli sapere che deve preparare quella consegna prima che io faccia qualcosa di avventato.\n\n⟦Gadgetzan=Meccania⟧ è nel nord di Tanaris, a Kalimdor.", nil, "Ciao!\n\nOh, hai parlato con mio cugino Krazek? Come sta? Spero che ⟦Booty Bay=Baia del Bottino⟧ lo tratti bene...\n\nGusci di scarabeo, dici? Be'... lascia che ti racconti una storia...", 0x862f6956, 0x08fec570, 0x0c814a4b, nil, 0x87221180, "e..m." },
  [2865] = { "Gusci di scarabeo", "Porta 5 Guscio di Scarabeo Intatto a Tran'rek, a ⟦Gadgetzan=Meccania⟧.", "Gli scarabei di Tanaris hanno gusci durissimi! Così duri da usarli come materiale da costruzione per un sacco di cose. Tantissime cose!\n\nAnzi, quei gusci sono così utili... che gli scarabei sono stati cacciati quasi fino all'estinzione!\n\nIo so dove ci sono altri scarabei, e se mi prometti di portarmi i loro gusci, ti dico dove sono. Promesso?\n\nOk, gli scarabei hanno una colonia a ⟦Zul'Farrak=Zul'farrak⟧. Immagino che i troll non li caccino per i gusci.\n\nMa tu puoi farlo! Va' a ⟦Zul'Farrak=Zul'farrak⟧ e portami dei gusci intatti!", "Hai i gusci? Mio cugino a ⟦Booty Bay=Baia del Bottino⟧ ne aspetta un carico e sta perdendo la pazienza!", "Oh, fantastico! Li hai presi!\n\nGrazie, {name}. Mi hai salvato la vita!", 0xaeea837d, 0xb0792b2e, 0x1769c4e1, 0x29ff8a96, 0x096fb397, "....." },
  [2866] = { "Le ⟦Ruins of Solarsal=Rovine di Solarsal⟧", "Esplora le ⟦Ruins of Solarsal=Rovine di Solarsal⟧ e indaga sulla presenza dei naga.", "A sud di qui ci sono le ⟦Ruins of Solarsal=Rovine di Solarsal⟧, un luogo molto più antico dei tempi moderni. All'inizio abbiamo esplorato le rovine senza trovare nulla di rilevante, quindi le abbiamo lasciate in pace.\n\nMolto di recente, i naga Crestaostile hanno occupato queste rovine in numero allarmante. Sulle prime l'abbiamo considerato il preludio di un attacco. Anche se quella minaccia resta possibile, crediamo che stia succedendo qualcos'altro.\n\nVa' laggiù, esplora le rovine e cerca qualunque cosa ti salti all'occhio. Buona fortuna, {name}.", nil, "Esaminando il gazebo scopri alcune cose interessanti e insolite rispetto alle rovine circostanti.\n\nPrimo, il gazebo è chiaramente una costruzione più recente degli altri elementi delle rovine. Secondo, sui suoi lati è incisa una piccola serie di glifi; i glifi si ripetono secondo uno schema, ma per il resto origine e significato sono sconosciuti. Terzo, la pietra stessa del gazebo è calda al tatto.\n\nQuesto rientra di sicuro in ciò che «salta all'occhio» nella ricerca tra le rovine!", 0x1a50d962, 0xc3dae690, 0x5322883e, nil, 0x5f67c7ca, "...m." },
  [2867] = { "Ritorno a Feathermoon Stronghold", "Torna da Shandris Feathermoon a Feathermoon Stronghold e riferisci ciò che hai scoperto.", "Con la scoperta dello strano gazebo nel cuore delle ⟦Ruins of Solarsal=Rovine di Solarsal⟧, è giunto il momento di tornare a Feathermoon Stronghold e riferire alla generale Shandris Feathermoon ciò che è stato scoperto qui.", nil, "Bentornat<o/a>, {name}. Il tuo rapporto su questo gazebo è assai... inquietante. Sembrerebbe che, anche se i naga laggiù non stessero preparando un attacco, la loro presenza continua sia di cattivo auspicio per la nostra avanzata a Feralas. In ogni caso, ecco un compenso per la tua indagine.\n\nSembra che Feathermoon Stronghold abbia urgente bisogno di ulteriore aiuto contro i naga Crestaostile. Vorrei affidarti l'incarico, se te la senti. C'è molto da fare.", 0xeef1a527, 0x9e8c4317, 0xa7312d25, nil, 0x90a88c18, "...m." },
  [2869] = { "Contro i Crestaostile", "Porta 10 Scaglia di Naga Crestaostile a Latronicus Moonspear, a Feathermoon Stronghold.", "A questo punto la cosa migliore è dare per scontato che, qualunque cosa abbiano in mente i naga, prima o poi cercheranno di prendersi l'isola. Dobbiamo agire con decisione per contrastare questa minaccia prima che sia troppo tardi.\n\nPortami dieci scaglie dei Crestaostile in buone condizioni; come procurartele dovrebbe esserti ovvio. Ti farai le ossa sui naga per la prima volta, e la presenza dei naga sull'⟦Sardor Isle=Isola di Sardor⟧ ne uscirà indebolita: due prospettive che giocano entrambe a nostro vantaggio.", "{name}, se sei qui per far verificare il compito che ti è stato affidato, allora benissimo: sono dieci scaglie dei Crestaostile quelle che cerco. Se sei qui per fare due chiacchiere, al momento non ho tempo per simili futilità.\n\nSappi questo: noi elfi della notte non siamo guerrafondai. La nostra razza è votata alla conservazione della pace e dell'armonia. Questo però non significa che non proteggeremo i nostri interessi in modo attivo. È il mio dovere verso la generale Feathermoon e verso la roccaforte.", "Sì, sì, queste scaglie sono più che soddisfacenti. Anzi, credo che le manderò a Pratt perché le esamini. Forse saprà ricavarne qualcosa di utile.\n\nQuanto a te, ho un'altra missione da affidarti. Ma prima, ecco la tua ricompensa per le scaglie. Il tuo servizio costante alla generale e a Feathermoon Stronghold tutta è una benedizione di fronte alle avversità.", 0xbaae3916, 0x04b7ffdc, 0xeb518da8, 0xfcde299e, 0x7ea356dc, "....." },
  [2870] = { "Contro lord Shalzaru", "Elimina Lord Shalzaru, poi porta la ⟦Mysterious Relic=Reliquia Misteriosa⟧ che ha rinvenuto a Latronicus Moonspear, a Feathermoon Stronghold.", "{name}, nuovi rapporti degli esploratori ci hanno dato un'idea precisa della catena di comando dei naga. Tra le loro file ci sono dei nobili, e sono loro a dare tutti gli ordini.\n\nIn particolare, abbiamo identificato uno dei nobili più crudeli: lord Shalzaru. Gli esploratori riferiscono che lui stesso ha rinvenuto una strana reliquia durante un recente scavo dei naga in una grotta a sud delle rovine principali, al di là dell'acqua, sull'⟦Isle of Dread=Isola del Terrore⟧.\n\nFerma tutto questo fermando lui, e portami la sua reliquia, così potremo studiarla.", "Abbattere lord Shalzaru farebbe di sicuro arretrare i loro piani di settimane, se non di mesi. Per di più, la reliquia che ha rinvenuto ci interessa senz'altro.\n\nHai portato a termine la missione che ti è stata affidata, {name}?", "Ben giocata, {name}! La fine di lord Shalzaru getterà i naga nello scompiglio per un bel po', se non per sempre. La minaccia che rappresentano è ora sotto il nostro controllo più di quanto lo sia mai stata, e dobbiamo ringraziare te.\n\nEcco altro denaro della taglia dal tesoro della roccaforte: ti sei guadagnat<o/a> ogni singolo rame. Tu e i tuoi siete sempre i benvenuti a Feathermoon Stronghold, amic<o/a> mi<o/a>.\n\nUn'ultima cosa prima che tu parta, {name}... se potessi...", 0x5abae5df, 0x7d196789, 0x1ba18bcf, 0x9dbe60bd, 0x94b155f8, "....." },
  [2871] = { "La consegna della reliquia", "Consegna la ⟦Mysterious Relic=Reliquia Misteriosa⟧ a Vestia Moonspear, a Feathermoon Stronghold.", "Se fossi così gentile da consegnare la reliquia a mia moglie Vestia, te ne sarei grato. Non è solo un'ottima sacerdotessa per la nostra comunità, ma anche una delle studiose più erudite che troverai in giro. Io non ci capirei niente di questo congegno nemmeno se ci fosse in ballo una scommessa. Mia moglie invece, se qualcuno può capire cos'è questa cosa, è lei... e noi dobbiamo saperlo!\n\nÈ appena dietro la curva, senza dubbio a studiare. Grazie, {name}.", "Sì, posso aiutarti?\n\nUn momento, tu sei <il/la> {class} che sta aiutando il generale Feathermoon e Latro con la minaccia dei naga, vero? Io sono Vestia, la moglie di Latro... ehm, cioè, di Latronicus. È un piacere conoscerti!\n\nScusami, sei qui per lavoro, naturalmente. Hai qualcosa per me... da parte sua, per caso?", "Interessante... questo viene dalle ⟦Ruins of Solarsal=Rovine di Solarsal⟧, dici? Be', Latro ha ragione, devo darci un'occhiata. A prima vista non sembra originario delle rovine. D'altra parte, non è di fattura naga... non qualcosa di così alieno.\n\nCi vorrà del tempo per studiare questo oggetto. Quando avrò finito le mie ricerche, forse farò ricorso ai tuoi talenti, se sarai da queste parti.\n\nTieni, prendi uno di questi oggetti che abbiamo in più; spero che ti sarà utile!", 0x9554d08d, 0x0650d9f2, 0x4aa6c818, 0xd2302486, 0x691ff389, "....." },
  [2872] = { "Il debito di Stoley", "Parla con Stoley al ⟦Steamwheedle Port=Porto degli Spargifumo⟧.", "Il mio vecchio amico Stoley mi deve una bottiglia di rum molto speciale. Fa il barista al ⟦Steamwheedle Port=Porto degli Spargifumo⟧, a Tanaris, Kalimdor, e mi ha promesso che il rum di lì è più forte di qualsiasi cosa si trovi a ⟦Booty Bay=Baia del Bottino⟧. È così sicuro di sé che dice che, se assaggio quel rum e non gli do ragione, mi raddoppierà i soldi che mi deve!\n\nBe', credo che non sia più tanto sicuro come l'ultima volta che ci siamo parlati, e ora ha paura di darmi quel rum. Ma io non mi tiro indietro da una scommessa, quindi perché non vai a parlargli tu per me...", nil, "Ah, così hai parlato con MacKinley, eh?\n\nNon è come pensa lui! Non ho paura di dargli un po' di rum di sentina degli Spargifumo...\n\nÈ che non ho più rum da dargli!", 0x5fe16894, 0x0eecc166, 0x10ebc4de, nil, 0x2b1e2d44, "...m." },
  [2873] = { "⟦Stoley's Shipment=Spedizione di Stoley⟧", "Porta la ⟦Stoley's Shipment=Spedizione di Stoley⟧ a Stoley, al ⟦Steamwheedle Port=Porto degli Spargifumo⟧.", "Devo a \"Sea Wolf\" MacKinley, a ⟦Booty Bay=Baia del Bottino⟧, un po' di rum per saldare una scommessa, ma il rum mi è finito! Il capitano Cuergo mi ha rubato l'ultima spedizione e la tiene nascosta in quella città pirata cinta di mura, a sud.\n\nSe riesci a trovare la mia spedizione di rum e a riportarmela, potrò dimostrare a MacKinley che l'alcol di Kalimdor straccia quello di ⟦Booty Bay=Baia del Bottino⟧!", "Hai trovato la mia spedizione di rum, {name}?", "Fantastico, grazie per la spedizione! Ora io e MacKinley possiamo finalmente saldare la nostra scommessa.", 0xebea37eb, 0x90075e4c, 0xd6d71b9a, 0x77e5cbb1, 0x532d7415, "....." },
  [2874] = { "Consegna a MacKinley", "Porta la ⟦Stoley's Bottle=Bottiglia di Stoley⟧ a \"Sea Wolf\" MacKinley, a ⟦Booty Bay=Baia del Bottino⟧.", "Grazie ancora per l'aiuto, {name}. Ecco una bottiglia di rum di sentina degli Spargifumo. Portala a MacKinley, così potrà finalmente mettere da parte le sue strambe convinzioni sull'alcol di ⟦Booty Bay=Baia del Bottino⟧.", "Allora, Stoley ha sganciato il mio liquore?", "Mm, assaggiamolo...\n\nNon ci posso credere! Questa roba è... terribile! Fantastico!\n\nBe', immagino che Stoley possa tenersi i soldi che mi deve. Ha mantenuto la parola sul rum di sentina degli Spargifumo. Quella roba è densa come la ghiaia e brucia come la lava!", 0x6a990bcc, 0xb6815583, 0x3a92f2f5, 0xfdfa4434, 0xdd7d2488, "....." },
  [2875] = { "RICERCATO: Andre Firebeard", "Porta la testa di Andre al capo della sicurezza Bilgewhizzle, al ⟦Steamwheedle Port=Porto degli Spargifumo⟧.", "Il vile pirata Andre Firebeard è ricercato per crimini contro gli Spargifumo e ⟦Gadgetzan=Meccania⟧.\n\nPer decreto del consiglio di governo, chiunque legga il presente è autorizzato a usare la forza letale durante la cattura di Andre e dei suoi complici.\n\nPer ulteriore decreto, qualora Andre risultasse deceduto, o altrimenti indisposto, al momento della sua udienza, la sua testa potrà fungere da procuratore, e la consegna di tale testa al capo della sicurezza Bilgewhizzle costituisce un contratto vincolante ed esigibile.", "Hai l'aria un po' stordita. Hai letto i nostri documenti legali?", "Ah, la testa di Andre. Quindi, alla fine, al processo ci arriverà!\n\nTi sono molto grato, {name}. Ora, se firmi qui, posso emetterti il pagamento per i servizi resi.\n\nNon preoccuparti delle clausole in piccolo. Sono innocue, e... comunque non credo esista una lente d'ingrandimento abbastanza piccola da leggerle.", 0xc88ca7ef, 0x26984e62, 0x0a8a207a, 0xd8992961, 0x7b9eba8f, "....." },
  [2876] = { "Gli orari delle navi", "Mostra lo Ship Schedule a un'autorità del ⟦Steamwheedle Port=Porto degli Spargifumo⟧.", "Questa pergamena contiene gli orari delle spedizioni tra il ⟦Steamwheedle Port=Porto degli Spargifumo⟧ e ⟦Booty Bay=Baia del Bottino⟧. Vi sono riportate le spedizioni passate e future, insieme ai nomi delle navi, con delle grandi \"X\" accanto ai viaggi di alcune navi e annotazioni come \"GRAN BOTTINO\" e \"SCONTRO DURO\" accanto ad altre.\n\nQualcuno al ⟦Steamwheedle Port=Porto degli Spargifumo⟧ vorrebbe vedere questo documento.", "Sei senza fiato. Hai qualcosa da dirmi?", "Oh, cielo, questo sembra un elenco di partenze e arrivi delle navi, con date e orari precisi e tutto il resto! Se il capitano di una nave pirata ci mettesse le mani sopra, avrebbe di che sbizzarrirsi!\n\nDici di averlo preso a un pirata? Be', questa sì che è una notizia preoccupante...\n\nGrazie, {name}. Sono contento che tu gliel'abbia tolto, e sono contento che quel pirata ora stia mangiando la polvere!", 0xaf794933, 0x3f74c8bd, 0x53de1d3d, 0x4efbf817, 0xfe6ccd46, "....." },
  [2877] = { "Pulizia al ⟦Skulk Rock=Tumulo Strisciante⟧", "Uccidi 10 Green Sludge e 10 Jade Ooze, poi torna da Fraggar Thundermantle al ⟦Aerie Peak=Picco dell'Aquila⟧.", "Noi Granmartello ricordiamo il passato, più dei nostri fratelli di ⟦Ironforge=Forgiardente⟧. Se vuoi farti degli amici qui, devi sporcarti le mani per noi!\n\nL'⟦Horde=Orda⟧ ha abbandonato le sue posizioni nelle Entroterre intorno al ⟦Skulk Rock=Tumulo Strisciante⟧, che ora è invaso da melme e fanghiglie schifose. Abbiamo dei progetti per quella zona, ma prima ci serve una squadra di pulizia che ci apra la strada.\n\nEd è qui che entri in gioco tu, raggio di sole! Scendi laggiù, fai fuori dieci Green Sludge e dieci Jade Ooze, poi torna a fare rapporto da me. In marcia!", "Non provare a trattare sulla missione, {race}! Se gli dei avessero voluto quelle melme morte, avrebbero già fatto il miracolo, no?!", "Ma guardati, che dai una mano ai Granmartello! Sei <un/una> {class} d'azione, e qui è l'azione che rispettiamo.\n\nLa tua piccola missione di pulizia è molto più importante di quanto pensi. Con qualcuno che sfoltisce melme e fanghiglie, estenderemo la nostra sfera d'influenza in un attimo. Ecco, prendi qualcosina, oltre ai nuovi amici che hai trovato qui al ⟦Aerie Peak=Picco dell'Aquila⟧!", 0x6eb9a3b3, 0x9cea9fad, 0x047d59fd, 0xf3a93aaa, 0x8efbe603, "....." },
  [2879] = { "Il ⟦Stave of Equinex=Bastone di Equinex⟧", "Carica il ⟦Troyas' Stave=Bastone di Troyas⟧ e trova l'Equinex Monolith.", "Questo bastone potrebbe essere il ⟦Stave of Equinex=Bastone di Equinex⟧! Il ⟦Stave of Equinex=Bastone di Equinex⟧ è in realtà una chiave, che serve ad aprire l'Equinex Monolith nelle ⟦Ruins of Ravenwind=Rovine di Corvovento⟧, sulla terraferma a ovest dell'⟦Dream Bough=Albero dei Sogni⟧.\n\nTrova le quattro fiamme che ardono ancora in quelle rovine: Samha, Imbel, Byltan e Lahassa. Raccogli la loro essenza e poi, stando accanto all'Equinex Monolith, usa le essenze per caricare il bastone. Se è davvero il ⟦Stave of Equinex=Bastone di Equinex⟧, riuscirai ad aprire il monolito e a prenderne un manufatto sacro.", "L'Equinex Monolith si erge silenzioso tra le rovine. Che cosa potrà custodire?", "Tenere in mano il bastone carico è quasi impossibile. Il suo potere ti rimbomba in tutto il corpo.\n\nAllunghi la mano verso la fredda superficie dell'Equinex Monolith...\n\nSi apre una piccola porta, che ti permette di infilare la mano e prendere il manufatto all'interno.\n\nFasci di luce riempiono l'area intorno all'Equinex Monolith.", 0x77176a60, 0xe2718895, 0xd421c18b, 0xea8f6acc, 0x5cf47a0c, "....." },
  [2880] = { "Taglia sulle collane troll", "Porta 5 Collana Tribale Troll a Fraggar Thundermantle, a ⟦Aerie Peak=Picco dell'Aquila⟧.", "Mettitelo bene in testa, {race}: NOI NON facciamo parte dell'⟦Alliance=Alleanza⟧! I Granmartello sono indipendenti, e il valore di qualcuno lo misurano dalle imprese e dalle azioni, non dalle chiacchiere di chi usa le parole per gonfiare la propria pigrizia!\n\nSe cerchi amici qui, prima dimostraci quanto vali! Gli schifosi troll che infestano i pendii delle Entroterre a volte portano addosso delle collane tribali. Portamene cinque e lo considereremo un passo nella giusta direzione per te.", "Voglio cinque di quelle collane tribali che i troll portano addosso. Se ti serve che te lo spieghi meglio, uccidendone uno hai buone probabilità di trovarne una!\n\nDimostra il tuo valore ai Granmartello!", "Ecco, così si parla! Visto? Queste collane dimostrano che sei dispost<o/a> a sporcarti le mani. Noi Granmartello lo apprezziamo in chi frequentiamo.\n\nContinua così e finirai per entrare nelle nostre grazie.", 0x53d7f0f7, 0xff9c1e7f, 0x03782ded, 0xc50f9dc0, 0x7300fcde, "....." },
  [2902] = { "Indagine sui Raspalegno", "Trova i piani di battaglia degli gnoll negli accampamenti gnoll a sud dell'⟦Camp Mojache=Accampamento Mojache⟧.", "Gli gnoll non sono proprio delle cime, ma avranno senz'altro una qualche strategia scritta sulle loro attività recenti. Se trovassimo quei piani, avremmo un'idea più chiara di cosa li agiti tanto.\n\nVoglio che tu torni dai Raspalegno e cerchi qualunque cosa somigli ai loro piani di battaglia. Devono avere qualcosa: i loro attacchi sono stati troppo coordinati per farne a meno. Trovali e torna da me quando li avrai.", nil, "Esaminando la mappa, scopri che si tratta dei piani di battaglia che vuole Hadoken Swiftstrider. Sulla mappa sono disegnate numerose frecce che forse rappresentano movimenti di truppe, anche se quasi tutte sembrano dirette a sud anziché a nord, dove si trova l'⟦Camp Mojache=Accampamento Mojache⟧.\n\nIn un'altra parte della mappa c'è il disegno di quello che ti sembra un grosso insetto di qualche tipo, con varie tacche sotto. A giudicare dagli gnoll, forse rappresenta le loro perdite contro quegli insetti sconosciuti...", 0x04f1cc63, 0x5e53674b, 0xc7a041ff, nil, 0x54b4b8f0, "...m." },
  [2903] = { "I piani di battaglia", "Porta i ⟦Woodpaw Battle Plans=Piani di Battaglia dei Raspalegno⟧ a Hadoken Swiftstrider, all'⟦Camp Mojache=Accampamento Mojache⟧.", "Ora che i piani di battaglia degli gnoll sono stati scoperti, non resta che riportarli a Hadoken Swiftstrider all'⟦Camp Mojache=Accampamento Mojache⟧. Forse lui, o qualcun altro lì, riuscirà a capire meglio cosa stanno tramando gli gnoll.", "Bentornat<o/a>, {name}. Sei riuscit<o/a> a trovare qualche prova concreta dei piani degli gnoll?", "Ah, è proprio quello che ci serviva. Anche se non sono molto abile a decifrare la maggior parte degli scarabocchi su questa mappa, ai miei tempi ho visto abbastanza piani di battaglia da capire cosa sta succedendo agli gnoll. Sembra che stiano combattendo una guerra su due fronti. Uno è contro di noi... ma pare che le loro energie principali siano rivolte contro un nemico a sud.\n\nQui c'è più di quanto sembri. Forse è il momento di scoprire chi sia davvero quest'altro nemico.", 0x77bc1308, 0x6b0805ca, 0x100a6847, 0xa2808308, 0xfa142672, "....." },
  [2904] = { "Un bel pasticcio", "Scorta Kernobee fino all'uscita di Clockwerk Run, poi fai rapporto a Scooty a ⟦Booty Bay=Baia del Bottino⟧.", "<Kernobee geme.> Co... Cos'è successo?\n\nL'ultima cosa che ricordo è che un gruppo di nani Ferroscuro mi ha catturato, mi ha pestato fino a ridurmi in fin di vita e poi mi ha buttato qui dentro con questi trogg schifosi.\n\nTirami fuori di qui, {name}!\n\nEcco il piano: guidami all'uscita; se ne usciamo vivi, tu vai a ⟦Booty Bay=Baia del Bottino⟧ e fai sapere a Scooty che sono andato a ⟦Ratchet=Porto Paranco⟧ per avvertire Tinkerwiz del coinvolgimento dei Ferroscuro nella costruzione di quella supermacchina.\n\nAndiamo!", "Eh? Kernobee è vivo??", "Credo che tu meriti una ricompensa per averci riportato Kernobee tutto intero, {name}. Se tornerai a Gnomeregan, questi potrebbero darti il vantaggio che ti servirà per sconfiggere quel traditore buono a nulla, Mekgineer Thermaplugg.", 0x63147a20, 0xac5b2106, 0x2a36e481, 0x0aeeadf6, 0x70f50dab, "....." },
  [2922] = { "Salva il cervello di Techbot!", "Porta il ⟦Techbot's Memory Core=Nucleo della Memoria di Techbot⟧ al mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "Quando la nostra amata città di Gnomeregan è caduta, una scintilla impazzita deve aver colpito la mia povera creazione, Techbot. Un tempo aiutava me e i miei colleghi con i suoi innumerevoli aggeggi e la sua scorta illimitata di informazioni, ma il suo cervello positronico si è polarizzato. Ora è negatronico... e i comportamenti di Techbot si sono invertiti. Vaga per Gnomeregan in preda alla frenesia!\n\nMa forse si può ancora salvare. Forse, se riesci a recuperare il nucleo della memoria di Techbot e a portarmelo, potrò scoprire la causa della polarizzazione e aggiustare il mio povero Techbot.", "Hai trovato Techbot? Hai recuperato il suo nucleo della memoria??", "Oh, è meraviglioso! Grazie, {name}! Mi metto subito al lavoro!!\n\nPovero, povero Techbot... Non abbatterti. Ti rimetteremo a posto.\n\nAllora, dove ho messo quella spina per la mia chiave girevole idro-cric...", 0x142b3f91, 0x989bf380, 0xa96aa51e, 0xa4a609b7, 0xbbc02495, "....." },
  [2923] = { "Il mastro inventore Overspark", "Parla con il mastro inventore Overspark, a ⟦Ironforge=Forgiardente⟧.", "Il mastro inventore Overspark è molto turbato per la sorte della sua creazione meccanica, Techbot. Ricordo Techbot come un aiutante gentile e utile per gli gnomi, ma Overspark mi dice che si è guastato.\n\nChe tristezza. Ma con un po' di fortuna forse si può aggiustare!\n\nParla con il mastro inventore Overspark, a Tinker Town, a ⟦Ironforge=Forgiardente⟧. Il tuo aiuto gli farebbe piacere.", nil, "Sì, è vero. Techbot è impazzito! Ti prego, puoi aiutarmi?", 0x50a40f08, 0x98ca0fa7, 0x226d20ab, nil, 0x8a6b241a, "...m." },
  [2924] = { "Essenziali Artificiali", "Porta 12 Essenziale Artificiale a Klockmort Spannerspan a ⟦Ironforge=Forgiardente⟧.", "Un componente meccanico quasi universale, l'essenziale artificiale, era utilissimo agli inventori e ai fabbri di Gnomeregan. Ma durante la fuga frenetica dalla nostra città, nessuno si è ricordato di portarne via neanche uno! E me ne serve una grande scorta per un lavoro che intraprenderò a breve.\n\nTi prego, entra a Gnomeregan e procurami degli essenziali artificiali. Li troverai nelle zone più profonde della nostra città, dentro contenitori chiamati estrapolatori artificiali.\n\nGrazie, {name}, e fai presto, ti prego!", "Hai gli essenziali artificiali?", "Li hai presi! Ora posso cominciare i miei nuovi esperimenti!\n\nNon so come ringraziarti, {name}! Il tuo coraggio ha fatto fare alla ricerca gnomesca un balzo da gigante!", 0xd3e977d4, 0xc9a42ec8, 0xf08a62a3, 0x88153ec4, 0x0a9e26a6, "....." },
  [2925] = { "Gli essenziali di Klockmort", "Parla con Klockmort Spannerspan a ⟦Ironforge=Forgiardente⟧.", "Un amico gnomo, Klockmort Spannerspan, mi ha mandato un messaggio da ⟦Ironforge=Forgiardente⟧. Dice che ha bisogno di aiuto per una missione pericolosa ma essenziale dentro Gnomeregan, la città un tempo grandiosa degli gnomi, ora contaminata e piena di gnomi impazziti e dei loro congegni.\n\nIo devo restare qui, ma mi si stringe il cuore a non poter aiutare il mio amico. Se puoi andare al posto mio, te ne sarò molto grat<o/a>.\n\nTroverai Klockmort a Tinkertown, a ⟦Ironforge=Forgiardente⟧.", nil, "Sì! Sì che mi serve aiuto per una missione dentro Gnomeregan. E tu sei proprio <il/la> {class} che fa al caso mio!", 0xd1472bfc, 0x7fe3166f, 0x3f0bf57e, nil, 0x578dfce4, "...m." },
  [2926] = { nil, "Usa la ⟦Empty Leaden Collection Phial=Fiala della Raccolta Vuota⟧ sugli Irradiated Invader o sugli Irradiated Pillager per raccogliere le scorie radioattive. Quando è piena, riportala a Ozzie Togglevolt, a Kharanos.", "Dall'incidente, Gnoarn non fa che pensare e parlare di ripulire Gnomeregan dall'infestazione dei trogg e di trovare una cura per il morbo che la affligge, {name}.\n\nPer fortuna, io e Razzle siamo vicini a una specie di cura... o a quello, o alla ricetta di un rum davvero potente. Non lo sapremo finché non lo proviamo! Naturalmente, per verificare la nostra teoria, ci serviranno alcune cose: nella fattispecie, le scorie dei trogg irradiati di Gnomeregan. Riempi questa fiala di quel bagliore verde e riportamela!", "Non vedi che qui stiamo cercando di curare un'intera specie di gnomi??! Ci serve altro bagliore verde!", "Ottimo lavoro! È giunto il momento di provare la nuova formula. Se funziona, non solo quello gnomo lebbroso catturato dovrebbe guarire, ma io dovrei ritrovarmi con una chioma folta! Stai indietro!", 0xf0c05f18, 0xdf69f0fb, 0xa76f5528, 0x20727b89, 0x9b4aacb0, "e...." },
  [2927] = { "Il giorno dopo", "Parla con Ozzie Togglevolt, a Kharanos.", "Non penserai che io sia sempre stato calvo, vero? No, <signore/signora>! È stata la fuga radioattiva di Gnomeregan a causare questa tragica perdita di capelli. Prima di quel giorno avevo l'unico gnomafro di tutta Azeroth.\n\n<Gnoarn agita il pugno in aria.>\n\nMaledetti quei maledetti sudici trogg! Che siano maledetti tutti!!\n\nForse non è troppo tardi, {name}. Potremmo ancora salvarla... la città, intendo! Parla con Ozzie Togglevolt a Kharanos. Lui e il suo socio Razzle stanno lavorando a una soluzione.", nil, "Pensavo che la perdita di quella splendida chioma sarebbe stata di sicuro la sua fine, ma è sopravvissuto!\n\nEro proprio accanto a lui quando è stato colpito dal raggio di radiazioni. Quelle deliziose ciocche castane sono cadute a terra a ciuffi! A grappoli! L'orrore è stato solo aggravato quando Gnoarn è andato completamente fuori di testa! Oh sì, fuori di testa, ti dico! Gnoarn si è toccato la testa calva, incredulo, e il suo sguardo gridava vendetta, {name}! Poi ha rivolto la sua rabbia contro i trogg!\n\n<Ozzie rabbrividisce.>", 0xf43f453e, 0xba99320a, 0x80d33f0e, nil, 0xbb58d6a8, "...m.", nil, nil, 0xb6251687, nil, nil },
  [2928] = { "Escavatori girotrivellomatici", "Porta ventiquattro Robo-mechanical Guts a Shoni a ⟦Stormwind=Roccavento⟧.", "È terribile, {name}. Non avremo abbastanza pezzi per portare la nostra flotta di escavatori girotrivellomatici fino a Dun Morogh.\n\nCi servono pezzi di ricambio, {name}. E quale posto migliore di Gnomeregan per trovare i ricambi per i nostri veicoli? Ho sentito che là dentro robot e macchinari vagano come bestiame al pascolo.\n\nVoglio che tu vada a Gnomeregan e faccia a pezzi quei robot. Portami le loro budella robotiche. Due dozzine dovrebbero bastare.", "Se fosse una gara, avresti già perso.", "Andrà benissimo, {name}. Un escavatore girotrivellomatico riparato; ne restano 398.", 0x7c11ff31, 0x78ec2936, 0x740676eb, 0x3fc85274, 0xaf06627a, "....." },
  [2929] = { "Il grande tradimento", "Va' a Gnomeregan e uccidi Mekgineer Thermaplugg. Torna dall'alto inventore Mekkatorque quando avrai finito.", "Mi fidavo di Thermaplugg, {race}. Non mi sarei mai aspettato che tradisse me e l'intero popolo degli gnomi. E per cosa? Potere? Ricchezza? Tutte cose che col tempo avrebbe avuto. Ora siamo stati cacciati dalla nostra casa e quel pazzo comanda. Il re del nulla...\n\nRiprenderemo Gnomeregan, {name}. Non ci fermeremo finché la città non sarà di nuovo sotto il nostro controllo. Se vuoi unirti alla nostra lotta, ti chiedo un compito semplice: uccidi il traditore. Distruggi Mekgineer Thermaplugg.", "Il compito è fatto? Ha implorato clemenza? Pietà??", "Mi piace pensare che l'ultima cosa che gli è passata per la testa mentre crollava a terra sia stato il tuo piede, {race}. Con Thermaplugg morto, i nostri piani per riprendere Gnomeregan sono un passo più vicini a diventare realtà.", 0xc7223d52, 0xfb52e324, 0x8bff6fc1, 0xada3365b, 0x5ff1117b, "....." },
  [2930] = { "Recupero dati", "Porta una ⟦Prismatic Punch Card=Scheda Perforata Prismatica⟧ al maestro meccanico Castpipe a ⟦Ironforge=Forgiardente⟧.", "Quando siamo fuggiti da Gnomeregan, abbiamo lasciato indietro un sacco di dati! Dati di vitale importanza!\n\nMi servono i dati su una scheda perforata prismatica, da un terminale ad alta sicurezza Matrix Punchograph 3005-D, nel profondo di Gnomeregan. Devi accedere al terminale, ma per farlo ti serve prima un'autorizzazione... e per averla devi accedere ai terminali a sicurezza inferiore, i modelli -A, -B e -C. E per fare QUESTO ti servono le schede perforate di sicurezza, a cominciare da quella bianca... e abbiamo lasciato tutte le schede perforate in città.\n\nÈ una catastrofe! Puoi aiutarci?", "Hai la scheda perforata prismatica??", "Ce l'hai fatta! Hai trovato la scheda perforata prismatica e recuperato i dati perduti! Dati vitalmente, criticamente, incommensurabilmente importanti, senza i quali non potevamo vivere un istante di più!\n\nIl tuo servizio agli gnomi sarà ricordato a lungo, {name}.", 0xb572ead8, 0x0d6cb3dd, 0x5be7a1ee, 0xa5d0b260, 0x9a4bbb5a, "....." },
  [2931] = { "L'incarico di Castpipe", "Parla con il maestro meccanico Castpipe a ⟦Ironforge=Forgiardente⟧.", "Il maestro meccanico Castpipe di ⟦Ironforge=Forgiardente⟧ ha bisogno di avventurieri! Sta organizzando delle squadre per rientrare a Gnomeregan in una missione di recupero dati della massima segretezza e importanza.\n\nCastpipe non sarà un membro della Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences come me, ma è comunque uno gnomo sveglio, quindi se pensa che sia importante, secondo i miei calcoli c'è un ottantaquattro per cento di probabilità che lo sia davvero!\n\nSono buone probabilità!", nil, "Sto organizzando missioni di estrazione dati a Gnomeregan. Se sei qui per questo, allora ascolta bene!", 0x95ff10c3, 0x3809bbd3, 0x4d68d41f, nil, 0x3d0d0c09, "...m." },
  [2932] = { "Un messaggio truce", "Raccogli Teschi di Scorzasecca e mettili sulla ⟦Nimboya's Pike=Picca di Nimboya⟧. Pianta la ⟦Nimboya's Laden Pike=Picca di Nimboya Carica⟧ in uno dei villaggi degli Scorzasecca nelle Entroterre, poi torna da Nimboya a Rovotorto.", "Un tempo i troll Scorzasecca erano alleati dell'⟦Horde=Orda⟧, ma hanno tradito Thrall... e devono essere puniti!\n\nEcco, prendi la mia picca e va' nelle Entroterre, lontano a nord. Le troverai a nord-est del ⟦Tarren Mill=Mulino di Tarren⟧, un villaggio in mano ai nostri alleati, i Reietti.\n\nQuando entri nelle Entroterre, dai la caccia ai troll Scorzasecca. Raccogli i loro teschi e pianta la mia picca nel terreno in uno dei loro villaggi più piccoli, Hiri'watha o Zun'watha.\n\nMostra loro che le loro azioni infami hanno delle conseguenze!", "Non hai portato a termine il mio compito, {name}.", "Mi è giunta notizia della tua impresa. Un'impresa truce, ma onorevole. Speriamo che gli Scorzasecca colgano il tuo messaggio.", 0xe9a63c1c, 0xc51a95c3, 0xd856795d, 0xd1a502bf, 0x2a9c90c2, "....." },
  [2933] = { "Bottiglie di Veleno", "Porta una ⟦Venom Bottle=Bottiglia di Veleno⟧ a uno speziale al ⟦Tarren Mill=Mulino di Tarren⟧.", "Queste bottiglie contengono un veleno verde e ripugnante.\n\nA giudicare dal numero di bottiglie in questo villaggio, gli Scorzasecca devono ritenerlo molto importante. Forse a uno speziale del vicino ⟦Tarren Mill=Mulino di Tarren⟧ farebbe piacere un campione.", "Salve, gentile {class}. La giornata è stata lunga e nemmeno un esperimento è riuscito... spero che tu mi porti buone notizie.", "Ah, e questo cos'è? Sembra veleno... di qualche creatura aracnide, direi. E dove l'hai preso?", 0x11490f01, 0xab4467b2, 0x215c3182, 0xc797364c, 0x24dc19cf, "....." },
  [2934] = { "⟦Undamaged Venom Sac=Sacca di Veleno Intonsa⟧", "Porta una ⟦Undamaged Venom Sac=Sacca di Veleno Intonsa⟧ allo speziale Lydon al ⟦Tarren Mill=Mulino di Tarren⟧.", "Mi serve un campione fresco del veleno che mi hai portato. I ragni da cui è stato raccolto devono vivere nelle Entroterre: da' loro la caccia finché non trovi una Sacca di Veleno Intonsa e portamela. Troverai molti ragni vicino alla città troll di Shadra'Alor.\n\nNon indugiare, {name}, perché la sacca di veleno dev'essere fresca quando me la consegni.", "Hai la Sacca di Veleno Intonsa, {name}? Non vedo l'ora di fare esperimenti con il suo veleno fresco, e ho già ordinato una partita di animaletti piccoli e tremendamente carini su cui provarlo!", "Oh, splendido! Il veleno è freschissimo e, ne sono certo, letale. Grazie!", 0x5787f979, 0xc1297cc7, 0x4adfb552, 0x3d50077f, 0x0b4e96a0, "....." },
  [2935] = { "Consulta il maestro Gadrin", "Parla con il maestro Gadrin al ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "Il veleno delle guardie della covata non era potente quanto quello che mi avevi portato all'inizio. Dev'essere venuto da un altro ragno.\n\nVoglio un campione fresco di quel veleno. Per scoprire da dove viene, devi consultare un troll che conosce bene gli Scorzasecca: il maestro Gadrin, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧. Recati a Durotar e parla con Gadrin. Con un po' di fortuna, saprà dove gli Scorzasecca prendono il loro veleno.", nil, "Ah, quindi vuoi veleno fresco dal ragno degli Scorzasecca, eh? Be', siediti... quello che devo dirti non ti piacerà.", 0xf6fc7c51, 0x0c77979e, 0x4a620828, nil, 0x49a2f284, "...m." },
  [2936] = { "Il dio ragno", "Leggi la tavoletta di Theka per scoprire il nome del dio ragno degli Scorzasecca, poi torna dal maestro Gadrin.", "Gli Scorzasecca venerano un dio ragno, ed è da lei che raccolgono il loro veleno più potente. Quindi, se vuoi il veleno, devi evocare il loro dio!\n\nPer farlo devi conoscere il suo vero nome, e quel nome è inciso su una tavoletta sepolta a Tanaris, nella città troll di ⟦Zul'Farrak=Zul'farrak⟧, in una tomba custodita da Theka il Martire.\n\nSconfiggi Theka, trova la sua tavoletta e leggila per scoprire il nome del dio ragno. Quando lo conoscerai, torna da me.", "Conosci il nome del dio ragno?", "Ah, Elortha no Shadra... pronuncia questo nome solo in un sussurro, perché dirlo ha un gran peso nei regni dello spirito.\n\nLo metterò su pergamena e creerò per te un incantesimo di evocazione...", 0x182b3641, 0xa80ea123, 0xcebbae4a, 0xf8b345e3, 0x1158639f, "....." },
  [2937] = { "Evocare Shadra", "Sconfiggi Shadra presso l'altare di Shadra'Alor, poi porta il suo veleno allo speziale Lydon, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Prendi la sua pergamena e leggila presso l'altare di Shadra'Alor, nel cuore del regno degli Scorzasecca, nelle Entroterre. Così evocherai Shadra, il dio ragno.", "Hai preso il veleno?", "Grande, ce l'hai fatta!", 0x1fe0036d, 0x8b5c3f22, 0x5866afa8, 0xe57d19f5, 0xbda6f99d, "....." },
  [2938] = { "Veleno per ⟦Undercity=Sepulcra⟧", "Porta la ⟦Faranell's Parcel=Busta di Faranell⟧ al maestro speziale Faranell, a ⟦Undercity=Sepulcra⟧.", "Il veleno che hai raccolto dal dio ragno degli Scorzasecca è davvero una scoperta! Con una sola goccia sono riuscito a uccidere quasi due dozzine di conigli. D'accordo, alcuni erano molto giovani e così piccoli da stare nel palmo di una mano, quindi sono certo che la loro resistenza alle tossine fosse bassa, ma non si può negare che questo veleno sia potente!\n\nVorrei che un campione venisse mandato al mio superiore, lo speziale Faranell, all'Apothecarium di ⟦Undercity=Sepulcra⟧. Sono sicuro che vorrà provarlo di persona.", "Mi hanno avvisato del tuo arrivo, {name}. Hai una busta per me?", "Ah, molto bene. Lydon ha detto che il veleno di questa busta è il più potente con cui sia mai venuto in contatto, e ora sta lavorando a nuovi usi.\n\nCon un po' di fortuna, ne troveremo molti.\n\nGrazie, {name}. Il tuo servizio alla Royal Apothecary Society è innegabile.", 0xb56a1970, 0x1d054150, 0xe4abef06, 0x979bec03, 0x29675c90, "....." },
  [2939] = { "In cerca di conoscenza", "Parla con Daryn Lightwind a ⟦Rut'theran Village=Rut'theran⟧.", "Le rovine di Feralas possono essere molto pericolose, ma hanno molto da raccontare su ciò che è accaduto qui.\n\nQualche giorno fa, frugando tra le macerie a sud, ho scoperto quello che sembra un normale bastone. Eppure non riesco a togliermi l'impressione che nasconda qualcosa di più. Angelas e io stiamo studiando i nostri libri, ma non troviamo nulla al riguardo.\n\nHo una collega a Darnassus che potrebbe dirci di cosa si tratta, {name}. Perché non vai a parlarle e vedi se può aiutarci?", nil, "Oh, quindi ti ha mandato Troyas Moonbreeze?\n\n<borbotta>...sempre a infastidirmi con le sue idee strampalate di aver trovato qualcosa di importante...\n\nSenti, {name}, sarò franca. Troyas crede sempre di aver trovato qualcosa di importante in quelle rovine. La verità è che tutto ciò che aveva davvero valore è stato probabilmente portato via tanto tempo fa dagli ogre o dalle arpie che ora vivono lì.\n\nPuoi dare un'occhiata, se vuoi, ma non so se troverai qui libri che ti possano aiutare.", 0x024ac15b, 0x27801142, 0x9fe00bd1, nil, 0x3aed02fb, "...m." },
  [2940] = { "⟦Feralas: A History=Feralas: Una Storia⟧", "Chiedi a Daryn Lightwind se puoi prendere in prestito il suo libro.", "Sembra che nessuno apra questo libro da moltissimo tempo. Le copertine sono parecchio consumate e le pagine ingiallite, ma esaminandolo ti accorgi che potrebbe essere proprio ciò che Troyas sta cercando.\n\nLo prendi, ma ti rendi conto che dovresti chiedere il permesso prima di prenderlo in prestito.", nil, "Quindi vorresti prendere in prestito ⟦Feralas: A History=Feralas: Una Storia⟧?\n\nFammi pensare...\n\nTi permetterò di prendere in prestito questo libro, {name}, ma solo se prima farai qualcosa per me.", 0xad9c7cd2, 0xcddd8fc5, 0xe6f4dd42, nil, 0x5487bf1c, "...m." },
  [2941] = { "Il prestito", "Porta la lettera a Curgle Cranklehop a Tanaris.", "Nella mia vita ho studiato molte materie, e la mia ultima passione sono le tartarabbie che popolano la spiaggia delle Entroterre. Ce n'è una in particolare che vorrei vedere, una tartarabbia gigante di nome Gammerita. Ci andrei io stessa, ma le mie ricerche mi trattengono qui. Credo che una sua immagine sarebbe la cosa migliore dopo vederla di persona.\n\nPorta questa lettera a Curgle Cranklehop a Tanaris. Ha creato per me un'invenzione capace di catturare un'immagine. L'ha chiamata \"istantanea\", mi pare...", "Una lettera... per me?", "Sei anche tu tra i tirocinanti di Daryn? È una storica molto preparata, {name}. Dovresti essere grat<o/a> di studiare sotto la sua guida.\n\nOra lascia che prenda il ⟦Super Snapper FX=Fotomatic FX⟧. Ti piacerà da matti!", 0xbf91965a, 0x1d265812, 0x87f31ae2, 0x84f49355, 0x65e2b535, "....." },
  [2942] = { "La Morrow Stone", "Riporta il Sasso Luccicante e il ⟦Stave of Equinex=Bastone di Equinex⟧ a Troyas Moonbreeze a Feathermoon Stronghold.", "Nel momento in cui togli il manufatto dal monolito, senti l'energia del ⟦Stave of Equinex=Bastone di Equinex⟧ cominciare a svanire.", "Sono lieto che tu sia tornat<o/a>, {name}. Non vedo l'ora di sapere cos'hai scoperto.", "Ho continuato a leggere da quando sei partit<o/a>, {name}. Questa pietra che hai trovato si chiama Morrow Stone. Anche se non sono ancora del tutto sicuro di quale sia il suo scopo, puoi star cert<o/a> che è qualcosa di grande importanza, se era nascosta così dentro l'Equinex Monolith.\n\nContinuerò i miei studi, e spero di poter contare su di te in futuro, {name}. Grazie per tutto il tuo aiuto.", 0x213c00cf, 0x61b177ca, 0x34c7ce0d, 0x1fded39e, 0xab29960a, "....." },
  [2943] = { "Ritorno da Troyas", "Consegna il libro a Troyas Moonbreeze a Feathermoon Stronghold.", "Eccolo, {name}. Ti prego, abbi cura del mio libro.\n\nOra sbrigati. Sono sicura che Troyas non vede l'ora che torni.", "Salve, {name}. Sei <stato/stata> a Darnassus?", "Hai portato un libro. Ottimo!", 0xff5baae2, 0xcfcf05ac, 0xb4df8e98, 0x38e98959, 0xab1081ea, "....." },
  [2944] = { "Il ⟦Super Snapper FX=Fotomatic FX⟧", "Usa il ⟦Super Snapper FX=Fotomatic FX⟧ per scattare una foto a Gammerita, poi torna da Daryn Lightwind a ⟦Rut'theran Village=Rut'theran⟧.", "Ecco a te il primo sguardo alla mia nuova invenzione, {name}. Ti basta puntare ciò che vuoi fotografare e premere il pulsante.\n\nCom'era quella creatura delle Entroterre che hai nominato? Gammerita? Be', buona fortuna a trovarla. Sono sicura che Daryn sarà molto contenta dell'istantanea che le porterai.\n\nComunque, ecco il Fotomatic. Divertiti!", "Allora, finalmente sei <tornato/tornata>, {name}. E hai portato l'aggeggio che Curgle ha costruito per me: perfetto.", "Bene! L'invenzione di Curgle è stata all'altezza delle aspettative.\n\nNon montarti la testa, ma sappi che sono soddisfatta del tuo lavoro, {name}.\n\nOra, dove ho lasciato quel libro...", 0x84039a5c, 0x80739a43, 0x92f501a3, 0x8dbec39e, 0x39c63785, "....." },
  [2945] = { "⟦Grime-Encrusted Ring=Anello Sudicio⟧", "Trova un modo per togliere lo sporco dall'⟦Grime-Encrusted Ring=Anello Sudicio⟧.", "Hai trovato quello che sembra un anello sul cadavere di uno dei nani ⟦Dark Iron=Ferroscuro⟧. È difficile dire che tipo di anello sia, però: terra e incrostazioni indurite lo ricoprono del tutto, ed è impossibile indossarlo. Ti sembra di scorgere la leggera lucentezza di un metallo prezioso, e forse persino il luccichio di una gemma sotto lo sporco.\n\nSe vuoi servirti di questo anello, dovrai trovare qualcosa per togliergli le incrostazioni.", "Il congegno gnomesco davanti a te porta una targa che lo chiama «La Lavatutto 5200». Dalle istruzioni sotto la targa si capisce che la macchina serve a togliere lo sporco da un oggetto. La macchina ha una fessura per le monete e, una volta messo dentro l'oggetto, accetta tre monete d'argento per avviare il processo.\n\nSembra proprio che l'anello incrostato che hai trovato prima sia la cosa giusta da provare in questa macchina!", "Metti l'anello nella Lavatutto 5200 e infili una moneta d'argento nella fessura.\n\nDalla macchina escono penosi rumori di ingranaggi, mentre comincia a scuotersi violentemente. Si può solo immaginare cosa stia succedendo all'anello là dentro...\n\nLa macchina si ferma di colpo e annuncia la fine con un semplice «Ding!». Lo scomparto si apre e rivela una scatolina incartata con cura, con un fiocco rosso. A quanto pare la Lavatutto 5200 fa anche i pacchetti regalo!", 0xf8a3263a, 0xc110cf2f, 0xab7d0f3c, 0x344cc60a, 0x3a2498fd, "....." },
  [2946] = { "Vedere cosa succede", "Porta i Dischi di Platino in Miniatura ai cancelli di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.", "Vogliamo che porti i dischi in miniatura che hai trovato ai cancelli sigillati di Uldum. Noi... non siamo sicuri di cosa succederà quando lo farai.\n\nSembra rischioso, certo, lo ammettiamo. Però potrebbe anche non succedere nulla. Forse dovrai usare i dischi su qualcosa. Forse le porte si aprono se hai i dischi con te. Sii pront<o/a> a tentare qualsiasi cosa, e a vedere succedere qualsiasi cosa.\n\nQuando avrai scoperto cosa succede, torna a ⟦Ironforge=Forgiardente⟧. Avremo un sacco di cose da analizzare quando avrai finito!", "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui significa qualcosa...", "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman ronzano e brillano nel tuo zaino. Una sensazione familiare di formicolio ti percorre le mani, mentre l'immagine di un altro guardiano di pietra prende vita davanti ai cancelli di Uldum.\n\n«Salve. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Plates of Uldum. Integra queste piastre nella struttura dei dischi e ripeti la sequenza d'accesso. Grazie.»", 0x7446c0c8, 0xec67bdb9, 0x5f1b449a, 0xd9076687, 0x2a4c8eea, "....." },
  [2947] = { "La restituzione dell'anello", "Puoi tenere l'anello, oppure cercare la persona a cui si devono il sigillo impresso e le incisioni all'interno della vera.", "Aprendo la scatola prodotta dalla Lavatutto 5200 trovi ciò che sospettavi: un anello lucente! Indossandolo, senti un potere magico scorrerti nel corpo.\n\nAll'interno della vera c'è un'impronta piccola ma ben riconoscibile del sigillo di ⟦Ironforge=Forgiardente⟧. Accanto sono incise tre piccole iniziali: \"TdK\". Potrebbero essere le iniziali del precedente proprietario, o forse quelle di chi ha forgiato l'anello. Tenere l'anello... o restituirlo a questa persona? Decisioni, decisioni...", "Ehi, calma, compare! Sono un uomo d'affari molto importante! Sono sicuro che il corriere è solo in ritardo con la consegna dell'affitto... aspetta... tu non sei il mio padrone di casa.\n\nMa certo che non lo sei, che sciocco! Sei venut<o/a> da me in cerca del miglior gioielliere di tutta ⟦Ironforge=Forgiardente⟧, uno che NON fa oggetti MALEDETTI! Sì!\n\nEhm... che cosa ti serve?", "Un anello, dici? Vediamo... sì, quell'anello l'ho fatto io, perbacco.\n\nPrima che Gnomeregan saltasse in aria, avevo una piccola bottega laggiù. Forse è uno di quelli che ho lasciato quando me la sono data a gambe; è un modello semplice, e ne ho fatti diversi così. Magari è di qualcuno che non è riuscito a uscirne.\n\nCe l'avevano i nani Ferroscuro? Be', questo aggiunge un nuovo strato di complotto ai nove strati che già girano. Forse alle autorità interesserebbe saperlo; con me è sprecato.\n\nOra, torniamo all'anello...", 0x9b2297a2, 0x8cbc1bad, 0x463d3a78, 0xf03132b6, 0x9157f220, "....." },
  [2948] = { "Migliorie da gnomo", "Porta l'⟦Brilliant Gold Ring=Anello d'Oro Scintillante⟧, un ⟦Silver Bar=Lingotto d'Argento⟧, un'⟦Moss Agate=Agata Muschiata⟧ e 30 monete d'argento a Talvash del Kissel a ⟦Ironforge=Forgiardente⟧.", "Senti, {name}, quell'anello è tuo, certo... ma io posso fartene uno migliore! Quel disegno, come ti dicevo, è davvero semplice. Ora sono molto più abile, e per la modica cifra di trenta monete d'argento te lo rimetto a nuovo! Be', un po' più di trenta, in realtà...\n\nAl momento sono in difficoltà: le mie scorte di materiali sono tutte esaurite. Se mi porti un lingotto d'argento e un'agata muschiata, aggiungerò all'anello un intreccio d'argento e agata che gli darà un tocco in più!\n\nFidati di me!", "Hai i materiali che mi servono? Non te li chiederei se la sorte non mi avesse voltato le spalle...", "Ah, proprio quello che mi serviva! Un giorno, quando uscirò da questo buco in cui mi trovo ingiustamente, farò per te, anzi per TUTTI, i ninnoli più belli di tutta Azeroth! Fino ad allora, grazie per essere stat<o/a> così sportiv<o/a> con i reagenti. Di solito per un anello di questa qualità chiederei dieci volte quello che ho chiesto a te...\n\nA proposito di anelli, ecco il tuo nuovo anello!", 0xaf868c64, 0x1a07e711, 0x8547b93f, 0x965ed2bb, 0xd8803d0d, "....." },
  [2949] = { "La restituzione dell'anello", "Puoi tenere l'anello, oppure cercare la persona a cui si devono il sigillo impresso e le incisioni all'interno della vera.", "Aprendo la scatola prodotta dalla Lavatutto 5200 trovi un anello lucente! Infilandolo, senti un potere magico scorrerti nel corpo.\n\nAll'interno della vera c'è un'impronta piccola ma ben riconoscibile del sigillo di Orgrimmar. Accanto ci sono delle lettere incise, ma anche dopo la pulizia si distinguono solo le prime tre: \"NOG...\"\n\nPotrebbero essere le iniziali del precedente proprietario, o forse quelle di chi ha forgiato l'anello. Tenere l'anello... o trovare \"NOG\"? Decisioni, decisioni...", "Uno penserebbe che troveremmo da soli un modo per superare quei piccoli gnomi schifosi. Scommetterei persino che quel marchingegno l'hanno rubato a noi, tanto per cominciare! Bah, quei viscidi, luridi... ehm, sì? Ti serve qualcosa?", "Un anello di Gnomeregan? Vediamo... non è mio, ma è interessante.\n\nLa faccenda di Gnomeregan... non poteva capitare a un branco di zucconi più simpatici. Per anni sono stati una barzelletta, e ora, quasi da un giorno all'altro, costruiscono macchinari migliori dei nostri?\n\nCe l'avevano i nani Ferroscuro? Questo è ancora più interessante! Sai, magari gli gnomi hanno rubato i loro folli progetti di golem e li hanno modificati. Quei Ferroscuro vorrebbero di sicuro una bella vendetta. Vale senz'altro la pena di indagare.\n\nSai, a proposito di quell'anello...", 0x9b2297a2, 0x8cbc1bad, 0xb84d59f3, 0xe22ff9bc, 0x4e5317a9, "....." },
  [2950] = { "L'anello rifatto di Nogg", "Porta l'⟦Brilliant Gold Ring=Anello d'Oro Scintillante⟧, un ⟦Silver Bar=Lingotto d'Argento⟧, un'⟦Moss Agate=Agata Muschiata⟧ e 30 monete d'argento a Nogg a Orgrimmar.", "No, no, no: non sto dicendo all'improvviso che l'anello è mio. Di solito non lo faccio, ma le tue informazioni sui Ferroscuro sono state utilissime. Ti migliorerò l'anello, meglio di quanto avrebbe mai potuto fare chiunque abbia fatto questa cosetta semplice. Probabilmente qualche gnomo...\n\nSe mi porti un lingotto d'argento, un'agata muschiata e trenta monete d'argento per il disturbo, aggiungerò all'anello un intreccio d'argento e agata che rafforzerà la magia al suo interno. Ti interessa?", "Hai i materiali che mi servono? Non posso migliorare questo disegno senza tutto quello che ti ho chiesto.", "Ecco il tuo anello, meglio di prima. Grazie ancora per le informazioni su quei nani ⟦Dark Iron=Ferroscuro⟧. Mi sembra una pista ragionevole per capire come quegli gnomi siano stati colpiti all'improvviso da un'ispirazione degna dei goblin.", 0xe9be8e28, 0xc0fbbadd, 0x13b26acd, 0x95624713, 0x48a5420b, "....." },
  [2951] = { "La Lavatutto 5200!", "Inserisci un Grime-Encrusted Item nella Lavatutto 5200, e assicurati di avere tre monete d'argento per avviare la macchina.", "Questo marchingegno spicca tra gli gnomi che resistono alla follia fuori dalla stanza. Una piccola targa sul congegno dice «La Lavatutto 5200», seguita da un testo:\n\n«Sporcizia e incrostazioni rovinano i tuoi gioiellini? La Lavatutto 5200 rimette lo splendore nello splendidoso! Inserisci l'oggetto che vuoi pulire e deposita tre monete d'argento nella fessura. Concedi alla Lavatutto 5200 un momento per l'operazione, e voilà! I tuoi oggetti di valore usciranno puliti e scintillanti!»", "A quanto pare il congegno ha bisogno di un qualche oggetto incrostato di sporcizia da pulire e di tre monete d'argento per mettersi in funzione. Se ci sono entrambe le cose, la Lavatutto 5200 dovrebbe funzionare...", "Inserisci l'oggetto incrostato di sporcizia e tre monete d'argento nella Lavatutto 5200. La macchina si risveglia in un tentativo frenetico di eliminare la sporcizia dall'oggetto sconosciuto. Dal cuore della macchina arrivano rumori violenti e assordanti di sbattimento. Il telaio di metallo del bestione cigola e geme mentre sobbalza da una parte all'altra...", 0x7df37d0f, 0xa77d0758, 0x66b0513f, 0x38e80812, 0x55272153, "....." },
  [2952] = { "La Lavatutto 5200!", nil, nil, nil, "Così come era partita, la Lavatutto 5200 si ferma di colpo. Dalla macchina si sente un semplice \"ding\" e la sua bocca si apre a spirale verso l'alto. Dentro la Lavatutto 5200 c'è una scatoletta legata con un fiocchetto. A quanto pare la macchina incarta l'oggetto dopo averlo liberato dalla sua crosta di sporcizia. Anche se la macchina non avesse funzionato, almeno ora l'oggetto è incartato in una bella scatola.\n\nBe', c'è un modo per scoprire se l'ha pulito o no...", 0x7df37d0f, nil, nil, nil, 0x6b359458, ".mmm." },
  [2954] = { "Il guardiano di pietra", "Scopri lo scopo dello Stone Watcher of Norgannon, poi interagisci con l'Uldum Pedestal nel deserto di Tanaris.", "«Salve. Sono un guardiano dell'ingresso. Se le Plates of Uldum non sono già integrate nel tuo insieme di dischi, non consentirò l'ingresso nel complesso di Uldum.»\n\nLa comparsa dello Stone Watcher of Norgannon dev'essere la reazione sperata quando ti hanno mandato nel deserto di Tanaris con i dischi di platino. Come ti è stato detto, prima di proseguire dovrai scoprire quale storia si cela dietro il guardiano di pietra.", "Prima di proseguire bisogna scoprire lo scopo del guardiano di pietra...", "La voce del guardiano di pietra risuona di potere e autorità:\n\n«I tuoi dischi ti saranno restituiti quando accederai al piedistallo. Quando avrai ottenuto le Plates of Uldum e le avrai integrate nel tuo insieme di dischi, potrai entrare nel complesso.»", 0xb5f90fe3, 0xdfcdd726, 0x98d8abcb, 0xa2bcd4ef, 0xa04cfcc1, "....." },
  [2962] = { "L'unica cura è altro bagliore verde", "Va' a Gnomeregan e riporta della ⟦High Potency Radioactive Fallout=Ricaduta Radioattiva ad Alta Potenza⟧. Attenzione: la ricaduta è instabile e decade piuttosto in fretta.\n\nAl termine del compito, Ozzie vorrà anche la tua ⟦Heavy Leaden Collection Phial=Fiala della Raccolta Pesante⟧.", "Non solo il tuo campione era insufficiente come quantità, era anche impuro.\n\nCi serve altro bagliore verde. È evidente che i trogg non sono abbastanza irradiati per le nostre esigenze. Dovrai andare a Gnomeregan e riportare della ricaduta radioattiva, presa direttamente alla fonte. Parlo delle melme, dei predatori in agguato e degli orrori irradiati. Attenzione: contenere questo tipo di ricaduta è difficile. Potrebbero servirti diversi tentativi con la fiala prima di raccogliere un campione adatto.", "Mmh, non brilli. È un buon segno.", "<Ozzie ti esamina.> Notevole, hai ancora tutti gli arti. Ora vediamo cosa sa fare questa roba!", 0xc891dea0, 0x4e7ea0ad, 0x6fc2256f, 0x66e8e057, 0x6eeec372, "....." },
  [2963] = { "Presagi di Uldum", "Parla con lo storico Karnik nella Hall of Explorers di ⟦Ironforge=Forgiardente⟧.", "Di nuovo salve, {name}! La tua scoperta a Uldaman ha messo in fermento la ⟦Explorers' League=Lega degli Esploratori⟧. La Lega lavora per svelare i segreti dei dischi di platino in miniatura che hai trovato. Il tuo arrivo provvidenziale qui nella sala mi permette di dirti che forse siamo sulla pista giusta!\n\nLo storico Karnik ha scoperto indizi importanti sulle vere origini della ⟦Valley of the Watchers=Valle dei Guardiani⟧, nel deserto di Tanaris. Vorrebbe parlarti il prima possibile!", nil, "Sono felice che tu continui a interessarti all'esplorazione, {name}! Con il tuo talento naturale e il tuo fegato, potremmo svelare segreti che non avremmo mai creduto possibili!\n\nI Discs of Norgannon a Uldaman erano un archivio di conoscenze immense; ti è stato permesso di accedere solo agli strati superiori, per così dire, delle informazioni che custodivano. Si dice che i Creatori avessero altri archivi sparsi per tutto Azeroth. E questo ci porta a Uldum...", 0xb4588354, 0x552c0a0b, 0x0dfef97f, nil, 0xbb6292ae, "...m." },
  [2964] = { "Un compito futuro", "Parla con l'alto esploratore Magellas a ⟦Ironforge=Forgiardente⟧.", "Ebbene, {name}... per ora sembriamo arrivati a un vicolo cieco. Sappiamo cosa ci serve, le Plates of Uldum, ma non abbiamo idea di dove possano trovarsi. Dovremo fare parecchie ricerche per mettere a punto un piano d'attacco solido. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di partire per recuperarle.\n\nL'alto esploratore dev'essere informato, {name}; di certo vorrà anche ringraziarti di persona per aver aiutato ancora una volta la Lega.", nil, "Allora siamo tutti d'accordo: il miglior piano d'attacco è mettere tutto in sospeso finché non avremo ristretto le zone dove potrebbero essere nascoste queste piastre. Ci hai portati fin qui, {name}, e spero che sarai tu a tornare sul campo per aprire Uldum a tutti noi!\n\nNel frattempo, permettimi di darti questo compenso; dovrebbe coprire le spese che hai sostenuto per aiutarci, più qualcosina in più. Torna presto a trovarci... Uldum ci chiama!", 0xa21b81b7, 0x886ee345, 0xf6da6a06, nil, 0xa20f123f, "...m." },
  [2965] = { "Presagi di Uldum", "Parla con Nara Wildmane sull'⟦Elder Rise=Altura degli Anziani⟧ a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ah, {name}, che fortuna che tu sia tornat<o/a> da me. Le tue rivelazioni al sito di scavo di Uldaman hanno dato a noi saggi molto di cui discutere. Ne stavo parlando proprio con una delle druide, Nara Wildmane, quando mi sono reso conto che le sue passate avventure potrebbero essere di grande importanza per il prossimo passo da compiere.\n\nVorrei che le parlassi dei suoi viaggi nella ⟦Valley of the Watchers=Valle dei Guardiani⟧, nel deserto di Tanaris. Ti aspetta sull'⟦Elder Rise=Altura degli Anziani⟧.", nil, "Nel profondo del deserto di Tanaris c'è un luogo chiamato ⟦Valley of the Watchers=Valle dei Guardiani⟧. I dischi che hai recuperato... i loro glifi tradotti parlano di un luogo chiamato Uldum. Quasi tutti pensano che sia un mito.\n\nIo so che non è così; Uldum esiste. Ci sono stata. Be'... fuori, almeno.\n\nIl punto è questo, {name}: pensiamo che ci sia un legame tra i dischi e Uldum, e vogliamo che tu ci vada.", 0xb4588354, 0xbe3df8e8, 0x29622ce1, nil, 0xfe5763d3, "...m." },
  [2966] = { "Vedere cosa succede", "Porta i Dischi di Platino in Miniatura ai cancelli di Uldum, a Tanaris, e cerca indizi sul legame tra le due cose.", "Il saggio Truthseeker e io vorremmo che portassi i dischi in miniatura che hai trovato ai cancelli sigillati di Uldum. Noi... non siamo sicuri di cosa succederà quando lo farai.\n\nSembra rischioso, certo, lo ammettiamo. Però potrebbe anche non succedere nulla. Forse dovrai usare i dischi su qualcosa. Forse le porte si aprono se hai i dischi con te. Sii pront<o/a> a tentare qualsiasi cosa, e a vedere succedere qualsiasi cosa.\n\nScopri ciò che puoi, poi torna da me. Avremo molto di cui discutere.", "Questo piedistallo dall'aspetto familiare spunta dalla sabbia rovente. Forse la sua presenza qui significa qualcosa...", "Quando tocchi il piedistallo, i dischi in miniatura di Uldaman ronzano e brillano nel tuo zaino. Una sensazione familiare di formicolio ti percorre le mani, mentre l'immagine di un altro guardiano di pietra prende vita davanti ai cancelli di Uldum.\n\n«Salve. Sono un guardiano dell'ingresso. Ai dischi usati per l'accesso mancano i dischi d'ingresso corretti, le Plates of Uldum. Integra queste piastre nella struttura dei dischi e ripeti la sequenza d'accesso. Grazie.»", 0x7446c0c8, 0xec67bdb9, 0xdf0e40da, 0xd9076687, 0x2a4c8eea, "....." },
  [2967] = { "Ritorno a ⟦Thunder Bluff=Picco del Tuono⟧", "Parla con Nara Wildmane a ⟦Thunder Bluff=Picco del Tuono⟧.", "Tocchi di nuovo il piedistallo; i dischi di platino ricompaiono all'improvviso nel tuo zaino.\n\nOra che conosci la storia del guardiano di pietra e hai di nuovo con te i dischi, è giunto il momento di tornare a ⟦Thunder Bluff=Picco del Tuono⟧ e informare Nara Wildmane della tua scoperta.", "Bentornat<o/a>, {name}. Sei riuscit<o/a> a usare i dischi a tuo vantaggio, o è stato tutto inutile?", "Ti mancavano alcuni dischi? Curiosamente, sembra che i Discs of Norgannon siano solo parti dell'insieme completo, come le chiavi di un mazzo, per così dire.\n\nSe riuscissimo a trovare le Plates of Uldum, potremmo davvero accedere al complesso di Uldum. Non so se essere entusiasta di questa prospettiva o esserne terrorizzata.\n\nForse dovremo rischiare tutto per far sì che i segreti custoditi dalla terra, capaci di distruggerci tutti, restino tali: segreti.", 0xb5d4ecc4, 0xc2d0c05d, 0x81744d92, 0x2e60b4a9, 0xa1778115, "....." },
  [2968] = { "Un compito futuro", "Parla con il saggio Truthseeker a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ebbene, {name}... sembriamo arrivati a una sfortunata impasse. Sappiamo cosa ci serve, le Plates of Uldum, ma non abbiamo idea di dove possano trovarsi. Faremo delle ricerche e poi metteremo a punto un piano d'attacco solido. Ho un paio di idee su dove cominciare a cercare; spero proprio che presto ti chiederemo di unirti di nuovo ai nostri sforzi per scoprire la verità.\n\nIl saggio Truthseeker dev'essere informato, {name}; di certo vorrà anche ringraziarti di persona per aver risposto ancora una volta alla chiamata.", nil, "Allora siamo tutti d'accordo: la cosa migliore è aspettare finché non avremo ristretto le zone dove potrebbero essere nascoste queste piastre. Ci hai portati fin qui, {name}, e spero che sarai tu a tornare sul campo per affrontare i segreti di Uldum.\n\nNel frattempo, permettimi di darti questo compenso; dovrebbe coprire le spese che hai sostenuto per aiutarci, più qualcosina in più. Torna presto a trovarci... Uldum chiama tutti noi, giovane.", 0xa21b81b7, 0x657f6ac8, 0xa1458715, nil, 0xd483c647, "...m." },
  [2969] = { "Libertà per tutte le creature", "Con la Bamboo Cage Key, libera gli Sprite Darter dal recinto nell'accampamento dei ⟦Grimtotem=Totem Truce⟧. Almeno 6 Sprite Darter e Kindal Moonweaver devono sopravvivere.\n\nHai 6 minuti prima che Kindal decida che è ora di ritirarsi e la missione fallisca.", "Il lurido clan dei ⟦Grimtotem=Totem Truce⟧ sta catturando draghi fatati, {name}. Jer'kai e io non abbiamo idea di cosa vogliano farne, ma di certo non tramano niente di buono.\n\nNon siamo abbastanza forti da aprirci la strada fino all'accampamento e liberare i draghi prigionieri, ma forse con il tuo aiuto...\n\nSe sei dispost<o/a>, e hai qualche amico forte, libera le creature dalla gabbia con questa chiave e assicurati che fuggano vive. Sarò al tuo fianco per tutto il tempo. Jer'kai resterà qui.", "Non possiamo permettere che il clan dei ⟦Grimtotem=Totem Truce⟧ distrugga queste splendide creature. Devono essere liberate!", "Grazie a Elune, {name}! Sei una grande benedizione per noi e per i draghi fatati che hai salvato. Jer'kai e io non saremmo mai riuscite ad aiutare i draghi da sole: il tuo intervento negli affari dei Totem Truce non sarà dimenticato.\n\nOra parla con Jer'kai... io devo prepararmi alla nostra rappresaglia. Il fatto che i draghi fatati siano liberi non significa che lo resteranno. Jer'kai e io passeremo all'offensiva.", 0x60dfaf24, 0xd95d73c5, 0xcb35a513, 0xafa50ad5, 0x27463b33, "....." },
  [2970] = { "Fare giustizia", "Uccidi 12 Grimtotem Naturalist, 10 Grimtotem Raider e 6 Grimtotem Shaman, poi torna da Jer'kai Moonweaver a Feralas.", "Come ti ha già detto, ora Kindal e io porteremo la lotta ai ⟦Grimtotem=Totem Truce⟧. Insieme dovremmo riuscire comunque a eliminare qualche tauren senza correre grossi rischi, ma un aiuto ci farebbe piacere, se vuoi e puoi.\n\nHai visto l'accampamento qui sotto, ma ce ne sono altri a est. Con le tue tattiche, infliggi ai tauren più danni che puoi. Ci ritroveremo tutti qui dopo che avranno assaggiato le frecce di Kindal e le tue armi.", "Kindal ha bisogno di tempo per prepararsi, ma abbiamo già ucciso decine di nemici. Il clan dei ⟦Grimtotem=Totem Truce⟧ sa benissimo che siamo nella zona, e ci danno la caccia come vipere.\n\nFaranno tutto ciò che è in loro potere per staccarci la testa dal corpo. Sta' all'erta... ora che ti sei intromess<o/a>, verranno anche per te.", "Kindal aveva ragione su di te, {name}: hai davvero talento per queste cose. Come <avventuriero/avventuriera> sei più espert<o/a> di noi due messe insieme, e per questo ti ringraziamo.\n\nIl clan dei ⟦Grimtotem=Totem Truce⟧ è molto più ostile della maggior parte dei tauren... Mi chiedo se la loro stessa gente disapprovi le loro azioni. Non mi stupirebbe. Come probabilmente sai, molte razze di Azeroth hanno legami con controparti meno benevole.\n\nMa questo è un discorso per un altro giorno.", 0xe759ef95, 0x5507b0a4, 0x657cbf89, 0x01f4f7af, 0xf5841753, "....." },
  [2972] = { "Fare giustizia", "Porta l'⟦Jer'kai's Signet Ring=Anello con Sigillo di Jer'kai⟧ alla somma sacerdotessa Tyrande Whisperwind a Darnassus.", "Qui nelle terre selvagge, Kindal e io abbiamo ben poco con cui ricompensare il tuo aiuto, ma non vogliamo che tu ti senta poco apprezzat<o/a>. Prendi il mio anello con sigillo. Se mai ti troverai tra i rami di Teldrassil, va' al ⟦Temple of the Moon=Tempio della Luna⟧, nel cuore di Darnassus. Lì troverai la mia somma sacerdotessa, Tyrande Whisperwind. L'anello le farà sapere che stiamo bene e darà credito al tuo racconto.\n\nTi ringraziamo entrambe, {name}.", "Salve, <figlio/figlia> mi<o/a>. Ci fa piacere avere qui al tempio avventurieri più esperti. Se hai tempo, racconteresti una storia o due agli avventurieri più giovani? So che molti di loro trarrebbero beneficio dalla tua saggezza.\n\nPerdonami, che maleducata. Sei venut<o/a> al Tempio a chiedere il nostro aiuto e io ti impongo le mie richieste. Ti prego, perdonami. Dimmi cosa possono fare per te i servitori della Luce.", "È una storia straordinaria, {name}. Ci fa piacere che tu non abbia aiutato solo la stirpe dei draghi, ma anche una delle nostre sacerdotesse. Jer'kai ha fatto bene a mandarti da me. Mi assicurerò che le venga restituito il suo anello: presto alcune mie esploratrici partiranno in direzione di Feralas. Sarà un compito in più per loro durante la missione.\n\nGrazie ancora e, ti prego, sentiti a casa finché sei qui.", 0xe759ef95, 0x80a8a598, 0x107eafc3, 0x8b166337, 0x9a5eb049, "....." },
  [2973] = { "La lucentezza di un nuovo mantello", "Porta 10 Ala Iridescente di Drago Fatato a Krueg Skullsplitter all'⟦Camp Mojache=Accampamento Mojache⟧.", "Ben trovat<o/a>, {class}. Sono sceso fino a Feralas con i miei compagni, in missione per i nostri superiori di Orgrimmar.\n\nLa mia compagna Korrin adora i vestiti nuovi, perciò voglio farle un mantello nuovo adornato con le ali sottili dei draghi fatati. Puoi aiutarmi? I draghi fatati con le splendide ali che cerco stanno a ovest dell'⟦Camp Mojache=Accampamento Mojache⟧.", "I draghi fatati possono essere bestiole pericolose, se provocati. Sta' attent<o/a> quando hai a che fare con loro, {class}. E sta' ancora più attent<o/a> agli elfi della notte della zona. Quegli sciocchi seccatori tendono a rintanarsi anche loro nelle foreste.\n\nQuando avrai abbastanza ali, fammelo sapere: ti ricompenserò bene, puoi starne cert<o/a>!", "Magnifico, {class}! Andranno benissimo. Ce n'è abbastanza per fare un mantello a Korrin, e forse anche di più! Grazie.\n\nSpero che il viaggio non sia stato troppo pericoloso. Feralas non è nota per essere clemente, ma evidentemente te la sei cavata bene.\n\nGrazie ancora, {class}.", 0x2bae8b1f, 0x8f85dbac, 0xf48da494, 0xeb9d3196, 0x75713903, "....." },
  [2974] = { "Una scoperta sinistra", "Porta 20 Corno dei ⟦Grimtotem=Totem Truce⟧ a Krueg Skullsplitter all'⟦Camp Mojache=Accampamento Mojache⟧.", "Cosa!? Hai incontrato dei tauren in zona? Stai scherzando! Che aspetto avevano!?\n\nIl clan dei ⟦Grimtotem=Totem Truce⟧! Ne hai trovati alcuni? Belgrom, uno dei nostri superiori, si interessa alla loro gente... ha persino messo una taglia su di loro.\n\nDevi tornare là, {class}. Torna indietro e portami le loro corna... mucchi di corna, se ci riesci. Con i ⟦Grimtotem=Totem Truce⟧ non si scherza e non vanno sottovalutati. Torna là e uccidili; fa' che i fiumi di Feralas scorrano rossi del loro sangue oscuro.", "Prendi sul serio le mie parole, {class}: il clan dei ⟦Grimtotem=Totem Truce⟧ è malvagio. Se hai scoperto dove si trovano, allora tocca a te tornare là e sferrare il primo colpo contro il loro clan... prima che possano entrare nelle nostre terre, radere al suolo i nostri villaggi o saccheggiare i nostri territori.", "Sono buone corna, {class}. Ben fatto. Le prendo io e mi assicurerò di dirlo a Belgrom appena torneremo a Orgrimmar. Mi hai aiutato già due volte, e per questo hai la mia stima. Forse in futuro potrò aiutarti io! Buona fortuna.", 0x19acaa18, 0x3bb8eb7f, 0xe57e61d4, 0x902d12ef, 0x8d25b8ba, "....." },
  [2975] = { "Gli ogre di Feralas", "Rok Orhan, all'⟦Camp Mojache=Accampamento Mojache⟧, vuole che tu uccida 10 Gordunni Ogre, 10 Gordunni Ogre-Mage e 5 Gordunni Brute.", "Gli effetti della tribù di ogre Gordunni non passano certo inosservati da queste parti. Guardati intorno, {name}: la loro sola presenza sfregia questa terra. Dobbiamo ricacciarli indietro prima che si espandano ancora di più a Feralas.\n\nSegui il fiume verso nord e troverai il loro avamposto. Riduci il loro numero, {name}. Dobbiamo far capire loro che la loro razza qui non è gradita.", "Muoviti, {name}. O il compito che ti ho chiesto è troppo difficile?", "Eccellente, {name}. Col tempo, la terra guarirà. Non dobbiamo arrenderci.", 0xf4ef25e1, 0x2da654a4, 0x7826014c, 0x0c264015, 0x3680d0c7, "....." },
  [2976] = { "Una scoperta sinistra", "Porta la ⟦Crate of Grimtotem Horns=Cassa di Corna dei Totem Truce⟧ a Belgrom Rockmaul a Orgrimmar.", "Cosa?!\n\nAh, quindi ho parlato di una taglia, eh? Beh, così imparo a tenere la bocca chiusa, no?\n\nIl lavoro l'hai fatto tu, quindi immagino sia giusto che sia tu a raccoglierne la ricompensa più grande. Prendi le corna, le farò mettere in una cassa per te. Cerca Belgrom Rockmaul nella ⟦Valley of Honor=Valle dell'Onore⟧: vorrà sapere cosa hai visto e ti ricompenserà per il tuo duro lavoro.\n\nStammi bene, {class}, e grazie ancora per tutto quello che hai fatto.", "Sbrigati, {class}, ho molto da fare oggi.", "I ⟦Grimtotem=Totem Truce⟧!? Interessante. Dici di averli incontrati mentre cacciavi a Feralas? Davvero?\n\nI miei pari vorranno sentire le tue notizie, {class}. Raccontami di più e intanto ti conto le monete.\n\nE prima che tu vada, sappi che ti ringrazio per le informazioni che mi hai passato oggi.", 0x19acaa18, 0x0b354058, 0xfd2f5a60, 0x6657fe16, 0x079d9f20, "....." },
  [2977] = { "Ritorno a ⟦Ironforge=Forgiardente⟧", "Parla con lo storico Karnik a ⟦Ironforge=Forgiardente⟧.", "Tocchi di nuovo il piedistallo; i dischi di platino ricompaiono all'improvviso nel tuo zaino.\n\nOra che conosci la storia del guardiano di pietra e hai di nuovo con te i dischi, è giunto il momento di tornare a ⟦Ironforge=Forgiardente⟧ e informare la ⟦Explorers' League=Lega degli Esploratori⟧ della tua scoperta.", "Bentornat<o/a>, {name}. Sei riuscit<o/a> a usare i dischi a tuo vantaggio, o si è rivelata una caccia alle farfalle?", "Ti mancavano alcuni dischi? Curiosamente, sembra che i Discs of Norgannon siano solo parti dell'insieme completo, come le chiavi di un mazzo, per così dire.\n\nSe riuscissimo a trovare le Plates of Uldum, potremmo davvero accedere al complesso di Uldum! Immagina di esplorare il luogo dove lavoravano i Creatori senza doversi portare dietro una pala enorme!\n\nNon che ci sia niente di male nelle pale... o nello scavare...", 0x144eacea, 0xb620dcc9, 0x8d9f3fda, 0x32dd35e3, 0xdf62418e, "....." },
  [2978] = { "La ⟦Gordunni Scroll=Pergamena di Gordunni⟧", "Porta la ⟦Gordunni Scroll=Pergamena di Gordunni⟧ a Rok Orhan, all'⟦Camp Mojache=Accampamento Mojache⟧.", "Raccogliendo la pergamena sporca, noti che sembra raffigurare una specie di incontro o di cerimonia. Rok Orhan sarebbe interessata a questa pergamena, e a ciò che potrebbe significare per i Gordunni.", "Che cos'è questa?", "Questa pergamena... L'hai trovata all'⟦Gordunni Outpost=Avamposto dei Gordunni⟧?", 0x554179ae, 0xf2ae9223, 0x43ca625e, 0x1eb006e5, 0xb8e81d0b, "....." },
  [2979] = { "Cerimonia oscura", "Rok Orhan, all'⟦Camp Mojache=Accampamento Mojache⟧, vuole che tu trovi un ⟦Gordunni Orb=Globo Gordunni⟧.", "Sembrano i piani per una specie di cerimonia oscura, {name}. Da quel che riesco a capire, questo rituale è condotto dai signori-maghi Gordunni.\n\nTrova uno di questi signori-maghi e prendigli un globo.\n\nIl globo di un mago racchiude un grande potere, e ci aiuterà a scoprire di più su questa cerimonia e sulla magia che usano i Gordunni.", "Dobbiamo scoprire di più sul perché i Gordunni sono qui, {name}.", "Questo globo ci darà altre informazioni sui Gordunni... che poi useremo per pianificare la loro caduta, {name}.", 0x060947fa, 0x932d7c0e, 0xd39fd8ff, 0xa62d29eb, 0x400573ef, "....." },
  [2980] = { "Gli ogre di Feralas", "Rok Orhan, all'⟦Camp Mojache=Accampamento Mojache⟧, vuole che tu uccida 10 Gordunni Shaman, 10 Gordunni Warlock e 5 Gordunni Mauler.", "Ora che hai dimostrato di essere <un/una> ver<o/a> combattente, confido che tu abbia il coraggio di proseguire con il compito che ci attende.\n\nRaggiungi l'⟦High Wilderness=Altopiano Selvaggio⟧, a sud-ovest di qui. Lì si trovano alcune strutture abbandonate e distrutte, su terre che un tempo appartenevano agli elfi della notte. Cerca queste rovine, e quando vedrai gli alberi avvizziti e il terreno profanato, troverai i Gordunni. Respingili.\n\nQuesti ogre sono molto più forti di quelli che hai affrontato finora, {name}. Sta' all'erta.", "Hai trovato le rovine, {name}?", "Hai dimostrato di essere <un/una> alleat<o/a> affidabile e degn<o/a> di fiducia, {name}.", 0xf4ef25e1, 0x74a8f3bf, 0x8518f41b, 0x8268bddc, 0x5265cbe1, "....." },
  [2981] = { "Una minaccia a Feralas", "Belgrom Rockmaul vuole che tu parli con Rok Orhan all'⟦Camp Mojache=Accampamento Mojache⟧.", "Feralas è il luogo ideale per <un/una> {class} espert<o/a> che voglia mettersi alla prova. Una tribù di ogre chiamata Gordunni è la forza militare dominante, e il loro numero cresce. Vanno fermati prima che minaccino la nostra presenza a Feralas.\n\nUna guerriera che conosco, Rok Orhan, si trova all'⟦Camp Mojache=Accampamento Mojache⟧, a Feralas: va' da lei. Ti spiegherà meglio la situazione quando arriverai.", nil, "Allora ti manda Belgrom. Arrivi giusto in tempo, {race}.\n\nLascia che ti spieghi la situazione, poi potrai decidere se sei all'altezza della sfida... Ma se ti manda Belgrom, sono certa che il tuo coraggio sia fuori discussione.", 0xd950ff93, 0x52a53a53, 0xda33d9df, nil, 0x4b012670, "...m.", nil, nil, 0x52a7f7e7, nil, nil },
  [2982] = { "L'⟦High Wilderness=Altopiano Selvaggio⟧", "Angelas Moonbreeze vuole che tu uccida 8 Gordunni Warlock, 8 Gordunni Shaman e 8 Gordunni Brute.", "Anche se è pericoloso, io e Troyas stiamo studiando le rovine che coprono le foreste di Feralas.\n\nUltimamente, però, Troyas va da solo all'⟦High Wilderness=Altopiano Selvaggio⟧, e sono davvero in pensiero per lui. Gli ogre Gordunni hanno preso possesso di quella zona, e non vedono di buon occhio chiunque entri nel loro territorio.\n\nSperavo che fossi dispost<o/a> a raggiungere le rovine a sud-est e a sgominare un po' di ogre. Rendi la zona un po' più sicura per il mio Troyas, e te ne sarò immensamente grata.", "Sta' attent<o/a> con i Gordunni, {name}. La loro magia sembra devastare la terra stessa su cui si trovano.", "Ti sono davvero grata per averlo fatto per me.\n\nOra, ti prego, non dire una parola a Troyas su questa faccenda...", 0x94041dc4, 0xe372a610, 0xb1f60eb1, 0xdcbfe250, 0x198dd9f4, "....." },
  [2983] = { "Il richiamo del fuoco", "Trova Kranal Fiss nelle ⟦Barrens=Savane⟧.", "È passato un po' di tempo dalla tua ultima prova, {name}. Finora sei <stato/stata> paziente nei tuoi studi, ma è ora che tu conosca poteri più grandi... è ora che tu conosca il vero potere. L'elemento del fuoco è tuo, se sei dispost<o/a> a pagarne il prezzo.\n\nCerca Kranal Fiss nelle ⟦Barrens=Savane⟧. Vive in una piccola dimora a nord del ⟦Crossroads=Crocevia⟧, ma fai attenzione: se hai raggiunto quelle maledette terre degli elfi della notte, sei andat<o/a> decisamente troppo oltre.", nil, "Mmm, ti ha mandato Swart da me, vero?\n\nBe', di Swart ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte alla prossima sapta: la sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere e ora ne vuoi ancora. Pazienza, {name}. Ricorda ciò che ti ha insegnato la terra. Potere e distruzione arriveranno facilmente, ma devi comunque sapere quando trattenere la mano.", 0x53f3b76b, 0xb1158d84, 0x0c7a07c5, nil, 0xbe75ed09, "...m." },
  [2984] = { "Il richiamo del fuoco", "Trova Kranal Fiss nelle ⟦Barrens=Savane⟧.", "È passato molto tempo dall'ultima volta che sei <stato/stata> mess<o/a> alla prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la distruzione... e il caos. L'elemento del fuoco è tuo da comprendere, se sei pront<o/a> a pagarne il prezzo.\n\nCerca Kranal Fiss nelle ⟦Barrens=Savane⟧. Vive in una piccola dimora a nord del ⟦Crossroads=Crocevia⟧, ma fa' attenzione: se sei arrivat<o/a> nelle terre degli elfi della notte, sei andat<o/a> troppo lontano.", nil, "Mmm, ti ha mandato Narm da me, vero?\n\nBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte alla prossima sapta: la sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere e ora ne vuoi ancora. Pazienza, {name}. Ricorda ciò che ti ha insegnato la terra. Potere e distruzione arriveranno facilmente, ma devi comunque sapere quando trattenere la mano.", 0x53f3b76b, 0xb1158d84, 0x0f02e651, nil, 0xd20cd47c, "...m." },
  [2985] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle ⟦Barrens=Savane⟧.", "Sembri pront<o/a> per la tua prossima prova, {name}. Sei stat<o/a> paziente nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle ⟦Barrens=Savane⟧. Si trova lungo la costa orientale, a sud del ⟦Southfury River=Fiume Furialunga⟧ e di ⟦Ratchet=Porto Paranco⟧. La troverai lì, nella sua capanna da pesca. Buona fortuna, {name}.", nil, "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x2f9a1a5e, nil, 0xf9228c66, "...m." },
  [2986] = { "Il richiamo dell'acqua", "Trova Islen Waterseer nelle ⟦Barrens=Savane⟧.", "È passato molto tempo dalla tua ultima prova, {name}. Finora hai mostrato pazienza nei tuoi studi, ma è giunto il momento di imparare di più. È giunto il momento di conoscere la purezza dell'acqua.\n\nCerca Islen Waterseer nelle ⟦Barrens=Savane⟧. Si trova lungo la costa orientale, a sud del ⟦Southfury River=Fiume Furialunga⟧ e di ⟦Ratchet=Porto Paranco⟧. La troverai lì, nella sua capanna da pesca. Buona fortuna, {name}.", nil, "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", 0x1f0e11aa, 0x52f30fbd, 0x7363625e, nil, 0xf9228c66, "...m." },
  [2987] = { "⟦Gordunni Cobalt=Cobalto dei Gordunni⟧", "Orwin Gizzmick, all'⟦Camp Mojache=Accampamento Mojache⟧, vuole 12 ⟦Gordunni Cobalt=Cobalto dei Gordunni⟧.", "Sono appena arrivato qui a Feralas, e ho sentito dire che gli ogre Gordunni che abitano queste terre selvagge hanno dei minerali interessanti. Chissà cosa stanno tramando, ma di sicuro quella roba la proteggono per bene! Non la lasciano in giro, no: la seppelliscono, perché quelli come me non ci mettano le mani sopra.\n\nSe sei d'accordo, ti darò la mia pala. Va' all'⟦Gordunni Outpost=Avamposto dei Gordunni⟧ a nord di qui e dissotterrami un po' di Cobalto dei Gordunni. Cerca il bagliore blu, poi comincia a scavare!", "Sbrigati ad andare lassù e comincia a scavare!\n\nHo posti dove andare e gente da vedere: il tempo è denaro!", "Perfetto! Li porterò con me nei miei viaggi, {name}. Sono sicuro di trovare qualcuno disposto a pagare un bel gruzzolo per questo cobalto.\n\nTieni, prendi questo per il disturbo.", 0x8fe31774, 0xcd9a26c2, 0x2dd1e0e3, 0x59e88299, 0x4cc222f9, "....." },
  [2988] = { "Le gabbie degli Scorzasecca", "Controlla le gabbie nei due villaggi degli Scorzasecca, poi torna dal maestro dei grifoni Talonaxe.", "Il figlio del nostro grifone più possente è scomparso! L'erede di Swiftwing, Beccaguzzo, si è perso pochi giorni fa mentre cacciava con i genitori, e crediamo che siano stati i troll a prenderlo.\n\nDevi aiutarci! Perquisisci le gabbie nei due villaggi dei troll Scorzasecca e guarda se Beccaguzzo è lì.", "Hai perquisito le gabbie, {name}? Dobbiamo trovare Beccaguzzo!", "Beccaguzzo non era nei villaggi? Hm... questa è una brutta notizia. Quel grifone è destinato a guidare la prossima generazione di grifoni. Se è perduto, la forza e lo spirito della nostra flotta ne soffriranno immensamente.", 0xd2ed808e, 0x7500a89e, 0x0bd1ca1e, 0xc6517c8f, 0xae95575d, "....." },
  [2989] = { "L'⟦The Altar of Zul=Altare di Zul⟧", "Controlla la cima dell'Altare di Zul, poi torna dal maestro dei grifoni Talonaxe.", "Beccaguzzo non era con i troll Scorzasecca. Forse l'hanno preso i troll Ramovile. Va' all'Altare di Zul, al confine occidentale del territorio dei Ramovile, e cerca il cucciolo di grifone.", "Sbrigati, {name}! Se Beccaguzzo ce l'hanno i troll Ramovile, chissà cosa gli stanno facendo!", "Beccaguzzo non c'era? È una brutta notizia, ma è anche una buona notizia...\n\nÈ un bene che non fosse all'Altare di Zul, perché i troll Ramovile sono noti per i loro sacrifici.\n\nTi ringrazio per tutto il tuo aiuto, ma temo che ci aspetti un compito ancora più grande.", 0x17765c2d, 0x87ae2e16, 0x8dc2c1ee, 0xa11ece19, 0x348c2bb1, "....." },
  [2990] = { nil, "Porta la ⟦Sharpbeak's Feather=Piuma di Beccaguzzo⟧ a Thadius Grimshade nelle ⟦Blasted Lands=Terre Devastate⟧.", "Porta questa piuma a Thadius Grimshade, il divinatore. Ha lasciato il ⟦Aerie Peak=Picco dell'Aquila⟧ anni fa per inseguire conoscenze più oscure, ma nel suo cuore è ancora un Granmartello!\n\nE forse i suoi talenti possono aiutarci a trovare Beccaguzzo.\n\nQuesta piuma è stata presa dal nido dove dorme il piccolo grifone. Se la dai a Thadius, con un po' di fortuna potrà usare la sua magia divinatoria per trovare Beccaguzzo.\n\nBuona fortuna, {name}. Troverai Thadius nelle ⟦Blasted Lands=Terre Devastate⟧, nella torre dei maghi del ⟦Nethergarde Keep=Forte di Guardiafatua⟧.", "{name}, vieni a portarmi un dono?", "Ah, sì. Questa piuma appartiene a un grifone eccellente. Uno destinato a grandi cose... se riuscirà a diventare adulto senza danni.\n\nVuoi trovarlo? Allora ascolta bene, {class} coraggios<o/a>...", 0x544cdf02, 0xf32d217d, 0x7a4689be, 0x0c71e9f6, 0xe9dbc04a, "e...." },
  [2991] = { "Il ⟦Nekrum's Medallion=Medaglione di Nekrum⟧", "Porta il ⟦Nekrum's Medallion=Medaglione di Nekrum⟧ a Thadius Grimshade, nelle ⟦Blasted Lands=Terre Devastate⟧.", "Scoprirò dov'è il tuo grifone, ma prima devi fare qualcosa per me. A ⟦Zul'Farrak=Zul'farrak⟧ c'è un troll, Nekrum Gutchewer, che possiede un medaglione che vorrei tanto studiare. Portami quel medaglione e userò i miei poteri per trovare Beccaguzzo.\n\n⟦Zul'Farrak=Zul'farrak⟧ si trova al di là dell'oceano, a ovest, nel deserto di Tanaris.", "Hai il ⟦Nekrum's Medallion=Medaglione di Nekrum⟧, {name}? Al suo interno si celano poteri che non vedo l'ora di scoprire.", "Ah, il medaglione di Nekrum. Si dice che abbia dato al troll una vita innaturalmente lunga, ma a caro prezzo. Spero di scoprire un modo per sfruttarne il potere evitandone gli... spiacevoli effetti collaterali.\n\nMi hai reso un servizio, {name}. Ora manterrò la mia parte del patto.", 0xd0e71ef2, 0x69d044e5, 0x23900882, 0xb6e9fb8f, 0x5ceb3a7c, "....." },
  [2992] = { "La divinazione", "Attendi che Grimshade compia il rituale di divinazione.", "Fammi spazio mentre compio un rituale di divinazione. Troverò il legame tra la piuma che mi hai portato e il suo proprietario, e seguirò quel legame fino a Beccaguzzo in persona.\n\nCioè... lo farò, se tutto va secondo i piani. Altrimenti... faresti meglio a chiudere gli occhi.", nil, "Il rituale è riuscito. Ho visto Beccaguzzo e posso dirti come trovarlo.", 0xf42df580, 0xa6313eaf, 0x9aae3f04, nil, 0xd58e9db1, "...m." },
  [2993] = { "Ritorno nelle Entroterre", "Parla con il maestro dei grifoni Talonaxe.", "Beccaguzzo è tenuto in una gabbia, in alto su una rupe in cima a ⟦Jintha'Alor=Jintha'alor⟧, nelle Entroterre. La chiave della gabbia è in mano alla somma sacerdotessa dei troll Ramovile, la sacerdotessa immonda Hexx.\n\nEcco. Ho fatto la mia parte. Ti auguro buona fortuna nella tua impresa, {name}.", nil, "Hai parlato con Grimshade? Che cosa ha detto?\n\n...Cosa? Beccaguzzo è nelle mani dei troll Ramovile? È insopportabile! Dobbiamo organizzare una squadra per riprenderlo!", 0x5419b47b, 0x4ba254df, 0x0fa70323, nil, 0x98f33a86, "...m." },
  [2994] = { "Salvare Beccaguzzo", "Combatti fino alla cima di ⟦Jintha'Alor=Jintha'alor⟧, uccidi Vile Priestess Hexx per avere la chiave della gabbia di Beccaguzzo e salva Beccaguzzo.", "Dobbiamo salvare Beccaguzzo!\n\nFatti strada fino alla cima di ⟦Jintha'Alor=Jintha'alor⟧, nel cuore del territorio dei Ramovile, prendi la chiave della gabbia di Beccaguzzo alla sacerdotessa immonda Hexx e poi trova e salva Beccaguzzo!", "Salva Beccaguzzo!", "Swiftwind e Keenclaw sono tornati con il loro piccolo poco fa, e lo coccolano come genitori novelli. Vederli di nuovo insieme basta a far inumidire gli occhi persino a questo vecchio nano...\n\nNon potremo mai ripagarti abbastanza per ciò che hai fatto, {name}. I grifoni del Picco dell'Aquila, e i loro cavalieri, canteranno il tuo nome per molto, molto tempo.", 0x64daaa65, 0x7af19d1c, 0x68d07569, 0x180edb9f, 0x5cb3cadc, "....." },
  [2995] = { "Linee di comunicazione", "Oran Snakewrithe, a ⟦Undercity=Sepulcra⟧, vuole che tu vada nelle Entroterre e bruci i Highvale Records, il Highvale Report e le Highvale Notes.", "Il ⟦Quel'Danil Lodge=Padiglione Quel'Danil⟧ è un centro di comunicazione per gli alti elfi delle Entroterre. I loro ambasciatori lavorano per stringere rapporti con le altre razze, con cui condividono ciò che sanno dei troll Scorzasecca che abitano la parte meridionale delle Entroterre. Tutti i documenti di questi scambi sono custoditi al padiglione.\n\nNon ci serve che gli Highvale si facciano alleati, {name}.\n\nDistruggi i documenti degli Highvale. Dobbiamo bruciare le loro linee di comunicazione... letteralmente.", "Tenere isolati gli elfi Highvale è la chiave. Hai trovato il padiglione?", "Perfetto, {name}. Mentre gli Highvale cercano di recuperare le informazioni perdute, noi potremo isolare ancora di più le loro linee...", 0x0715ee1f, 0x3448961e, 0xb2af364f, 0x725c34a5, 0x7a1c4449, "....." },
  [2996] = { "In cerca di Strahad", "Parla con Strahad Farsan a ⟦Ratchet=Porto Paranco⟧.", "In passato ti ho insegnato delle abilità, ma è giunto il momento che sia un altro a istruirti. Si trova a ⟦Ratchet=Porto Paranco⟧ e il suo nome è Strahad. È umano, ma non lasciarti ingannare: non è debole. È potente, anche se forse è piccolo. Può insegnarti evocazioni più potenti: sento che sei pront<o/a>. Va' da lui, ora. È a ⟦Ratchet=Porto Paranco⟧... sopra la città portuale, accanto alla sua torre.", nil, "Una giornata piena a ⟦Ratchet=Porto Paranco⟧, vero? Quanto mi piace osservare la fatica di una città portuale. Tanto mistero, tanta avventura... tanta ignoranza.\n\nÈ odio quello che vedo nei tuoi occhi, {name}? Bene, lo metteremo a frutto.", 0x884bfbbe, 0x0c866240, 0x442728fe, nil, 0x44d961f5, "...m." },
  [2997] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧.", "Salve, {name}. So che sei impegnat<o/a> ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire a ⟦Ironforge=Forgiardente⟧ a parlare con una delle nostre più rispettate: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su cosa ci si aspetta da te.\n\nLa trovi al piano di sopra, nella Hall of Mysteries. Se non ci sei mai stat<o/a>, è nel Mystic Ward. Buona fortuna, {name}.", nil, "Ben trovat<o/a>, {name}. Spero che la Luce ti mostri il vero cammino e ti protegga dal male.", 0x85861feb, 0x04be03fc, 0x4e98a6c9, nil, 0x942f654d, "...m." },
  [2998] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Duthorian Rall a ⟦Stormwind=Roccavento⟧.", "Salute, <fratello/sorella>. Duthorian Rall, uno dei nostri paladini più influenti, parlava di te di recente. L'ho sentito dire che era ora di metterti un po' alla prova... e anche dire cose molto lusinghiere su come te la sei cavata finora.\n\nSe fossi in te, andrei a ⟦Stormwind=Roccavento⟧ a parlargli quando hai tempo. Di sicuro è nella ⟦Cathedral of Light=Cattedrale della Luce⟧: è lì che passa la maggior parte del suo tempo.", nil, "È bello qui a ⟦Stormwind=Roccavento⟧, non trovi?\n\nA dire il vero, non potevi arrivare in un momento migliore, {name}.", 0x85861feb, 0x0f3ca705, 0x35944d83, nil, 0x3fd2197e, "...m.", nil, nil, 0xa8a5e826, nil, nil },
  [2999] = { "⟦Tome of Divinity=Tomo della Divinità⟧", "Parla con Tiza Battleforge a ⟦Ironforge=Forgiardente⟧", "Salve, {name}. So che sei impegnat<o/a> ad aiutare la gente di Dun Morogh, ma quando hai tempo dovresti salire al piano di sopra a parlare con una delle nostre più rispettate: Tiza Battleforge. È da lei che vanno i paladini più giovani quando è il momento di imparare di più sulla Luce e su cosa ci si aspetta da te.", nil, "Ben trovat<o/a>, {name}. Spero che la Luce ti mostri il vero cammino e ti protegga dal male.", 0x85861feb, 0xafea0004, 0xdacc6f34, nil, 0x942f654d, "...m." },
})
